t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "向北經過{area:918}回到礦坑：狗頭人掘地工在礦坑內工作。",
		["Back to {area:108}"] = "返回{area:108}",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon."] = "迪菲亞巡路者和迪菲亞拳匪在{area:20}巡邏；迪菲亞路霸（17級）成對巡邏其南邊和東邊的丘陵：把牠們分開拉。鐵匠鋪內的{area:1581}入口是小隊地城。",
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}."] = "迪菲亞搶劫者和迪菲亞強奪者佔據了{area:108}西邊的農場，位於海岸道路和{area:20}之間。",
		["Fill the vial at the farm's well"] = "在農場的井裝滿小瓶",
		["Fill the vial at the well"] = "在井邊裝滿小瓶",
		["Fly or ride to {zone:1453}. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids)."] = "飛往或騎往{zone:1453}。訓練師：{object:2100}（戰士、盜賊）、大教堂（聖騎士、牧師）、{object:2101}（法師、術士）、公園（德魯伊）。",
		["Fly or ride to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "飛往或騎往{zone:1453}。{npc:376}在光明大教堂內。",
		["Fly or ride to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "飛往或騎往{zone:1453}。{npc:5480}在{object:2100}訓練戰士；{npc:6089}和{npc:6090}一起站在那裡的{object:2152}旁。{npc:6090}會為了他的杯子和你決鬥。",
		["Follow the road north. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west."] = "沿道路向北走。{npc:233}站在屋外，{npc:235}在屋內，{npc:253395}在西邊的穀倉裡。",
		["For {npc:11026} in {zone:1453}'s {object:28027}"] = "為了{zone:1453}{object:28027}的{npc:11026}",
		["For {npc:266} in {area:69}, Redridge"] = "為了赤脊山{area:69}的{npc:266}",
		["Further north along the road. The Furlbrows sit by their burned farm. Collect the oats from the Sacks of Oats in the fields as you go."] = "沿道路繼續向北。法布隆夫婦坐在被燒毀的農場旁。沿途從田裡的一袋燕麥收集燕麥。",
		["Gnoll Paws"] = "豺狼人的爪子",
		["Harvest Watchers"] = "看守傀儡",
		["Hearthstone on cooldown? Follow the road north-east."] = "爐石在冷卻中？沿道路往東北走。",
		["Kobold Diggers"] = "狗頭人掘地工",
		["Level 12, 14 and 16 spells"] = "12、14和16級法術",
		["Longshore Murloc Gills"] = "長灘魚人鰓",
		["Murloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time."] = "灘行魚人和魚人襲擊者散布在礦坑北邊的海灘。牠們血量低時會逃跑：一次只拉一隻。",
		["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine."] = "在摩爾森農場北邊。迪菲亞捕獸者和迪菲亞走私者在礦坑外紮營。{object:290}在礦坑東邊的廢墟旁。",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "只有在艾爾文森林拾取了{item:1972}時：右鍵點擊它",
		["Ride to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "騎往{zone:1453}。那裡沒有薩滿訓練師：從{object:28027}搭乘{area:2257}前往{zone:1455}，向{npc:258098}學習，然後搭地鐵回來搭船。",
		["Riverpaw Gnolls and Scouts roam the hills between the coast and the {area:916}."] = "河爪豺狼人和河爪斥候在海岸與{area:916}之間的丘陵遊蕩。",
		["Riverpaw Miners"] = "河爪礦工",
		["Sacks of Oats"] = "一袋燕麥",
		["Shaman training"] = "薩滿訓練",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "向西南前往海岸，在{area:918}西邊。河爪礦工在採石場工作。",
		["The gnoll hills"] = "豺狼人丘陵",
		["The north coast"] = "北部海岸",
		["The western farms"] = "西部農場",
		["The {area:113}"] = "{area:113}",
		["West of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "在薩丁農場西邊。看守傀儡和麥田傀儡在田裡工作；牠們掉落等軸彈簧、陀螺穩定器、{item:732}，有時掉落{item:255155}。{npc:573}是20級稀有怪，在此遊走：別惹它。這一圈的每一段都持續擊殺血牙野豬和碎屍鳥。",
		["Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way back."] = "幼年血牙野豬和碎屍鳥在農場周圍的田野遊蕩：回程時順便收集肝臟和燉肉用的肉。",
		["{area:20} and the Defias hills"] = "{area:20}與迪菲亞丘陵",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{zone:1439}「收集解藥」（6123）所需的{item:2449}：向鍊金術供應商{npc:1313}購買；草藥學家可改在那裡採集",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}，來自{area:20}周圍的箱子",
		["{item:6529}, from {npc:5494}"] = "{item:6529}，向{npc:5494}購買",
		["{item:729}: Fleshrippers"] = "{item:729}：碎屍鳥",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234}和{npc:821}站在石塔頂端。{npc:491}在塔內，{npc:878}在山丘南側，旅店和獅鷲管理員{npc:523}旁邊。",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}，在{npc:878}旁邊",
		["{npc:523}; skip the free flight it offers"] = "{npc:523}；跳過它提供的免費飛行",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494}在{object:2096}西側的運河邊出售釣魚用品；{npc:267118}在港口釣魚，就在前往船的路上。",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}，巫師聖所：{quest:1861}",
		["{quest:153}: every Defias drops them"] = "{quest:153}：所有迪菲亞都會掉落",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "在{area:2362}",
		["Back north-east into the mountains to the crystal."] = "向東北回到山中的水晶那裡。",
		["Back south"] = "往南回去",
		["Back to {npc:11802}"] = "返回{npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702} (by way of {area:442})."] = "回到{area:2361}找{npc:11802}，然後飛往{area:702}（途經{area:442}）。",
		["Bears and the Blackwood camp"] = "熊與黑木營地",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "黑木探路者和黑木風語者佔據{area:442}東南方的營地。",
		["Blackwood furbolgs"] = "黑木熊怪",
		["Boat to {zone:1453}"] = "搭船前往{zone:1453}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "施放{spell:18960}。{npc:11802}在{area:2361}。神殿靈珠在{area:2361}下方{area:656}湖底的容器裡：拿一個到西北方的{area:2362}，在那裡使用並與{npc:11799}交談。然後從{area:2361}飛回{area:442}。",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "施放{spell:18960}。{npc:11802}在{area:2361}；如果還沒有那裡的飛行路線就學一下。",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "爬上{area:447}東邊的山脈；{object:175524}在一處岩架上。",
		["Crawler Legs"] = "蟹腿",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "護送她離開月刃；瑟瑞希爾在{zone:1440}接受繳交",
		["Fill the tube at the moonwell in the village"] = "在村子的月井裝滿試管",
		["Fine Moonstalker Pelts"] = "優質月夜猛虎毛皮",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "從{area:442}飛往{area:702}，搭傳送門上到{area:1658}找{npc:4217}。",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "沿海岸向東北前往{area:443}。{quest:951}散落在廢墟中；雷鱗侍從、雷鱗巫師和雷鱗戰士佔據著廢墟，雷鱗獸王在岸邊走動。",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "沿海岸向南經過{area:447}：一個{quest:4728}在古樹之林西邊的岸上，另一個在更南邊的{area:450}附近。更西南方的灰霧智者和灰霧潮行者（18-20級）之間還有三具骨骸：指南把它們留到最後一輪，那時你的等級更接近牠們。",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "沿丘陵向北到{area:456}，再往上到瀑布。北岸還有兩具擱淺的骨骸：在{area:443}附近和{quest:954}北邊。",
		["Follow the road north."] = "沿道路向北。",
		["Follow the road south. {quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "沿道路向南。{quest:948}是古樹之林的古樹；{npc:270269}和{npc:11218}睡在他旁邊。",
		["Grell Earrings"] = "劣魔耳環",
		["Grizzled Scalps"] = "灰色頭皮",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "灰斑薊熊在林地周圍的丘陵遊蕩；{quest:1003}就在林地西邊的熊群之中。",
		["Hearth to {area:442}"] = "用爐石回到{area:442}",
		["Hearthstone on cooldown? Follow the coast road back south."] = "爐石在冷卻中？沿海岸道路往南回去。",
		["Highborne Relics"] = "精靈貴族的聖物",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "在{area:442}東邊的丘陵擊殺狂暴薊熊，然後走到牠們東南方的熊怪營地：目前還不用殺任何東西。",
		["Moonstalker Fangs"] = "月夜猛虎的牙齒",
		["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "月夜雄虎在月刃周圍的樹林中徘徊。{object:10076}和{object:12666}在坑底；{npc:3584}站在北側。",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "月夜猛虎在{quest:954}與高塔之間的丘陵徘徊。{quest:1002}站在高塔西邊的山丘上。",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "夜精靈從{area:442}飛往{area:702}；天裔精靈從{area:442}碼頭搭船，並在那裡學習魯瑟蘭村的飛行路線。搭傳送門上到{area:1658}找{npc:4217}。",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "沿丘陵向北。{npc:3650}在{quest:954}的廢墟中等著；野生劣魔和惡靈劣魔遍布廢墟，戴瑟雷薩特在東緣。{quest:1001}站在廢墟西邊的路旁；前往它的路上，岸邊有一個{quest:4723}。",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "只有在暮光信徒或暮光暴徒掉落{item:5352}時：右鍵點擊它",
		["Plagued bears"] = "染病的熊",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "狂暴薊熊在{area:442}東邊不遠的丘陵遊蕩。對一隻使用{quest:2139}，把牠帶回給他。",
		["Read the {object:17188}"] = "閱讀{object:17188}",
		["Read the {object:17189}"] = "閱讀{object:17189}",
		["Scaber Stalks"] = "粗柄蘑菇",
		["She gives you the {item:15826}"] = "她會給你{item:15826}",
		["Take the portal up to {npc:4217}, then fly back to {area:442} for the boat to {zone:1453}."] = "搭傳送門上去找{npc:4217}，然後飛回{area:442}搭船前往{zone:1453}。",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "月光蘑菇花生長在{area:442}東邊不遠丘陵中的梟獸洞穴裡；那裡的梟獸脾氣暴躁。{item:2449}需要{skill:182}：草藥學家在{zone:1439}各處都能採到，其他人從{zone:1453}（{npc:1313}）或拍賣場帶來。",
		["The WANTED poster"] = "通緝海報",
		["The WANTED poster outside the inn"] = "旅店外的通緝海報",
		["The bay wrecks"] = "海灣沉船",
		["The beach"] = "海灘",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "船停靠在村子西邊。飛行管理員站在旅店南邊的山丘上；任務給予者分布在主街沿線。",
		["The cave and the {npc:6788}"] = "洞穴與{npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls; {object:177624} lies at the satyr camp north of her."] = "洞穴在瀑布南邊：粗柄蘑菇長滿整個洞穴，{item:5270}在最深處。{npc:6788}的巢穴在瀑布南邊的丘陵中；{object:177624}在她北邊的薩特營地。",
		["The flame burns in the south of {area:447}."] = "火焰在{area:447}南部燃燒。",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "兩半墜飾在{zone:1439}和{zone:1436}：之後的路線",
		["The naga"] = "納迦",
		["The red crystal"] = "紅色水晶",
		["The relics of the Barrow Dens"] = "怒風獸穴的聖物",
		["The skeletal turtle"] = "海龜骨骸",
		["The southern beaches"] = "南部海灘",
		["The {area:443}"] = "{area:443}",
		["The {area:448}"] = "{area:448}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["The {object:16393}"] = "{object:16393}",
		["Thresher Eyes"] = "蛇頸龍的眼球",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的海岸爬行；{quest:983}站在碼頭南邊不遠的海灘上。黑海岸蛇頸龍在淺水中游動。{object:175207}在村子南邊不遠的岸上。",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore."] = "兩艘沉船在{area:442}北邊的海灣海底；每艘都有一個鎖箱。暗礁蟹和硬殼潮行蟹散布在這片海岸。",
		["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil."] = "{area:450}位於{npc:10323}海灘南邊的海岸。在勘察員尋找化石時保護他。",
		["{item:12238}: fish from the pier"] = "{item:12238}：在碼頭釣魚",
		["{item:12289}, on the beach west of the docks"] = "{item:12289}，在碼頭西邊的海灘上",
		["{item:12349}, at the waterfall"] = "{item:12349}，在瀑布",
		["{item:12355}, in {object:177624}"] = "{item:12355}，在{object:177624}裡",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}：在瀑布旁的洞口",
		["{item:15851} and {item:2449}"] = "{item:15851}與{item:2449}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，從湖中的{object:177785}取得",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}：廢墟西邊、北海岸外水下的{object:177792}",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}：暮光信徒和暮光暴徒",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}：戴瑟雷薩特",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}：暗灘狂熱者",
		["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}，在碼頭上：只有在學會{skill:356}時",
		["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches west and south-west of {area:450}."] = "{npc:10323}在月刃西邊的海灘紮營：擊殺營火旁的魚人；他會在第三波帶著獵犬出現。{area:450}西邊和西南邊的海灘上還有三具擱淺的骨骸。",
		["{npc:10323}'s beach"] = "{npc:10323}的海灘",
		["{npc:11218}: his escort to {area:413} is done on the {zone:1440} leg"] = "{npc:11218}：護送他到{area:413}的任務在{zone:1440}路段完成",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}：沙德拉斯·月樹的歡迎",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}：對牠們使用{item:15826}；牠們遍布整個{zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}，在古樹之林",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}站在廢墟北緣。被詛咒的精靈貴族、悲苦的精靈貴族和{npc:2178}在廢墟中出沒；{npc:3667}的鬼魂在它們之間走動，貓頭鷹{npc:270196}在它們東邊盤旋。兩塊石板在廢墟中；一個{quest:4722}在廢墟西邊的岸上。",
		["{npc:3644}, on the pier"] = "{npc:3644}，在碼頭上",
		["{npc:3649}, north end of the village"] = "{npc:3649}，在村子北端",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}：給{zone:1453}的{npc:1646}",
		["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661}躲在塔底的暗灘狂熱者之間。把他的信留給{zone:1440}的淨化者德爾葛蘭。",
		["{npc:3666}, by the inn"] = "{npc:3666}，在旅店旁",
		["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out."] = "{npc:3692}躲在{area:449}東邊的丘陵中。幫他回到道路上；他會一路戰鬥出去。",
		["{npc:3694}: for {npc:3691} in {area:415}, on the later {zone:1440} leg"] = "{npc:3694}：之後{zone:1440}路段時給{area:415}的{npc:3691}",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667}躲在廢墟外的小島上。鑰匙碎片由兇猛的森林陸行鳥（上段）、灰霧魚人（中段）和狂暴暗礁蟹（下段）掉落。",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}：在{area:445}裝滿採樣器",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}：交齊全部九具擱淺的骨骸後，{npc:10219}會提供這個任務",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394}（夜精靈）和{npc:272054}（天裔精靈）在{area:493}南部等著。三件聖物在它們東邊的{area:2363}。最初幾週的回報指出，當另一名玩家正在拾取時，聖物不會給你任何東西：稍等一下再試。",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "返回{area:69}",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "向北走過長橋進入城鎮。{npc:341}和{npc:382}站在橋的北端，{npc:900}在市政廳，{npc:381}和{npc:266}在碼頭，{npc:343}在旅店，{npc:342}在西端她的花園裡。",
		["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite."] = "向東經過伐木場並渡河。暗皮豺狼人遍布山谷；{npc:703}（26級，遠高於你）在北端帶領他們：先清掉他的護衛，滿血再打他。不要進入南邊的{area:2099}：那裡的獸人是精英。",
		["Fly to {area:108} and ride north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then ride east along the road through Elwynn to Redridge."] = "飛往{area:108}，向西北騎往海岸：{object:177790}在岸外的海底。然後沿著道路向東穿過艾爾文森林前往赤脊山。",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "沿著{area:68}南岸的道路前往獅鷲管理員處。{npc:1070}和{npc:903}站在她旁邊的路旁。",
		["For {npc:3649}, on the return to {area:442} (06-ashenvale)"] = "給{npc:3649}，在回到{area:442}時（06-ashenvale）",
		["Gnolls toward {area:1002}"] = "前往{area:1002}方向的豺狼人",
		["Greater Tarantulas crawl on the slopes around the mill north-east of the lake; Blackrock Renegades hold the mill itself."] = "巨型狼蛛在湖東北方伐木場周圍的山坡上爬行；黑石叛節者佔據伐木場本身。",
		["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "向北離開{area:69}，沿著{area:95}前往{area:997}。黑石勇士在山谷中紮營。",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "基沙恩躲在山谷最北端、{zone:1428}邊界旁。護送他下到{area:69}；途中黑石獸人會伏擊你。",
		["Lake murlocs"] = "湖邊魚人",
		["Level 18 and 20 spells"] = "18級和20級法術",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin."] = "魚人食腐者和魚人招潮者分布在橋東邊的南岸。他們每一個都可能帶著{item:1467}或魚鰭。",
		["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Dire Condors and Great Goretusks roam the same hills."] = "混血赤脊山豺狼人和其他豺狼人佔據{area:1002}東邊、道路北側的山丘；赤脊山鞭笞者在牠們之間徘徊，赤脊山偷獵者在道路南側紮營。恐鷲和巨型血牙野豬在同樣的山丘上遊蕩。",
		["Shaman training"] = "薩滿訓練",
		["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "從橋向東游進{area:68}；箱子在湖底。",
		["The Wanted poster by the inn: {npc:703}, in {area:1000}"] = "旅店旁的通緝告示：{npc:703}，在{area:1000}",
		["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "從艾爾文森林來的道路在{area:1002}進入赤脊山。{npc:464}站在通往赤脊山和{zone:1431}的道路交會處。",
		["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "{area:442}的船停靠在{area:17203}。走進城裡學習技能並找{npc:1646}，然後從正門離開，沿著道路向東穿過{zone:1429}。",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}：任何暗皮豺狼人",
		["{item:15882}: the {object:177790}"] = "{item:15882}：{object:177790}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}：赤脊山鞭笞者",
		["{item:3014}: the Blackrock Renegades at the mill"] = "{item:3014}：磨坊的黑石叛節者",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}：來自{area:442}的桑迪斯的信",
		["{npc:266}, by the docks"] = "{npc:266}，在碼頭旁",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332}在{object:2100}的軍情七處，{npc:6122}在{object:2101}的{object:2164}地下室，{npc:376}在光明大教堂。",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332}：由{zone:1436}的{npc:7024}接收，在{zone:1431}的結尾",
		["{npc:341}: after {quest:89}"] = "{npc:341}：在{quest:89}之後",
		["{npc:344}, in the town hall"] = "{npc:344}，在市政廳",
		["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345}（24級）在{area:69}西邊不遠處的豬圈裡拱土。把牠從其他野豬旁拉開，滿血再戰。",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}：由{zone:1457}的{npc:11401}接收，稍後",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}：由{zone:1455}的{npc:11406}接收，稍後",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}：由{zone:1455}的{npc:258785}接收，稍後",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}：由{zone:1413}的{npc:6244}接收，稍後",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}，在橋南邊的獅鷲旁",
		["{zone:1431} is next: follow the road west to {area:1002}, then south to {area:42}."] = "下一站是{zone:1431}：沿著道路向西前往{area:1002}，再向南前往{area:42}。",
		["{zone:1453} class quests"] = "{zone:1453}職業任務",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453}沒有薩滿訓練師：從{object:28027}搭乘{area:2257}前往{zone:1455}，向{npc:258098}學習，然後搭地鐵回來。",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "在{npc:7207}旁邊/lay down",
		["Back to {area:42}"] = "回到{area:42}",
		["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "繼續向西前往{area:94}。{object:673515}在道路南邊的廢墟房屋旁發光。",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters."] = "{area:492}北半部的每個食屍鬼都可能掉落肋骨：食腐者、噬骨者、瘟疫食屍鬼和食腦者。",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "沿著道路向西北經過墓地，前往森林最西緣的{npc:311}營地。{npc:893}站在{npc:311}旁邊。",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "沿著道路從{area:1002}向南進入{zone:1431}；{area:42}位於森林東側。",
		["Ghoul Ribs"] = "食屍鬼的肋骨",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "她的房子在{area:42}東南方的山丘上，位於{area:121}上方。",
		["Level 22 and 24 spells"] = "22和24級法術",
		["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "接下來：到{zone:1453}訓練，然後從{area:17203}搭船前往{area:442}，再前往{zone:1440}。",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang."] = "瘋狂的恐狼在墓地和{npc:289}周圍的樹林遊蕩，饑餓的恐狼在他東北方的山丘上。小型結網毒蜘蛛在墓地東邊爬行，會掉落毒液。墓地北半部的每個食屍鬼都可能掉落尖牙。",
		["Ride back east along the road to the {area:245}."] = "沿著道路向東騎回{area:245}。",
		["Ride back east to {area:42}."] = "向東騎回{area:42}。",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "向北騎過艾爾文森林前往{zone:1453}；馬迪亞斯·肖爾在{object:2100}的軍情七處。",
		["Ride west along the road once more."] = "再次沿著道路向西騎。",
		["Ride west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "沿著道路向西離開{area:94}進入{zone:1436}。{npc:7024}在邊界內側的山丘上監視{npc:7053}的塔。守衛塔的{npc:7051}（等級23）身上帶著塔的鑰匙；克拉文的日記在塔頂的箱子裡。",
		["Ride west to the hermit once more."] = "再次向西騎去找隱士。",
		["Rot Blossoms"] = "腐敗之花",
		["Shaman training"] = "薩滿訓練",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "恐怖骸骨在城鎮東南方、{area:42}與{area:121}之間的山坡上走動；牠們會掉落腐敗之花。",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}."] = "骷髏戰士和骷髏法師在{area:42}東南方的墓地間走動，就在山丘上{npc:302}房子的下方。{zone:1431}的每個骷髏都可能掉落{item:2378}。",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "墓地在村莊北邊。恐怖骸骨和骸骨魔在墓地南半部走動。精英{npc:522}在墓地之間遊蕩：遠離他。",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "隱士的小屋在{area:492}東北方的樹林裡。",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "鬆土堆在農舍南邊的老樹樁旁。",
		["Train in {zone:1453}, north through {zone:1429}. Then take the boat from {area:17203} to {area:442}."] = "在{zone:1453}訓練，向北穿過{zone:1429}前往。然後從{area:17203}搭船前往{area:442}。",
		["Wolves, spiders and ghouls"] = "狼、蜘蛛和食屍鬼",
		["{area:492}, south"] = "{area:492}南側",
		["{item:281046}, from the {object:673515}"] = "{item:281046}，來自{object:673515}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}：鍊金術供應商{npc:1313}",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {area:150} sells it too."] = "{item:4371}，向{npc:3133}購買：數量有限。賣完了？{area:150}的{npc:1448}也有賣。",
		["{item:7908}, in the chest"] = "{item:7908}，在箱子裡",
		["{npc:2409}, at the north end of town"] = "{npc:2409}，在城鎮北端",
		["{npc:264}, in the town hall"] = "{npc:264}，在市政廳裡",
		["{npc:265}, in her house by the tavern"] = "{npc:265}，在旅店旁她的房子裡",
		["{npc:267}, in the town hall"] = "{npc:267}，在市政廳裡",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}，在市政廳後面的房子裡",
		["{npc:273}, in the tavern"] = "{npc:273}，在旅店裡",
		["{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "{npc:276}的房子在城鎮東端。{npc:3133}在旁邊的房子裡出售工程學商品。",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288}躲在{area:94}西端的房子裡。",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}：毒藥，以及{item:18160}",
		["{npc:633}, at the south end of town"] = "{npc:633}，在城鎮南端",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}，在旅店",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888}站在道路南邊的{area:245}。",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}：{npc:7207}，在兵營地下室",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}：{zone:1431}怪物的稀有掉落",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the {area:442} boat."] = "{zone:1453}沒有薩滿訓練師：從{object:28027}搭乘{area:2257}前往{zone:1455}，向{npc:258098}學習，然後搭地鐵回來搭前往{area:442}的船。",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "回到光明大教堂：{npc:928}站在裡面。",
		["Black Oozes"] = "黑色軟泥怪",
		["Black Oozes creep through the marsh north of the {area:1025} road, west of {npc:2093}'s camp. Any ooze may hold {npc:2111}'s bag."] = "黑色軟泥怪在{area:1025}道路北邊、{npc:2093}營地西邊的沼澤中爬行。任何軟泥怪都可能帶著{npc:2111}的袋子。",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Cathedral of Light"] = "光明大教堂",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "洞穴捕獵者和吸血捕獵者遍布挖掘場東南方的洞穴{area:1021}。",
		["Dragonmaw camp"] = "龍喉營地",
		["Escort Kerlonian to {area:413} in {zone:1440}."] = "護送克羅尼亞·恒影到{zone:1440}的{area:413}。",
		["Fen Creepers"] = "沼澤爬行者",
		["Fen Creepers hide in the marsh pools north-west of the {area:1025}."] = "沼澤爬行者躲在{area:1025}西北方的沼澤水池中。",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "沿海岸向北離開米奈希爾港。藍腮魚人遍布沼澤；{npc:1259}帶著一群魚人在中間走動。",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "沿海岸向北前往{area:414}。{npc:3846}在海灘上紮營；怒尾納迦遍布海岸。",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "沿道路向東前往{area:419}；{npc:3916}站在月井旁。",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "沿道路向東。小濕地鱷魚潛伏在挖掘場北邊的水池中。",
		["Follow the road north to {area:205}, at the foot of the {area:881}. {npc:1071} stands in the dwarves' camp."] = "沿道路向北前往{area:881}山腳下的{area:205}。{npc:1071}站在矮人營地裡。",
		["Follow the road south-east to {area:415}, on the island in the lake."] = "沿道路向東南前往湖中島上的{area:415}。",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "給{object:2117}的伯瓦爾·弗塔根公爵：先留著",
		["For the giant crocolisks of the north coast, on your next visit"] = "北海岸的巨型鱷魚，下次來時再打",
		["For {npc:2228} in {area:271}: keep it"] = "給{area:271}的{npc:2228}：先留著",
		["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then ride south along the road through {zone:1439}."] = "從{area:17203}搭船到{area:442}；{npc:3649}站在村子北端。然後沿道路向南騎過{zone:1439}。",
		["Hearth to Menethil"] = "用爐石回到米奈希爾港",
		["Hearthstone on cooldown? Ride back north through the {area:1276}."] = "爐石在冷卻中？向北騎回去穿過{area:1276}。",
		["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {zone:1440} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep."] = "克羅尼亞·恒影睡在{zone:1439}南部的{area:448}。使用{item:13536}叫醒他，沿道路向南帶他進入{zone:1440}，到{area:413}找{npc:11219}；每當他睡著就再吹一次號角。",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "擊殺元素取得5個完整的元素護腕，然後使用{item:5456}",
		["Mosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "蘚皮沼澤行者和蘚皮織霧者在{npc:1244}西邊和南邊不遠的河岸遊蕩；幾乎每一隻都會掉落燧石。",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "蘚皮豺狼人和混血蘚皮豺狼人佔據{area:1025}東南方的丘陵。",
		["Mottled Raptors and Screechers roam the hills west of the excavation site."] = "雜斑迅猛龍和雜斑尖嘯龍在挖掘場西邊的丘陵遊蕩。",
		["Next: fly to {area:42}."] = "下一步：飛往{area:42}。",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "在邁斯特拉崗哨北邊，植物束散落在{area:411}廢墟周圍。暗灘祭司佔據其南邊不遠的廢墟：任何一個都可能掉落{item:5366}。",
		["Only if you looted {quest:337} in {zone:1431}"] = "只有在{zone:1431}拾取了{quest:337}時",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "只有在持有{zone:1439}的{item:5352}時：{npc:2786}，{object:32383}",
		["Raptor valley"] = "迅猛龍山谷",
		["Ride east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "沿{zone:1437}的道路向東騎，向南穿過{area:836}進入{zone:1432}，再向西穿過隧道進入{zone:1426}，前往{area:1537}。",
		["Ride south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "向南騎過{area:421}進入{area:1276}隧道；出口在石爪山脈的{area:461}。{npc:4080}和{npc:4077}在峭壁西南方的{area:1076}紮營。",
		["Ride west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "向西騎到{area:441}的岸邊。泰洛尼斯的屍體躺在鹽沫魚人之間；任何魚人都可能掉落{item:5463}。",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "在魚人南邊，{npc:3585}在{area:416}等著。",
		["Take the boat from {area:17203} to {area:442} and fly to {area:702}; {npc:11401} is in the Temple of the Moon. Then fly back to {area:442}."] = "從{area:17203}搭船到{area:442}，飛往{area:702}；{npc:11401}在Temple of the Moon。然後飛回{area:442}。",
		["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then fly to {area:702} (by way of {area:442})."] = "從{area:17203}搭船到{area:442}。把兩半墜飾合成{item:15885}，施放{spell:18960}：{npc:11802}在{area:2361}。然後飛往{area:702}（途經{area:442}）。",
		["Take the portal up to the {area:1658}, then fly back to {area:442}."] = "搭傳送門上到{area:1658}，然後飛回{area:442}。",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "從{object:171524}搭乘{area:2257}前往{zone:1453}的{object:28027}，然後走到{object:2098}。",
		["The Bluegill hovels"] = "藍腮魚人小屋",
		["The Dragonmaw camp lies south of the road, just west of the {area:1025}: Raiders, Swamprunners and Bonewarders. {npc:2092}'s quest in {zone:1426} needs level 28."] = "龍喉營地在道路南邊、{area:1025}西邊不遠處：有龍喉襲擊者、龍喉沼澤行者和龍喉白骨守衛。{npc:2092}在{zone:1426}的任務需要28級。",
		["The Foulweald"] = "汙林熊怪",
		["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "汙林熊怪住在道路南邊、{area:415}東南方的樹林中。汙林衛兵和汙林巨熊怪守護巢穴。",
		["The Mosshide gnolls"] = "蘚皮豺狼人",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "風險投資公司正在砍伐{area:461}的森林。樵夫和砍樹工到處工作；操作員駕駛伐木機，其中一人帶著藍圖。",
		["The bigger raptors hunt in the valley just west of the dig."] = "體型更大的迅猛龍在挖掘場西邊不遠的山谷中狩獵。",
		["The excavation site sits on the hill south of the road."] = "挖掘場在道路南邊的山丘上。",
		["The raptor hills"] = "迅猛龍丘陵",
		["The tears glow on the small isle east of {area:415}."] = "淚珠在{area:415}東邊的小島上發光。",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "魚人小屋中的三個容器，由南到北：{object:261}，然後是{object:142151}，最後是北端的{object:259}。",
		["Timber and iron piles lie around the keep and along the harbor's walls."] = "木材和鐵堆放在城堡周圍和港口的城牆邊。",
		["To {area:150}"] = "前往{area:150}",
		["Venture Co. loggers"] = "風險投資公司樵夫",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "在密斯特拉湖西邊，星塵灌木生長在廢墟之間。",
		["Young crocolisks"] = "小鱷魚",
		["grind on Dragonmaw Raiders and Swamprunners at the Dragonmaw camp, {zone:1437}"] = "在{zone:1437}的龍喉營地刷龍喉襲擊者和龍喉沼澤行者",
		["{item:15885}: join the two halves"] = "{item:15885}：合成兩半",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}，在海岸上的廢墟裡",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406}和{npc:258785}在{object:32362}的{object:32386}。",
		["{npc:1239}, in the inn"] = "{npc:1239}，在旅店裡",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}，在旅店北邊的碼頭上",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}：給城堡裡的{npc:2104}",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}，在皇家圖書館",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}，在{object:2098}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}，在{object:32372}",
		["{npc:2086}, by the keep"] = "{npc:2086}，在城堡旁",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093}在路邊紮營；{npc:1244}站在更東邊的河邊。",
		["{npc:2094}, by the north gate"] = "{npc:2094}，在北門旁",
		["{npc:2096}, by the north gate"] = "{npc:2096}，在北門旁",
		["{npc:2097}, by the north gate"] = "{npc:2097}，在北門旁",
		["{npc:2104} stands in {area:2103}, a short walk from {npc:1242}."] = "{npc:2104}站在{area:2103}，離{npc:1242}不遠。",
		["{npc:3649}: Alexston's reply"] = "{npc:3649}：巴洛斯·艾力克斯頓的回信",
		["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664}和他的虛無行者佔據神殿南邊的{area:412}。先拉他的守衛。",
		["{npc:3691}, in the inn"] = "{npc:3691}，在旅店裡",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885}站在{area:421}東岸的{area:420}；{npc:210995}在湖的西岸紮營。污濁的水元素在兩者之間的湖中涉水。",
		["{npc:3987} (25) leads the Thistlefur gnolls at the camp north of {area:415}. Clear his guards first, one at a time."] = "{npc:3987}（25級）率領{area:415}北邊營地的薊皮熊怪。先一個一個清掉他的守衛。",
		["{npc:4201}, in the hut north of them"] = "{npc:4201}，在他們北邊的小屋裡",
		["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines."] = "{npc:4276}在峭壁東端的{area:2160}採礦。和他交談，在他採礦時擊退風險投資公司的襲擊者。",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}，{object:2096}的乳酪店",
		["{npc:4959} and {npc:482}"] = "{npc:4959}與{npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}，在光明大教堂內",
		["{object:2164} is in the {object:2101}."] = "{object:2164}在{object:2101}。",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009}帶著怒尾守衛在{area:414}的北端走動。",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}，從植物束取得",
		["{zone:1455} priests"] = "{zone:1455}的牧師",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to Menethil"] = "回到米奈希爾",
		["Back to {area:42}"] = "回到{area:42}",
		["Bluegill Raiders"] = "藍腮襲擊者",
		["Dragonmaw camp"] = "龍喉營地",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿著峽谷向東前往鹽湖。{area:2240}的哥布林和地精是中立的，兩個陣營都能接他們的任務。",
		["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it."] = "沿著海岸向北前往沉船。被詛咒的水手在海灘上走動，被詛咒的水兵在甲板上；{npc:1159}站在船頭旁的海灘上。巨型濕地鱷魚潛伏在它北邊的海岸。",
		["Follow the coast north-east past the wreck: the Bluegill Raiders hold the marsh beyond the Giant Crocolisks."] = "沿著海岸向東北經過沉船：藍腮襲擊者佔據巨型鱷魚後方的沼澤。",
		["Follow the road east to the excavation site."] = "沿著道路向東前往挖掘場。",
		["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "龍喉投石車在下一份指南的{zone:1437}路線中完成",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "交給{zone:1453}的{npc:1212}，在下一份指南",
		["For {npc:1284} in {zone:1453}, in the next guide"] = "交給{zone:1453}的{npc:1284}，在下一份指南",
		["For {npc:4048} in {zone:1444}, much later"] = "交給{zone:1444}的{npc:4048}，很久以後",
		["For {npc:482} in {zone:1453}, in the next guide"] = "交給{zone:1453}的{npc:482}，在下一份指南",
		["For {quest:5762} in Stranglethorn, later"] = "交給荊棘谷的{quest:5762}，稍後",
		["From Theramore follow the road west out of Dustwallow into the {zone:1413} and south along it; give {area:378} a wide berth. {area:485} at the {zone:1413}' south end takes you down into {zone:1441}. The journal lies at the foot of the lift."] = "從塞拉摩沿著道路向西離開塵泥沼澤進入{zone:1413}，再沿路向南；遠離{area:378}。{zone:1413}南端的{area:485}帶你往下進入{zone:1441}。日記就在升降梯底下。",
		["From {npc:352} in {zone:1453}"] = "向{zone:1453}的{npc:352}取得",
		["Her house stands on the hill south-east of {area:42}."] = "她的房子在{area:42}東南方的山丘上。",
		["Nightbane Dark Runners"] = "夜行黑暗狼人",
		["Nightbane Shadow Weavers"] = "夜行織影狼人",
		["Nightbane Vile Fangs and the {npc:511}"] = "夜行邪齒狼人與{npc:511}",
		["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too."] = "沒有{quest:174}要的{item:4371}？{npc:3133}在{npc:276}旁邊的房子裡限量出售；{area:150}的{npc:1448}也有賣。",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "在向南穿過{zone:1413}的道路上，{npc:6244}在道路東邊、{area:378}東北方紮營；從東邊過去，避開部落衛兵。",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "僅限{npc:272273}掉落了{quest:96138}時：右鍵點擊它",
		["Plague Spreaders"] = "瘟疫食屍鬼",
		["Ride back west along the road to {area:150}."] = "沿著道路向西騎回{area:150}。",
		["Ride east again to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "再次向東騎到龍喉營地。四份攻擊計畫在{area:1036}；精英{npc:2091}也站在營地裡。",
		["Ride east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "向東騎往巨魔山。{object:119}放在入口處的營地裡；裂拳巨魔守衛著它。",
		["Ride west along the road; the hermit's shack stands north-east of the {area:492}."] = "沿著道路向西騎；隱士的小屋在{area:492}東北方。",
		["Skeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp."] = "骷髏襲擊者、骷髏醫師和骷髏看守佔據墓地西側，就在{npc:311}營地的東邊。",
		["Take the boat from Menethil's pier to {area:513} in {zone:1445}."] = "從米奈希爾的碼頭搭船前往{zone:1445}的{area:513}。",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "黑暗狼人在道路南側、{area:42}西邊的樹林中徘徊。",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "迪菲亞營地位於{zone:1431}西南部，{area:94}南邊，靠近{zone:1436}邊界。保險箱在帳篷之間。",
		["The Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "龍喉獸人在挖掘場東邊紮營。龍喉襲擊者和龍喉沼澤行者帶著戰旗。",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him."] = "瘟疫食屍鬼在{area:492}北半部走動。精英{npc:522}在墓地之間遊蕩：遠離他。",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "船長在沉船的甲板上走動；他的保險箱在貨艙裡。",
		["The dig and {npc:1353}"] = "挖掘場與{npc:1353}",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "文物就在挖掘場裡。{npc:1353}是一隻大型刺喉龍，在挖掘場西邊的迅猛龍山谷徘徊。",
		["The salt flats"] = "鹽湖",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery."] = "最強的狼人在{area:42}南邊、{area:121}西邊和南邊的樹林中遊蕩。{npc:511}躲在墓園旁的小墓穴裡。",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "狼人佔據亮木樹林的樹林，在{area:42}西邊、道路北側。一次只拉一隻。",
		["The wreck of the Third Fleet"] = "第三艦隊的殘骸",
		["To Theramore"] = "前往塞拉摩",
		["Wait a moment, then speak with her again"] = "稍等一下，然後再和她說話",
		["{area:492}, west"] = "{area:492}西側",
		["{item:2594}, from {npc:1464}"] = "{item:2594}，向{npc:1464}購買",
		["{item:2661}: the {object:331}"] = "{item:2661}：{object:331}",
		["{item:4371}, from {npc:3133}, if you have none"] = "如果你沒有，向{npc:3133}購買{item:4371}",
		["{npc:1078} and Whelgar"] = "{npc:1078}與維爾加",
		["{npc:1217}, upstairs in the inn"] = "{npc:1217}，在旅店樓上",
		["{npc:1239}, in the inn"] = "{npc:1239}，在旅店裡",
		["{npc:2104}, by the keep"] = "{npc:2104}，在城堡旁",
		["{npc:2104}, in {area:2103}"] = "{npc:2104}，在{area:2103}",
		["{npc:263}, in the town hall"] = "{npc:263}，在市政廳裡",
		["{npc:267}, in the town hall"] = "{npc:267}，在市政廳裡",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}，在市政廳後面的房子裡",
		["{npc:276}, at the east end of town"] = "{npc:276}，在城鎮東端",
		["{npc:311}'s Camp"] = "{npc:311}的營地",
		["{npc:4454}: for Martek in the {zone:1418}, later"] = "{npc:4454}：交給{zone:1418}的馬特克，稍後",
		["{npc:661}, by {npc:633}'s house"] = "{npc:661}，在{npc:633}的房子旁",
		["{npc:663}, by the town hall"] = "{npc:663}，在市政廳旁",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}，在旅店",
		["{npc:840}, at the north entrance of town"] = "{npc:840}，在城鎮北側入口",
		["{object:19868} lies all over the flats. Scorpid Reavers, Sparkleshell Tortoises and Saltstone Basilisks roam the north half, Crystalhides, Scorpid Terrors and Snappers the middle, and the Gazers (34-35, five levels above you: one at a time) the far south. Vultures circle over all of it."] = "{object:19868}遍布整片鹽湖。恐蠍劫掠者、鹽殼龜和鹽石蜥蜴在北半部遊蕩，鹽石水晶蜥蜴、恐蠍和鹽殼鉗嘴龜在中間，鹽石凝視者（34-35級，比你高五級：一次一隻）在最南邊。鹽湖禿鷲在整片上空盤旋。",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}：在{zone:1440}，前往{zone:1443}的路上",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}：夢魔在魅魔旁邊；{item:190309}在{quest:1738}附近",
		["{quest:98221}: {quest:465} comes after it on Forever"] = "{quest:98221}：在Forever上，{quest:465}排在它之後",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}"] = "新的{item:279996}，用於{zone:1437}周圍的四個泰坦守望者",
		["A report for {object:2117}"] = "給{object:2117}的報告",
		["Back south down the road to the excavation site."] = "沿著道路向南回到挖掘場。",
		["Back to the same murlocs; not every one drops a head."] = "回到同一群魚人；不是每隻都會掉落頭。",
		["Boat to {area:271}"] = "搭船前往{area:271}",
		["Cathedral of Light"] = "光明大教堂",
		["Daggerspine naga"] = "刺脊納迦",
		["Druid training"] = "德魯伊訓練",
		["Farren"] = "法爾林",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["Follow the road east to {area:118}."] = "沿著道路向東前往{area:118}。",
		["Follow the road north-east into the {area:1025}: {npc:270637} camps beside it, {npc:1244} a short way east."] = "沿著道路向東北進入{area:1025}：{npc:270637}在路旁紮營，{npc:1244}在東邊不遠處。",
		["For King Magni in {zone:1455}, at the end of this guide"] = "給{zone:1455}的國王麥格尼·銅鬚，在本指南結尾",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "給{zone:1455}的{npc:2916}，在本指南結尾",
		["From {npc:2432} in {area:271}"] = "來自{area:271}的{npc:2432}",
		["Level 30 and 32 spells"] = "30級和32級法術",
		["Murloc heads"] = "魚人頭",
		["North along the road to {area:205}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "沿著道路向北前往{area:205}。{npc:271460}站在遺跡中（使用{item:279996}）；{npc:271481}被關在西側：把它帶出去交給{npc:1072}。",
		["North-east to the {area:1038}: the {npc:271373} are held there, and {npc:271338} stands at the gates (use the {item:279996})."] = "向東北前往{area:1038}：{npc:271373}被關在那裡，{npc:271338}站在大門旁（使用{item:279996}）。",
		["Pick up everything in town before heading out. Off the boat, {npc:251493} is the first you meet, north-west of the flight master; {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "出發前先接下城裡的所有任務。下船後，第一個遇到的是飛行管理員西北方的{npc:251493}；{npc:2381}和{npc:2438}站在飛行管理員和旅店之間，法爾林和{npc:2366}在旅店，馬雷布在市政廳。",
		["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; {npc:271458} stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised."] = "紅色雛龍遍布大門西邊的山丘，瘋狂的腐爪龍在{area:1025}，刺喉龍在北面山坡；{npc:271458}站在東北方（使用{item:279996}）。\n{quest:98283}是精英：建議組隊。",
		["Snapjaws"] = "鉗嘴龜",
		["South to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "向南前往龍喉的{area:1036}：第一架投石車就在路上，{object:671518}就在營地裡。",
		["Syndicate camp"] = "辛迪加營地",
		["Take the {area:2257} from the {object:28027} to {zone:1455}."] = "從{object:28027}搭乘{area:2257}前往{zone:1455}。",
		["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one."] = "{npc:270892}就站在維爾加營地西邊：在其中一個旁邊使用他給你的{item:279996}。",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "鉗嘴龜在{area:271}東邊、{area:272}（部落）南邊的河邊曬太陽。",
		["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp."] = "辛迪加營地位於{area:287}北部的奧特蘭克邊界，在{area:272}（部落）西邊；文件就在營地裡。",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}."] = "碎鰭魚人聚集在{area:271}西南方的{area:295}。",
		["The Villards"] = "韋拉德一家",
		["The cheese shop in the {object:2096}."] = "{object:2096}的乳酪店。",
		["The naga hold the shore south-east of {area:271}."] = "納迦佔據{area:271}東南方的海岸。",
		["The next step, Defeat Nek'rosh, pits you against an elite chieftain: skip it."] = "下一步「擊敗納克羅西」要你對抗一名精英酋長：跳過它。",
		["The yetis live in the cave in the hills north of {area:271}, on your way back south."] = "雪人住在{area:271}北邊山丘的洞穴裡，就在你往南回去的路上。",
		["Torn Fin murlocs"] = "碎鰭魚人",
		["West along the road to Menethil."] = "沿著道路向西前往米奈希爾。",
		["West to the farms of {area:287}: place the {item:279386} on the bookkeeping table in the town hall, where {npc:2335} and the councilmen stand."] = "向西前往{area:287}的農場：把{item:279386}放在市政廳裡的帳簿桌上，{npc:2335}和議員們就站在那裡。",
		["Whelps, raptors and {npc:271458}"] = "雛龍、迅猛龍與{npc:271458}",
		["Yeti cave"] = "雪人洞穴",
		["{area:287} town hall"] = "{area:287}市政廳",
		["{area:287}'s town hall"] = "{area:287}的市政廳",
		["{item:3713}, from {npc:2381}"] = "{item:3713}，來自{npc:2381}",
		["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244}：{quest:98283}，一隻精英迅猛龍",
		["{npc:2104} stands in {area:2103}; {npc:2094} stands by the north gate."] = "{npc:2104}站在{area:2103}；{npc:2094}站在北門旁。",
		["{npc:2104}: for {npc:270637}"] = "{npc:2104}：給{npc:270637}",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}，在旅店裡：給{area:35}（04-stranglethorn-vale）",
		["{npc:2382}: the lions come later"] = "{npc:2382}：獅子稍後再打",
		["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in {area:271} later."] = "{npc:2438}還要一件{item:3719}、一匹{item:2997}和{item:2321}：自己製作或購買；斗篷要等你稍後回到{area:271}時才繳交。",
		["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708}在{object:2164}；{npc:211033}在運河附近；{npc:5081}在{object:2101}南邊。",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}：他的線索通往阿拉希",
		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462}站在東南方的山丘上：在它旁邊使用{item:279996}。",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}，{object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961}在{object:2100}的酒館裡等候；他和他的兩個打手會跟你打，但被打敗後就會停手。",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479}在{object:2100}的酒館旁訓練戰士。{npc:6236}在{zone:1413}的{area:720}等候，要很久以後前往{area:392}的途中才會經過（40-50/01）。",
		["{npc:5683} waits north of {area:205} by the {area:881}; {npc:271322} a short walk further north-east."] = "{npc:5683}在{area:205}北邊的{area:881}旁等候；{npc:271322}在東北方不遠處。",
		["{object:671518}: for {npc:2104}"] = "{object:671518}：給{npc:2104}",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455}沒有德魯伊訓練師：搭地鐵前先在{zone:1453}向{npc:5504}學習。",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort the caravan"] = "護送車隊",
		["Escort {npc:5644}"] = "護送{npc:5644}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "沿著道路向西經過{area:460}（部落），再向西南穿過{area:465}進入{zone:1443}；{area:608}位於山口頂端。",
		["From {area:415} head south-west to the {area:1276}, a tunnel through the mountains into Stonetalon."] = "從{area:415}向西南前往{area:1276}，這是一條穿過山脈通往石爪山脈的隧道。",
		["From {area:415} ride north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "從{area:415}向西北騎進山丘：{quest:1738}是前往{area:413}道路北邊一棵發光的樹。如果你接了{quest:65602}，{item:190309}在{area:413}北邊樹林中的一間房子裡（26.6,22.0）。然後經過{area:415}回到{area:1276}。",
		["From {zone:1455}'s {npc:1573}"] = "來自{zone:1455}的{npc:1573}",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "她的哥哥{npc:5643}（36級）和燃刃氏族教徒（30-33級）一起在要塞裡走動：單獨把他拉出來。{npc:13019}把權杖放在要塞的主建築裡。",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "帶{npc:5644}走出要塞；離開要塞後她就會自行離去。指南結尾時在{area:608}向{npc:5642}繳交。",
		["Malem chest"] = "瑪雷姆的箱子",
		["Out of Thunder Axe Fortress"] = "離開雷斧堡壘",
		["Scorpashi venom"] = "荒土蠍毒液",
		["Take the boat to {area:442} from Menethil's docks."] = "在米奈希爾的碼頭搭船前往{area:442}。",
		["The Gizelton Caravan waits at {area:2407}."] = "基澤爾頓車隊在{area:2407}等候。",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}."] = "怨怒薩特佔據{area:608}東邊的{area:603}廢墟。",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "科卡爾半人馬在{area:609}周圍的平原上遊蕩；牠們的耳朵是給{npc:5752}的。",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "荒土蠍在往南道路上的{area:2407}周圍山丘獵食。",
		["The chest lies in the ruins south-west of {area:608}."] = "箱子在{area:608}西南方的廢墟中。",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "對{npc:4700}使用{npc:11596}的{item:13892}，把馴服的科多獸帶回他的營地，共五次；老邁的科多獸也會掉落獸皮。",
		["Walk with the caravan south past {area:609}; Kolkar ambushers jump it on the way. Stay close until it stops at {area:2617}. The ambushers are 34-35 and come in waves: skip it if you are below 33."] = "跟著車隊向南經過{area:609}；途中科卡爾伏擊者會襲擊車隊。待在附近直到它停在{area:2617}。伏擊者是34-35級，而且分波出現：如果你低於33級就跳過。",
		["{item:190309}, north of {area:413}"] = "{item:190309}，在{area:413}北邊",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "{npc:11596}的營地在{area:609}南邊的路上，位於{area:596}旁。",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "{npc:11863}的塔位於{area:599}西邊的山丘上：先接他的任務，他要的權杖就在要塞裡。",
		["{npc:5643} and the Seer"] = "{npc:5643}與先知",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644}躲在{area:608}西南方火刃的要塞裡。",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "達圖爾的變形魔棒",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "沿著道路向東前往{area:429}的薩特營地；{npc:3920}躲在營地邊緣。",
		["Follow the road west out of {area:415}; {area:413} lies north of it."] = "沿著道路向西離開{area:415}；{area:413}在道路北邊。",
		["From {area:608}"] = "從{area:608}出發",
		["Insane druids"] = "發狂的德魯伊",
		["Lightforge Ingots"] = "光鑄鐵錠",
		["Melyria and {npc:3901}"] = "梅麗瑞亞與{npc:3901}",
		["Rusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel."] = "生銹的箱子散落在被遺忘者西邊的沼澤獸營地周圍；逐一打開，直到其中一個裝著柄頭。",
		["Take the boat to {area:150} from {area:442}'s docks."] = "從{area:442}的碼頭搭船前往{area:150}。",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "穿過隧道進入{area:419}；書在山谷西端的廢墟裡。",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "米奈希爾西南方海灘上的藍腮魚人帶著鐵錠。",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "月井北邊的瘋狂的古樹和乾枯的古樹帶著{item:5475}；它能打開的破舊箱子就在它們之間。",
		["The Forsaken's camp lies in the woods south of {area:2358}."] = "被遺忘者的營地在{area:2358}南邊的樹林裡。",
		["The moonwell lies in the hills north-east of {area:415}."] = "月井在{area:415}東北方的山丘上。",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "第二個{object:19901}在{area:428}的山谷裡，在往西的路上。",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "神龕在月井東南方的山丘上；沿著蜿蜒的小路往上走。",
		["The three druids stand together at the Forsaken camp south of {area:2358}."] = "三名德魯伊一起站在{area:2358}南邊的被遺忘者營地。",
		["The two stand together at the western end of the road."] = "她們兩人一起站在道路西端。",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "沉船殘骸在城堡南邊的淺水處。",
		["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way."] = "{npc:3931}在箱子西南方的{quest:1035}岸邊走動；{object:669176}在湖的北邊，就在路上。",
		["The {object:19901} stands in the satyr camp of {area:430}, further east along the road."] = "{object:19901}在道路更東邊的{area:430}薩特營地裡。",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}是道路東端的夜精靈前哨：{npc:3848}站在那裡。",
		["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217}站在米奈希爾城堡的上層。",
		["{npc:3696} and his guards camp just east of {npc:3897}."] = "{npc:3696}和他的守衛在{npc:3897}東邊紮營。",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "未受腐化的熊怪{npc:3897}坐在{area:421}下方的道路南邊。",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide"] = "{npc:3970}：交給米奈希爾的{npc:1480}，在本指南的最後",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619}率領{area:429}的薩特；樹枝在他身上。",
		["{npc:5082}, {npc:4963} and Tapoke Jahn are all at Menethil's inn; {npc:4962} fights you when you talk to {npc:4963}, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn."] = "{npc:5082}、{npc:4963}和{npc:4962}·賈恩都在米奈希爾的旅店；你和{npc:4963}說話時塔伯克會攻擊你，但被打敗後就會投降。{npc:1480}站在旅店東北方不遠處。",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}：交給{area:415}的{npc:3961}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "往南經過赫米特·奈辛瓦里：黑豹和荊棘谷迅猛龍在營地西邊通往海岸的空地上奔跑；老年荊棘谷猛虎佔據西南方的丘陵。",
		["Bloodscalp trolls"] = "血頂食人妖",
		["Both roam the grass around the camp and along the road north."] = "兩者都在營地周圍的草地和往北的道路沿線遊蕩。",
		["Down to {area:35}"] = "前往{area:35}",
		["Druid training"] = "德魯伊訓練",
		["Fly from {area:150} to {area:1537} and train."] = "從{area:150}飛往{area:1537}並訓練。",
		["Fly to {area:42}: {npc:1573} in {area:1537}'s {object:32372}, or {npc:352} in {zone:1453}'s {object:2096}."] = "飛往{area:42}：{area:1537}{object:32372}的{npc:1573}，或{zone:1453}{object:2096}的{npc:352}。",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "沿主要道路向南穿過整片叢林，經過{object:3202}岔路，到達南端海角的{area:35}。",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "沿西海岸向北；鬧鬼的島在奈辛瓦里營地西邊的外海。只要到達那裡即可。",
		["For Archmage Ansirem in {zone:1416}"] = "給{zone:1416}的大法師安斯雷姆·魯因維沃爾",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "從{zone:1431}沿道路向南進入荊棘谷；獵人的帳篷就在過了{area:99}岔路後的道路西邊。",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "戈魯格爾是營地西邊海岸上的稀有魚人，會掉落{item:4614}：遇到就拿",
		["Gyll, on the top floor by the docks"] = "蓋爾，在碼頭旁的頂樓",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "庫爾森精神醫師站在營地更深處；庫爾森特種兵潛行埋伏在營地周圍和洞穴中。掉落的荊棘谷的青山書頁都撿起來。",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "書呆子赫羅德的檔案在營地西側的一間小屋裡；他的保險箱在更東邊的洞口旁。",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "繞行北部和中部的食人妖廢墟：每處都有一塊記載食人妖傳說的石板。深喉獵豹潛行在周圍的叢林中；{area:37}的風險投資公司營地身上帶著打磨過的水晶。",
		["Panthers, raptors and elder tigers"] = "黑豹、迅猛龍與老年猛虎",
		["River Crocolisks swim the river by the {area:99}."] = "淡水鱷在{area:99}旁的河中游動。",
		["River crocolisks"] = "淡水鱷",
		["Skullsplitter trolls"] = "劈顱食人妖",
		["Snapjaw Crocolisks"] = "鉗嘴鱷魚",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "鉗嘴鱷魚在{area:35}北邊海岸和島嶼上曬太陽。",
		["Stranglethorn Tigers"] = "荊棘谷猛虎",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "沿道路向北；{npc:738}在路上巡邏，營地在西邊的丘陵中。",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "血頂食人妖佔據奈辛瓦里營地西邊海岸上的廢墟。",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "庫爾森叛軍佔據{area:99}東邊的營地；在外圍活動，那裡有庫爾森叢林戰士和庫爾森藥草師，並拾取帳篷旁的補給箱。",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "劈顱食人妖佔據奈辛瓦里與{object:3202}之間道路東邊的廢墟。",
		["The adult tigers prowl the hills just south and west of the camp."] = "成年猛虎在營地南邊和西邊不遠的丘陵徘徊。",
		["The elder tigers come later, on the way back from the {area:99}"] = "老年荊棘谷猛虎之後再打，在從{area:99}回來的路上",
		["The haunted island"] = "鬧鬼的島",
		["The jungle ruins"] = "叢林廢墟",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "礦石由{zone:1417}的枯鬚狗頭人掉落",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "列兵索爾森在營地北邊、朝{area:99}方向的道路上巡邏。",
		["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards."] = "往北走回去；{area:310}在叢林中部的道路西邊。那裡的晶背蜥蜴會掉落碎片。",
		["Young tigers and panthers"] = "小荊棘谷猛虎與小獵豹",
		["{area:1537} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{area:1537}沒有德魯伊訓練師：從{object:171524}搭乘{area:2257}前往{zone:1453}，向{npc:5504}學習。",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}，來自{object:263}箱子",
		["{npc:2495}, by the bank"] = "{npc:2495}，在銀行旁",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}，在酒館樓上",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}，在{object:56910}",
		["{npc:469}, in the hut"] = "{npc:469}，在小屋裡",
		["{npc:715}, from {zone:1441}"] = "{npc:715}，來自{zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716}收集{item:2755}：叢林中幾乎每個人形生物都會掉落書頁。邊走邊把書頁整理成章節。",
		["{npc:729} and the Lashtail raptors"] = "{npc:729}與鞭尾迅猛龍",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "巨虎{npc:729}的巢穴在營地西南方的山頂；鞭尾迅猛龍在它南邊、前往{area:35}的路上奔跑。",
		["{npc:737}, in the tavern"] = "{npc:737}，在酒館裡",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}：給{area:35}的{npc:773}",
		["{npc:773}, in the tavern"] = "{npc:773}，在酒館裡",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}：只需在獵人營地四處看看",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "一個{npc:2434}隱身潛伏在{area:271}邊緣；殺死他並閱讀他身上的契約。",
		["Back west through {zone:1430} to {area:42}."] = "向西穿過{zone:1430}回到{area:42}。",
		["Crushridge ogres"] = "破碎嶺巨魔",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}."] = "每把鑰匙都在高地的一處立石圈：碎片東邊、{area:320}附近，以及西部。{object:2702}在{area:320}西邊。",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "沿道路向東前往{area:76}。{npc:256028}怪物會掉落水晶；木棒諾博魯在廢墟中走動，會掉落他的木棒。",
		["Ebenezer Rustlocke"] = "伊貝尼瑟的屍體",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "護送教授到海灣北邊的海灘，在他工作時保護他；納迦會一波波來襲。",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:42}"] = "飛往{area:42}",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "沿道路從{area:287}向東越過{area:1057}前往{area:320}。",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "沿道路從{area:271}向北進入山區。山地獅在山坡上遊蕩；{area:280}的辛迪加戴著圖章戒指，{npc:2306}在鎮北側的莊園庭院走動。",
		["Follow the road north to the draenei of the {area:657}."] = "沿道路向北前往{area:657}的德萊尼人那裡。",
		["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "沿道路向南過橋，前往{zone:1437}那一端的{area:205}，{npc:1075}在那裡等著。",
		["For {npc:1440} in {zone:1453}: keep it"] = "給{zone:1453}的{npc:1440}：先留著",
		["For {npc:2487} in {area:35}: keep it"] = "給{area:35}的{npc:2487}：先留著",
		["For {npc:2542} in {area:35}: keep it"] = "給{area:35}的{npc:2542}：先留著",
		["For {npc:2711} in {area:271}"] = "給{area:271}的{npc:2711}",
		["From {area:42} follow the road east through {zone:1430} into the {zone:1435}; Biggs guards the road junction just inside it. {npc:217412} stands a short way north of him."] = "從{area:42}沿道路向東穿過{zone:1430}進入{zone:1435}；衛兵比格斯守在入口不遠處的道路岔口。{npc:217412}站在他北邊不遠處。",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "從{zone:1455}走隧道向東穿過{zone:1426}進入{zone:1432}，沿道路前往{area:144}。",
		["Gyll, {area:35}"] = "蓋爾，{area:35}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "向北經過{area:314}；碎片在{area:333}旁的山丘上閃閃發光。",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "只有在荊棘谷的戈魯格爾給了你墜飾時",
		["Phizzlethorpe"] = "菲茲索普教授",
		["Ride back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "向東北騎回去經過{area:320}；{npc:2712}和{npc:2713}在{area:314}北邊的丘陵紮營。",
		["Shaman training"] = "薩滿訓練",
		["South-east along the loch to the dig site."] = "沿湖向東南前往挖掘場。",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "向西南前往{area:279}西邊湖岸的祈倫托營地，就在越過邊界進入{zone:1421}之處：{npc:269127}站在那裡。大法師安斯雷姆·魯因維沃爾站在它東南方的穹頂旁。",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way."] = "跟著{npc:2713}潛入{area:314}再回來；途中部落獸人會突襲你。",
		["Subdue the succubus"] = "制服魅魔",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "破碎嶺巨魔佔據{area:280}北邊的丘陵。再往北，一個破舊的木箱裡有{item:3706}；{quest:537}的{npc:2320}就站在旁邊。",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore."] = "枯鬚狗頭人在{area:321}（部落）東邊的峽谷中挖掘；從北邊繞過城鎮。他們會掉落微粒和克拉澤克要的礦石。",
		["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off."] = "辛迪加佔據{area:320}西北方的農場。一隻{npc:217589}在農場裡爬來爬去：用{npc:217412}的昆蟲學入門套件抓一隻，然後勾選完成。",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "枯木食人妖住在{area:314}南邊的丘陵；枯木巫醫站在村子裡，枯木暗影獵手守在山谷遠端。",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "被遺忘者信差帶著兩名守衛走在{area:314}西邊的道路上；把他們拉離道路。",
		["The shards lie at the far end of {area:318}."] = "碎片在{area:318}的最深處。",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins."] = "書卷在{area:280}西邊的城堡廢墟中；暗影大法師佔據著廢墟。",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "兩艘沉船在海灣西邊的海灣裡。海圖和航海日誌在船內；寶石散落在周圍的海床上。刺脊納迦在整個海灣游動。",
		["The western swamp"] = "西部沼澤",
		["The wrecked caravan lies off the road near Biggs."] = "失事的商隊在衛兵比格斯附近的路邊。",
		["The wrecks"] = "沉船",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "走回橋上：伊貝尼瑟的屍體在橋的阿拉希那一端下方。",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "沿海岸向西前往哥布林的海灣；哨兵魯魯在上方的岩石上守望。",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "小鹽齒鱷魚、沼澤紡絲蛛和沼澤虎都在道路周圍的沼澤遊蕩。",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "如果你沒有，向{npc:2381}購買{npc:2438}的披風所需的{item:2321}",
		["{item:3658}: Crushridge ogres"] = "{item:3658}：破碎嶺巨魔",
		["{item:3659}: the {object:1760}"] = "{item:3659}：{object:1760}",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}，{area:17203}的路上",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}，光明大教堂",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}，城堡裡的皇家圖書館",
		["{npc:185335}, at the same circle"] = "{npc:185335}，在同一個法陣",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}：在阿拉希高地、{zone:1443}和荊棘谷各抓一隻小動物",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}：抓住牠，用於{quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712}與{npc:2713}",
		["{npc:2713}'s errand"] = "{npc:2713}的差事",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "巨魔法師{npc:2793}佔據枯木山谷南端的洞穴。",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391}被關在聖所北端的籠子裡。釋放他並在走出去的路上保護他；之後他的保險箱就在路邊。",
		["{npc:6122} binds the incubus to you"] = "{npc:6122}會把夢魘束縛給你",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122}在{object:2101}{object:2164}的地窖裡等著。在那裡的召喚法陣使用{item:6913}，擊敗召喚出的魅魔。如果你接了{quest:65602}，也把{item:190309}交給他，放在同一個法陣並擊敗夢魘。",
		["{quest:65602}, if you took it"] = "{quest:65602}，如果你有接",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train with {npc:258098}. {npc:1573} in the {object:32372} flies to {area:271} too."] = "{zone:1453}沒有薩滿訓練師：從{object:28027}搭乘{area:2257}前往{zone:1455}，向{npc:258098}學習。{object:32372}的{npc:1573}也能飛往{area:271}。",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "飛往塞拉摩",
		["Follow the road north to {area:608}."] = "沿著道路向北前往{area:608}。",
		["Follow the road south to {area:2407}."] = "沿著道路向南前往{area:2407}。",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "沿著道路向西穿過{zone:1443}北部，前往{area:2405}的廢墟。{npc:11863}的塔就在那裡的山丘上，在前往船骸的路上。",
		["Greater Rock Elementals"] = "巨型石元素",
		["Lesser Rock Elementals"] = "次級石元素",
		["Maraudine centaurs"] = "瑪洛迪半人馬",
		["Ogres and buzzards"] = "巨魔與禿鷲",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "向西騎回道路，沿路向南離開{zone:1432}，穿過山口進入{zone:1418}。{npc:2910}和{npc:2860}在挖掘場並肩紮營。",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "向東北騎往廢棄的挖掘場；補給箱就在那裡的火煙巨魔之間。",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "向東北騎往{zone:1418}北部的矮人遺跡；箱子在暗爐矮人之間。附近的{npc:2745}是精英：離他遠一點。",
		["Ride south to {area:345}."] = "向南騎往{area:345}。",
		["Ride west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "向西騎進{area:1878}；{npc:2921}在中央的機器旁工作。",
		["Rock Elementals"] = "石元素",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "雷杜爾的下一個任務要進入{area:1517}：跳過。",
		["Shadowforge camp"] = "暗爐營地",
		["Take the boat to Theramore from the far pier."] = "在最遠的碼頭搭船前往塞拉摩。",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "火煙巨魔就在山谷南邊紮營；他們每一個都會掉落廢料。禿鷲在東邊的平原上空盤旋。",
		["The Greater Rock Elementals (level 42) walk the far south-west corner below {area:342}; pull them one at a time. The Dustbelcher Wyrmhunters and Maulers at {area:342} also drop scrap."] = "巨型石元素（42級）在{area:342}下方的西南角落走動；一次拉一隻。{area:342}的火煙獵龍者和火煙虐待者也會掉落廢料。",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}."] = "次級石元素在{npc:2921}西邊的{area:1878}遊蕩。",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "瑪洛迪半人馬佔據墓地西邊的{area:607}；每一種都會掉落圖騰。",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "石元素在{npc:2921}東南方遊蕩；巨型禿鷲和老峭壁山狗則在牠們西邊的平原上。",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "暗爐矮人在挖掘場北邊紮營；揉皺的地圖在他們的帳篷之間。暗爐隧道工和暗爐巫師身上帶著雷杜爾的鋤頭。峭壁山狗在周圍的山坡上遊蕩。",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "破損的骷髏就在巨魔東邊、石窟穴居人營地的邊緣；周圍的石窟斷骨者和石窟薩滿會掉落碎片。塞爾杜林坐在更南邊的廢棄營地旁。",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "蚌殼在荊棘谷的西北海岸，在下一份指南中：保留此任務",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit."] = "惡魔聚集在{zone:1443}南部的{area:602}：魔犬（噬法魔犬、法師獵手和靈能獵犬）、地獄魔女和地獄修女，以及坑洞周圍的末日看守隊長。",
		["The excavation crate"] = "挖掘箱",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "飛行管理員站在{area:514}的大門旁；{npc:5083}和{npc:4964}在要塞裡面。",
		["The next guide starts in Theramore."] = "下一份指南從塞拉摩開始。",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "骷髏的下一個任務「莫達洛克」要等到43級的{zone:1418}指南再做。",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "失事船隻的箱子就在{npc:11863}的塔西邊不遠的岸上。",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "塞拉摩",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "亡靈劫掠者在瑪格拉姆村南邊、瑪諾洛克集會所東邊的白骨原野上遊蕩；在最東南方使用{item:15848}引來瑪格拉姆鬼魂。",
		["escort {npc:12277} back toward the graveyard"] = "護送{npc:12277}回到墓地附近",
		["for the Dustwallow loop in the next guide"] = "用於下一份指南的塵泥沼澤環線",
		["for {npc:2786} in {zone:1455}: keep it"] = "給{zone:1455}的{npc:2786}：保留此任務",
		["for {npc:3980} in {area:271}: keep it"] = "給{area:271}的{npc:3980}：保留此任務",
		["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "給{area:439}的{npc:4454}：{zone:1446}指南會在45級時經過那裡，保留此任務",
		["for {npc:5637} in {zone:1455}: keep it"] = "給{zone:1455}的{npc:5637}：保留此任務",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "只有在你帶著{item:2868}（鐵匠製作）時",
		["{npc:11626}'s caravan stops on the road east of {area:606}. Take the quest and walk with the kodos past the {area:602}, killing the demons that jump them; talk to {npc:11596} at his camp east of the {area:596} afterwards."] = "{npc:11626}的商隊停在{area:606}東邊的路上。接下任務，跟著科多獸走過{area:602}，擊殺撲向牠們的惡魔；之後到{area:596}東邊的營地與{npc:11596}交談。",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277}被關在墓地西邊的半人馬營地。救出她，並在離開途中保護她存活；她會在墓地旁停下。",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}是一名半人馬首領，在{npc:11863}的塔北邊的西北海岸紮營。",
		["{npc:1470}, in the inn"] = "{npc:1470}，在旅店裡",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}：抓一隻，用於任務「My Little Friends」",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}，在{npc:2921}旁邊",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "{npc:2921}的下一個測試需要製作的裝備：跳過。",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618}和{npc:2817}一起在{zone:1418}中部的{area:1877}紮營。",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "{npc:5638}的下一個任務{item:6245}是遠處海岸的掉落物：跳過。",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019}站在{area:2407}西南方的{area:596}邊緣；{object:176751}散落在骸骨之間。墓地裡有{npc:217590}在爬行：用昆蟲學入門工具包抓一隻，然後勾選完成。",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "伊格納茲",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. No Skyborne riding trainer is known; the Forever client files {spell:1285849} under the one Riding skill, so {npc:4732} at {area:88} in eastern {zone:1429}, the nearest trainer to {zone:1453}, should teach it (unconfirmed). The Galestriders are sold by {npc:265756} in {area:16638} on Zephras Isle; Collectibles, Mounts · Level 40 lists them."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。目前沒有已知的天裔精靈騎術訓練師；Forever 用戶端把{spell:1285849}歸在唯一的騎術技能下，所以離{zone:1453}最近的訓練師，也就是{zone:1429}東部{area:88}的{npc:4732}，應該能教（未確認）。逐風者由微風島{area:16638}的{npc:265756}販售；收藏品的「坐騎 · 40級」列出了牠們。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:4732}在{zone:1429}東部的{area:88}教導人類，旁邊是{npc:384}的馬匹。Forever 可能允許任何種族向任何騎術訓練師學習（未確認）。收藏品的「坐騎 · 40級」列出所有顏色。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:4753}在{zone:1457}教導夜精靈，旁邊是{npc:4730}的豹：從{area:17203}搭船到{area:442}，再飛往{area:702}。Forever 可能允許任何種族向任何騎術訓練師學習（未確認），例如{zone:1429}{area:88}的{npc:4732}。收藏品的「坐騎 · 40級」列出所有顏色。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:4772}在{area:803}教導矮人，位於{area:131}東邊通往{zone:1432}的路上，旁邊是{npc:1261}的山羊。Forever 可能允許任何種族向任何騎術訓練師學習（未確認）。收藏品的「坐騎 · 40級」列出所有顏色。",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "40級且有100金幣時就能學騎術，學會後會得到一匹坐騎。{npc:7954}在{area:189}教導地精，就在{area:131}東邊，旁邊是{npc:7955}的機械陸行鳥。Forever 可能允許任何種族向任何騎術訓練師學習（未確認）。收藏品的「坐騎 · 40級」列出所有顏色。",
		["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "回到塞拉摩：特沃許和珍娜·普勞德摩爾一起在{area:514}的塔裡等候。",
		["Bloodsail camp"] = "血帆營地",
		["Bloodsail pirates"] = "血帆海盜",
		["Boat to {area:35}"] = "搭船前往{area:35}",
		["Cold Eye Basilisks"] = "冷眼蜥蜴",
		["Defeat the challengers and {npc:6238}"] = "擊敗挑戰者和{npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "每個血帆海盜都會掉落鼻煙，其中一個帶著{npc:2493}的眼睛；血帆流氓在城鎮北邊的岸上走動。海圖和命令在{area:35}南邊{area:43}的海盜營地裡。",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "每個贊吉爾信徒都可能掉落混合物；{npc:2537}在營地南部走動。",
		["Fly to {area:42} and ride east through {zone:1430} into the {zone:1435}; {npc:5476} stands by the road just past the border."] = "飛往{area:42}，向東騎過{zone:1430}進入{zone:1435}；{npc:5476}就站在剛過邊界的路旁。",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "沿著道路向東回到塞拉摩。特沃許、珍娜·普勞德摩爾和軍官們都在塔裡和{area:514}。",
		["Follow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals."] = "沿著道路向東北前往{area:310}的風險投資公司營地；礦工、勘探員和工頭會掉落水晶。",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "沿著道路從塞拉摩向西北前往{area:503}的瞭望塔。泥石穴居龜在周圍的沼澤中遊蕩。",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "逐風者：{npc:265756}，在微風島的{area:16638}。",
		["Gorilla hills"] = "猩猩山丘",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "交出獠牙後留下來：會來三波猩猩，最後是{npc:1514}。滿血再戰。",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "從隧道離開城鎮，沿著海岸向北走；信件在海灘上的血帆營地裡，「帥小子」鄧肯在那裡走動。",
		["MacKinley's next task sends you after elite ogres: skip it."] = "馬克基雷的下一個任務要你去打精英巨魔：跳過。",
		["Mirefin murlocs"] = "黑鰭魚人",
		["Mudrock tortoises"] = "泥石海龜",
		["Naga Explorers"] = "納迦探險者",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "往北騎向{area:392}的途中，{area:720}位於城鎮南邊的{area:391}外海：涉水走過沙洲淺灘。{npc:6236}會派出四名挑戰者，然後是{npc:6238}（33級），一次一個。",
		["Paladin: {quest:1661}"] = "聖騎士：{quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "騎回城鎮；病鬼站在隧道口。",
		["Ride back west along the road; {npc:217412} stands a short way north of Biggs."] = "沿著道路向西騎回去；{npc:217412}站在比格斯北邊不遠處。",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "向東騎；沿途的糾纏恐獸也會掉落研究筆記。在{area:74}邊緣搜尋，神廟遺跡就在那裡露出水面。",
		["Ride from Theramore west along the Dustwallow road into the {zone:1413} and north to {area:392} on the coast. Learn the flight path from {npc:16227}, then take the boat to {area:35} from the dock."] = "從塞拉摩沿著塵泥沼澤的道路向西騎進{zone:1413}，再向北前往海岸邊的{area:392}。向{npc:16227}取得飛行路線，然後在碼頭搭船前往{area:35}。",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "向內陸騎往迷霧谷猩猩的山丘。老邁的迷霧谷猩猩會掉落內臟；{npc:1449}坐在牠們之間。",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "向北騎往道路西邊的山丘。{npc:2535}和{npc:2536}一起站在贊吉爾村莊北邊。",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "向東北騎過奈辛瓦里的營地，沿著道路向北前往山谷頂端的營地。途中，奈辛瓦里營地東南方的叢林裡有{npc:217588}在爬行：用昆蟲學入門工具包抓一隻，然後勾選完成。",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "從礦坑向西北騎往西北海岸的海灣。巨型蚌殼躺在海底，裡面有珍珠；{npc:2624}在牠們之間游動，會掉落{item:4034}。",
		["Ride south to the giant's hut in the middle of the marsh."] = "向南騎往沼澤中央巨人的小屋。",
		["Riding at 40"] = "40級騎術",
		["Seahorn's next errand goes back to Arathi: skip it."] = "海角的下一個任務會回到阿拉希：跳過。",
		["Skullsplitter ruins"] = "劈顱遺跡",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "伊格納茲在莊園西邊、{area:504}下方的沼澤裡等候。帶他去找他的藥草葉子，別讓沼澤生物靠近他。",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "沿著道路向北前往毀壞的莊園；加爾住在旁邊的棚屋裡，鬆動的泥土在房子的轉角處。",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "從{object:28027}搭乘{area:2257}。{npc:5637}在{object:32356}旁的尋物公司大廳裡，{npc:1356}在大廳本身，{npc:2786}在{object:32383}。下一份指南會飛往{area:144}。",
		["The Bloodsail captains"] = "血帆船長",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "冷眼蜥蜴躺在礦坑西邊的岩石上。",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes."] = "暗霧蜘蛛在沼澤西北部的洞穴周圍築巢；每隻蜘蛛都會掉落眼睛。",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "黑鰭魚人聚集在{area:497}以北的海岸；在牠們旁邊的海龜身上收集完舌頭。",
		["The Mudrock Tortoises and Spikeshells sun themselves on the shore north-east of the manor."] = "泥石海龜和泥石刺殼龜在莊園東北方的岸邊曬太陽。",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do."] = "劈顱食人妖佔據礦坑東邊的遺跡；他們每一個都可能掉落獠牙，他們的豹子則一定會掉。",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "燒毀的旅店位於西邊通往{zone:1413}的道路上；衛兵的徽章就在灰燼中，蹄印則在旅店旁的泥地上。",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "船長們站在停泊於{area:43}外海的船上，每艘都有42-45級的海盜船員：斯蒂沃特船長（45）和尼哈魯船長（46）在較近的甲板上，{npc:2546}（48）在旗艦上。42級時這是小隊的戰鬥，或留到指南最後再打；如果要去，先清空每層甲板。科泰羅的卷軸在岸邊的船骸上。",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "逃兵在道路南邊、{npc:4503}小屋西邊紮營。",
		["The driftwood washes up along the eastern shore."] = "浮木沖上東岸。",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "納迦在血帆營地北邊的海灘上搜尋；牠們會掉落蘆葦。",
		["The north-west coast"] = "西北海岸",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "謎題的下一份卷軸在塵泥沼澤西部：跳過。",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "卷軸在比格斯北邊的沼澤裡。它北邊的沼澤漫步者可能會掉落卡德加的空間收斂研究筆記。",
		["The sunken temple"] = "沉沒的神廟",
		["Theramore"] = "塞拉摩",
		["Unbagwa's ritual"] = "安巴格瓦的儀式",
		["Warlock: {quest:3631}"] = "術士：{quest:3631}",
		["Zanzil's village"] = "贊吉爾的村莊",
		["for Stoley in {zone:1446}: keep it"] = "給{zone:1446}的斯杜雷：保留此任務",
		["for the {zone:1435} later"] = "稍後用於{zone:1435}",
		["for {area:1438}: keep it"] = "給{area:1438}：保留此任務",
		["for {npc:2616} in Theramore: keep it"] = "給塞拉摩的{npc:2616}：保留此任務",
		["for {npc:5635} at {area:348}: keep it"] = "給{area:348}的{npc:5635}：保留此任務",
		["for {npc:770} at the {area:99}, on the northern loop"] = "給{area:99}的{npc:770}，在北部環線上",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "只有在你帶著{item:3853}（鐵匠製作）時",
		["with the spices from Theramore"] = "帶著從塞拉摩買來的香料",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}，給「沼澤之眼」加爾",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141}在{object:2169}烹飪；{npc:5384}在{object:28027}。",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}：其他顏色，20金",
		["{npc:1356}: for {npc:1344} in {zone:1432}, keep it"] = "{npc:1356}：給{zone:1432}的{npc:1344}，保留此任務",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}，在{object:2117}的皇家圖書館",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}：{quest:93176}，來自30-40級的阿拉希高地指南",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}：抓一隻，用於{quest:93176}",
		["{npc:2487}, top floor"] = "{npc:2487}，頂樓",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "{npc:2498}的下一個贊吉爾任務從{zone:1441}開始：跳過。",
		["{npc:2535} and {npc:2536}"] = "{npc:2535}與{npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624}在西北海岸外游動，在北部環線上",
		["{npc:384}: other colours, 20g"] = "{npc:384}：其他顏色，20金",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}，在{object:2164}：由{area:392}的{npc:6251}在下一份指南結尾接收",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}：其他顏色，20金",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966}和幾個逃兵佔據著塔樓。他會攻擊你：把他打到投降為止。",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}：給{area:1438}，保留此任務",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}，在光明大教堂裡",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236}接著會提供捕風者（1791）：旋風斬武器任務線的最後有一個精英，收錄在戰士職業指南「旋風斬武器」中。",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}：給{zone:1446}的{quest:2864}，保留此任務",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}：其他顏色，20金",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910}是港口上方的高大建築；大多數任務給予者都在它的各樓層或下方的碼頭。",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260}站在旅店附近；往南幾步的商業用品供應商{npc:4897}販售加爾要的香料。",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}沒有薩滿訓練師",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "來自荊棘谷的藍珍珠",
		["Fly to {area:392}; {npc:6251} teaches in the house by the bank. Fly back to Theramore afterwards."] = "飛往{area:392}；{npc:6251}在銀行旁的房子裡授課。之後飛回塞拉摩島。",
		["Fly to {area:608}, ride south through {zone:1443} into {zone:1444} and follow the road to the dock on the {area:1108}; the boat crosses to {area:1116}, where the next guide starts."] = "飛往{area:608}，向南騎過{zone:1443}進入{zone:1444}，沿道路前往{area:1108}的碼頭；船會駛往{area:1116}，下一份指南從那裡開始。",
		["On to Feathermoon"] = "前往羽月要塞",
		["Raleigh's next errand is in the {area:796}: skip it."] = "虔誠的萊雷恩的下一個差事在{area:796}：跳過它。",
		["Ride back east to {area:1898}."] = "向東騎回{area:1898}。",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "向北騎到{area:144}，飛往{area:271}。{npc:3980}在旅店旁傳道。",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "沿道路從{area:271}往東北騎進{zone:1425}；{area:348}就在邊界後方。{npc:5635}在頂層主持，{quest:1450}照料獅鷲棲所，{npc:7884}站在旅店旁。",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "從{zone:1432}向南騎，穿過山口進入{zone:1418}；{npc:2860}在挖掘場紮營。",
		["Ride west across the {zone:1418} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "向西騎過{zone:1418}，前往{area:342}的火煙巨魔營地。{npc:2944}站在營地中央，周圍有火煙獵龍者和火煙虐待者。",
		["Ride west to the {area:1877} in the middle of the {zone:1418}; {npc:2817} camps beside Martek."] = "向西騎到{zone:1418}中部的{area:1877}；{npc:2817}在流放者馬特克旁邊紮營。",
		["Take the boat to Theramore from the far pier."] = "從最遠的碼頭搭船前往塞拉摩島。",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "沙拉克·鷹斧的下一個任務留到之後的{zone:1425}指南。",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "滾燙的雛龍在{npc:2888}東邊的峽谷中築巢；別惹烈焰守護者（精英）。{item:4612}很少掉落：刷怪時掉了就拿著。",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "殘破的骷髏躺在石窟穴居人營地的邊緣；殺死埃格蒙德的{quest:739}就在石窟斷骨者之間走動。",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "前兩個籠子一起放在{npc:5634}南邊的枯木村落；第三個在東邊的下一個村落。每隻枯木食人妖都可能掉落項鍊。",
		["Theramore"] = "塞拉摩島",
		["Warlock: {quest:3631}"] = "術士：{quest:3631}",
		["Witherbark villages"] = "枯木食人妖村落",
		["grind on {npc:2725} at {area:339}, {zone:1418}"] = "在{zone:1418}的{area:339}刷{npc:2725}",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}，{object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616}站在船靠岸的碼頭上。",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}的下一個任務不給經驗值：跳過它。",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888}獨自在挖掘場東南方的{area:1898}紮營。",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}的下一個任務是精英狩獵：跳過它。",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634}在{area:348}東邊的路上紮營。",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "{npc:5634}的雞尾酒需要卡林多的材料：跳過它。",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}，在頂層的飛行管理員旁邊",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884}會持續收購項鍊：多的都交出去",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "回到{area:1117}。那裡的每個憎世納迦都可能掉落鱗片。",
		["Boat to the {area:1108} and ride east across {zone:1444} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "搭船前往{area:1108}，向東騎過{zone:1444}，前往道路北邊的恐怖圖騰營地。{npc:7956}在營地外等候；放出中央圍欄裡的小精龍，保護{npc:7956}和至少六隻小精龍存活。",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "搭船前往{area:1108}，向東騎進{area:1105}。{npc:14637}在海岸的任務需要45級。",
		["From Theramore, fly to {area:608} and ride south out of {zone:1443} into {zone:1444}; the road leads west to the {area:1108} dock, where the boat crosses to Feathermoon on {area:1120}."] = "從塞拉摩飛往{area:608}，向南騎出{zone:1443}進入{zone:1444}；道路向西通往{area:1108}的碼頭，船會從那裡渡海前往{area:1120}的羽月要塞。",
		["Giants and elementals"] = "巨人與元素",
		["Gordunni ogres"] = "戈杜尼巨魔",
		["Grimtotem camp"] = "恐怖圖騰營地",
		["Grimtotem tauren"] = "恐怖圖騰牛頭人",
		["Grind to 45"] = "練到45級",
		["Hatecrest naga"] = "憎世納迦",
		["Hearth to Feathermoon."] = "使用爐石回到羽月要塞。",
		["Rage Scar yetis"] = "怒痕雪人",
		["Ride back north-west to the {area:1108} dock and take the boat to the island."] = "向西北騎回{area:1108}的碼頭，搭船前往島上。",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "騎回{area:1108}；那個哥布林站在碼頭旁。",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "沿著道路向西騎回去，然後向北進入怒痕雪人的山丘。這裡的每隻雪人都可能掉落毛皮；其中可能會掉落{quest:7735}，{npc:7852}也會為它付錢。",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "向東騎往雪人山谷東南方山丘上的戈杜尼營地：戈杜尼術士和薩滿佔據營地，戈杜尼蠻兵在周圍和更北邊的山坡上遊蕩。",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "向北騎進雪人山谷。每隻深痕雪人都可能掉落厚毛皮；{npc:5346}（48級）在中央徘徊。",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "向東北騎往{zone:1441}邊界上的夜精靈前哨站。",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "向東南騎往木爪豺狼人處；信使的背包在他們南邊的營地裡，裡面的一個包裹會開始一個送往{area:489}的任務。祖卡什蟲巢就在南邊：一路殺到關著拉斯卡爾的繭，救出他並在離開途中保護他存活。",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "向西騎往山丘腳下友善的山嶺巨人。他周圍的大地行者和峭壁巨人是精英：離牠們遠一點。",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "每當{npc:7774}停下來亂逛時就搖鈴，帶她向南到{npc:7765}處。",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in northern {zone:1446}, the next zone on the route; come back to {npc:14637} on the {area:1108} afterwards."] = "組隊打{area:978}代替練等能更快達到目標。這座食人妖城市位於{zone:1446}北部，也就是路線的下一個地區；之後回到{area:1108}的{npc:14637}處。",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "海岸巨人、深海巨人和波濤巨人（精英巨人）在碼頭北邊的海岸涉水：用{item:18904}電擊一隻，然後殺死縮小後的巨人。海元素和巨型海元素在同一片浪中漂浮。",
		["Swim south from the island to the {area:1121}. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "從島上向南游到{area:1121}。憎世毒蛇守衛和憎世巫師佔據那裡；{npc:8136}（47級）在南端的洞穴裡等著。先拉他的守衛。",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "搭船前往{area:1108}，沿著海岸向南走到海灘上失事的划艇。",
		["The courier's boat"] = "信使的船",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "沿著島嶼向南走到納迦遺跡；涼亭就在遺跡之間。",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "你在{area:1108}的碼頭結束：{zone:1446}指南從這裡向東出發開始。",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "給{zone:1457}的泰蘭妲：路線會在47級時帶你去那裡",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "在{zone:1444}的{area:1105}擊殺{npc:5292}練等",
		["if you carry {quest:1100} from {zone:1441}"] = "如果你帶著{zone:1441}的{quest:1100}",
		["{area:978} instead of grinding"] = "以{area:978}代替練等",
		["{item:11463}, from the backpacks"] = "{item:11463}，來自背包",
		["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}的補充任務是55級：跳過。",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936}接著會要你把消息帶到{zone:1457}：跳過，{area:976}會改派你去那裡。",
		["{npc:3936}, beside him"] = "{npc:3936}，在他旁邊",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}：他的回覆稍後在{area:702}等你",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774}在{npc:7765}北邊的山丘上、北泉鷹身人之間遊蕩；她的鈴鐺在她旁邊的箱子裡。",
		["{npc:7774}'s escort"] = "護送{npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}，在要塞頂端",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}留到大陸環線結束時再打。",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Fly from {area:976} to Theramore, take the boat to {area:150} and fly to {area:1537}. Train."] = "從{area:976}飛往塞拉摩，搭船前往{area:150}，再飛往{area:1537}。訓練。",
		["Fly to {area:348}. {zone:1425} guide starts here."] = "飛往{area:348}。{zone:1425}指南從這裡開始。",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "沿著海岸向南前往海盜灣。南海海盜擠滿了海灘和船隻：沿著邊緣推進，一次拉一隻。{npc:7883}站在另一頭；{npc:7881}被偷的貨物在營地裡。",
		["From the {area:1108} dock, boat to Feathermoon and fly to {area:489}, then ride east through {zone:1441} to the {area:2240} on the {area:439}. {npc:4454} and {npc:4630} are in the camps beside the track; {npc:4709} stands by the goblin camp."] = "從{area:1108}的碼頭搭船前往羽月要塞並飛往{area:489}，然後向東騎過{zone:1441}，前往{area:439}上的{area:2240}。{npc:4454}和{npc:4630}在賽道旁的營地裡；{npc:4709}站在哥布林營地旁。",
		["Gives the {item:8585}"] = "會給你{item:8585}",
		["He runs off to keep Rizzle busy"] = "他跑去拖住瑞茲爾",
		["Hearth to {area:976}."] = "用爐石回{area:976}。",
		["Pool by {area:979}"] = "{area:979}旁的水池",
		["Ride back west to {area:976}."] = "向西騎回{area:976}。",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch."] = "向西騎回{area:976}。廢土強盜和廢土竊賊佔據沿途的沙丘；他們都可能帶著水袋。",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "向東騎過沙丘，前往東北海岸的哥布林港口。",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "向西北騎往沙丘中的森提帕爾蟲巢。所有森提帕爾都可能掉落昆蟲肢體。",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "向西北騎往{area:979}的沙怒食人妖營地。在水池邊緣使用{item:8584}；食人妖站得很近，先拉最近的。",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "向南騎進{quest:3362}。灌木露水收集者會掉落腺體；只有一部分是飽滿的，所以保留飽滿的露水腺。長瘤的灌木獸和灌木塑根者也在山谷裡。灌木獸是48-50級，比你高：一次拉一隻。",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside."] = "向南騎過{area:1938}前往{area:981}，也就是哈札里的隧道；謝申克的設備在深處。",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "向南騎往{area:1938}的挖掘營地。{npc:7771}會給你一頂探測頭盔：戴上它就能看見{quest:3161}土堆，它們密集分布在營地周圍的沙地上，以及往西南方巨魔那邊。",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "向東南騎離{area:439}進入{zone:1446}。{area:976}就在邊界內側。",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first."] = "向東南騎往{area:985}。{npc:7847}站在南方廢土營地的中央：先清掉他周圍的敵人。",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "向西南騎往巨魔營地。裡面滿是砂槌蠻兵和砂槌執行者（46-48級）；{npc:12046}（49級）站在中央，周圍有守衛：先清掉守衛。",
		["Rizzle's plans"] = "瑞茲爾的設計圖",
		["The Wanted poster beside him"] = "他旁邊的通緝告示",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "小烏龜{npc:5955}躲在山谷北端。帶他回家找他的妻子{npc:6015}，她在{area:977}東邊的水邊：他走得很慢，沙漠的野獸會攻擊他，所以要保住他的性命。",
		["The pool by {area:979}"] = "{area:979}旁的水池",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "同一張告示：{npc:7847}要很久以後才會出現，在{area:976}之後",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later."] = "更強的廢土遊蕩者、廢土暗法師和廢土刺客在{area:976}東南方、強盜的南邊紮營。南方營地中央的{npc:7847}留到之後再處理。",
		["The {area:1938}"] = "{area:1938}",
		["Wastewander bandits"] = "廢土強盜",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "趁{npc:4709}拖住瑞茲爾說話時，他的設計圖就無人看守地放在賽道對面的地精營地裡。",
		["for {zone:1457}: the route takes you there at 47"] = "交給{zone:1457}：路線會在47級時帶你去那裡",
		["{npc:11758}, on the east side of town"] = "{npc:11758}，在城鎮東側",
		["{npc:5955}'s escort"] = "護送{npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}，在水塔旁",
		["{npc:7408}, next to him"] = "{npc:7408}，在他旁邊",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "{npc:7583}的下一種材料生長在{zone:1425}，而路線不會再帶你回來：跳過。",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}：他的箱子要送到{area:702}，稍後",
		["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "{npc:7881}的下一批貨要送回{area:35}：跳過。",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}，在港口的旅店裡",
		["{quest:2864}, north side of town"] = "{quest:2864}，在城鎮北側",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "灰鬃野豬和紅石蜥蜴共同分布在要塞西南方的山坡上。遠離更南邊的地獄野豬：牠們是52級。",
		["Back to {area:144}"] = "返回{area:144}",
		["Boars and basilisks"] = "野豬與蜥蜴",
		["Fly from {area:144} to {area:150}, take the boat to {area:442} and fly to {area:702}."] = "從{area:144}飛往{area:150}，搭船到{area:442}，再飛往{area:702}。",
		["Fly from {area:348} to {area:42}."] = "從{area:348}飛往{area:42}。",
		["Hearth to {area:144}. The {zone:1427} guide starts at {area:1446}: from here, ride south into the {zone:1418}, west past the Horde town of {area:340} and up the trail into the gorge."] = "用爐石回到{area:144}。{zone:1427}指南從{area:1446}開始：從這裡向南騎進{zone:1418}，向西經過部落城鎮{area:340}，再沿小徑上到峽谷。",
		["Hearth to {area:348}."] = "用爐石回到{area:348}。",
		["Hearthstone on cooldown? Ride back north-west."] = "爐石在冷卻中？騎回西北方。",
		["Ride back east to {area:1438} and fly to {area:144}."] = "向東騎回{area:1438}，飛往{area:144}。",
		["Ride back north to Ironband's camp."] = "向北騎回鐵環挖掘場的營地。",
		["Ride east along the south shore of the loch to Ironband's camp."] = "沿湖的南岸向東騎到鐵環挖掘場的營地。",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "向東騎過{zone:1430}進入{zone:1435}，再沿道路向南進入{zone:1419}。血法師的營地是路旁的第一站。",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it."] = "向北騎到{zone:1425}中部的{area:351}。綠色淤泥怪和玉石軟泥怪在周圍到處爬行。",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "先沿道路繼續向東前往要塞：{item:6091}在離開{area:42}一小時後過期，而血法師要的野獸會花更久。",
		["Ride south through the pass into the {zone:1418}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "向南穿過山口到{zone:1418}北緣：石窟穴居人在那裡的{area:1517}外挖掘。雕紋甕和洋紅色蘑菇叢在他們的洞穴和隧道中，在地城本身之外。",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down."] = "向東南騎到{zone:1425}南部的{area:355}（邪枝食人妖的階梯神廟），爬到頂端。守護者奇爾加和{npc:8636}（精英，50級）站在上面：碰到頂端就立刻下來。",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "向西騎：饑餓的彎牙土狼在血法師營地南邊不遠的乾燥丘陵遊蕩；厚甲毒刺蠍（50級）在北部中央爬行。{npc:5982}禿鷲在整片區域上空盤旋。一次只拉一隻。",
		["Scorpoks and snickerfangs"] = "毒刺蠍與彎牙土狼",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "穿過傳送門進入{zone:1457}。Temple of the Moon在城市南部。",
		["Temple of the Moon"] = "Temple of the Moon",
		["The bloodmages"] = "血法師",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "血法師的第二階段用增益物品換取同樣的材料，不給經驗值：跳過它。",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "德魯伊訓練師在塞納里奧區；{zone:1455}沒有",
		["The {area:1517} dig"] = "{area:1517}挖掘場",
		["for {quest:2990} at {area:1438}, later"] = "之後給{area:1438}的{quest:2990}",
		["the book on her table"] = "她桌上的書",
		["the soil comes from {zone:1449}, later"] = "土壤之後來自{zone:1449}",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}，在樹頂",
		["{npc:7740}, beside her"] = "{npc:7740}，在她旁邊",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}：上一份指南在這裡綁定爐石，所以這一步通常會立即完成",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "{npc:7907}的下一個差事要去{zone:1446}：跳過它。",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}：先留著，羽毛在{zone:1428}指南的最後",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "{npc:8022}的下一個任務{item:9471}是{area:978}的任務：跳過它。",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}，在要塞頂端",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "之後給{zone:1455}的{npc:8256}",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}. {area:1446} is the scaffolded camp on the north-west rim."] = "從{area:144}向南騎進{zone:1418}，然後向西經過部落城鎮{area:340}（離它遠一點），再沿小徑上到{zone:1427}。{area:1446}是西北邊緣搭著鷹架的營地。",
		["Golems and elementals"] = "傀儡與元素",
		["Greater Lava Spiders"] = "巨型熔岩蜘蛛",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "重型作戰傀儡在卡拉然下方的大熔爐底部巡邏；熔岩元素在牠們之間飄蕩。傀儡和元素會掉落油，元素會掉落核心。",
		["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "卡拉然·溫布雷站在{area:1446}南邊的大熔爐邊緣。聆聽他的故事。",
		["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "向東騎過大熔爐，前往東南方的{area:247}。木製廁所裡的囚犯要15塊{item:4306}，以及擊殺周圍挖掘場的八名黑鐵地質學家。如果你找到了鑰匙，也能用它打開廁所。",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "黑鐵工頭和黑鐵奴隸販子在大熔爐各處驅趕奴隸，任何一個都可能帶著{item:10551}。黑鐵鍛造師在中央的熔爐工作（{item:18959}），黑鐵哨兵站在南邊的山脊上（偵查員的望遠鏡）。任何{object:147516}都可能掉落{item:11818}：留著它。",
		["The Grimesilt outhouse"] = "煤渣挖掘場的庫房",
		["The dwarf stands by the road at the dig site. Follow him north along the road and fight off the {object:147516} ambushes. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "杜里奧斯·裂石站在挖掘場旁的道路邊。跟著他沿道路向北，擊退{object:147516}的伏擊。結束後，閱讀他留在{area:1959}道路上的{object:175704}。",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "那名夜精靈獨自站在{area:1446}西邊。聽他的故事。",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "囚犯的下一個任務「{zone:1446}的帳本」會派你去{zone:1435}和{zone:1445}：跳過它。",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "蜘蛛在峽谷西南部的高地和熔岩池間遊蕩。",
		["The {object:179827} board"] = "{object:179827}告示板",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443}的入口在大熔爐北部。秘密設計圖：熾熱助熔劑在上層平台；燻火龍在更深處的熔岩池中游動，把牠們拉到邊緣。遠離深處的{npc:14621}和他的精英守衛。",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}：上一份指南用爐石把你送到這裡，所以這一步通常會立即完成",
		["{object:147516} dwarves"] = "{object:147516}矮人",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "阿克瑟努斯站在{object:171709}的國王麥格尼身旁。",
		["Bind and train"] = "綁定爐石並訓練",
		["Bones and equipment"] = "骨頭與裝備",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "穿越環形山南部，前往坡道旁的{npc:9619}。",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "恐龍骨頭散落在西南部的劍龍群中：劍龍是精英，在牠們周圍撿骨頭，其餘的從雙帆龍身上取得。探險隊的{item:11112}在西南部叢林。",
		["Eastern Pylon"] = "東部水晶塔",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "在{zone:1452}的{npc:9298}處完成：保留此任務",
		["Escort {npc:9999}"] = "護送{npc:9999}",
		["Fly from {area:144} to {area:1537}."] = "從{area:144}飛往{area:1537}。",
		["For {npc:7775} in {zone:1444}: keep it"] = "交給{zone:1444}的{npc:7775}：保留此任務",
		["Four rune rubbings in {zone:1447}: keep it"] = "在{zone:1447}拓印四個符文：保留此任務",
		["From {area:144} fly to {area:150}, take the boat to Theramore and fly on to {area:976}. {npc:9619}'s first quest in the crater needs level 48: finish the level here if you are short."] = "從{area:144}飛往{area:150}，搭船到塞拉摩，再飛往{area:976}。{npc:9619}在環形山的第一個任務需要等級48：若等級不足，先在這裡練完這一級。",
		["Grind to 50"] = "練到50級",
		["Grind to 51"] = "練到51級",
		["Gryfe"] = "葛萊夫",
		["Lar'korwi Mates and the raft"] = "拉克維的配偶與木筏",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "帶{npc:9999}向北前往{area:541}。他昏倒時，對他使用{item:11804}把他叫醒。",
		["Northern Pylon"] = "北部水晶塔",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "沿坡道騎下環形山：{npc:9619}在坡道底部紮營。",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "向東騎往{area:537}，爬上去，在山頂附近的熔岩噴口使用{npc:10541}。",
		["Ride north along the east side of the crater to {area:541}, the camp in the caves of the northern cliff. Give the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "沿著環形山東側向北騎往{area:541}，也就是北面懸崖洞穴中的營地。遠離精英魔暴龍和劍龍。從現在起，拾取沿途經過的每一個能量水晶和{object:157936}。",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "沿東側向北騎往猩猩高地。55級的猩猩{npc:9622}在最深的洞穴裡：先清掉洞口的猩猩。",
		["Ride north along the western jungle back to the refuge."] = "沿西部叢林向北騎回避難營。",
		["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "向北騎往{area:1943}，機器人站在猩猩群中。不要進入那裡的深洞。",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "沿東面懸崖向南騎往坡道底部的{npc:9619}。",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "沿東側向南騎。幼雙帆龍在東部叢林覓食，{npc:9165}在東面懸崖附近飛行；兩者都會掉落{npc:9998}要的鱗片。",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "向南騎往環形山中央的{area:537}，然後向東進入東部叢林。水晶簇遍布整個環形山，許多在{area:537}周圍：每種顏色多拿幾個。血瓣花鞭笞者和血瓣花猛擊者會掉落花瓣；探險隊的{item:11113}在東部叢林中一處廢棄的營地裡。",
		["Ride west back to the refuge."] = "向西騎回避難營。",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "從{npc:9619}向西騎：異種蟲巢穴佔據環形山南部。在孵化室（掛著幼蟲的洞室）使用未使用的採集瓶。格里什異種蠍和格里什工蠍會掉落{quest:3764}；若還需要擊殺數，{npc:9166}在南面懸崖築巢。",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "從{area:976}向西出發，前往通往{zone:1449}的長坡道。{npc:9619}在坡道底部紮營，位於環形山東南角。",
		["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "向西經過{area:541}，再沿西側向南前往{area:543}：哥布林{npc:10302}坐在水邊。",
		["Running the {area:1417} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "組隊打{area:1417}代替練等能更快達到目標。單人練等請跳過此步驟。",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in the north-west of {zone:1446}, just north of {area:976}."] = "組隊打{area:978}代替練等能更快達到目標。這座食人妖城市位於{zone:1446}西北部，就在{area:976}北邊。",
		["The Centipaar silithid crawl around the {area:982} in western {zone:1446}, just east of the crater ramp. The Workers are the easiest pulls."] = "森提帕爾異種蟲在{zone:1446}西部的{area:982}周圍爬行，就在環形山坡道東邊。工蠍最容易拉。",
		["The Gorishi hive"] = "格里什蟲巢",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "拉克維的配偶在{npc:9619}西邊的叢林中徘徊。破碎的木筏在那裡的湖岸上；小包就在旁邊的水裡。把指南針、地圖和鑰匙留給{npc:8737}。環形山的任何野獸都可能掉落{item:11116}：右鍵點擊它。",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "死去的蛇頸龍躺在{npc:9619}北邊的水邊。",
		["The east side"] = "東側",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55."] = "猩猩住在{area:541}東邊的{area:1943}。把牠們的毛皮留給{npc:9619}。不要進入最深的洞穴：{npc:9622}是55級。",
		["The gorillas of {area:1943} come in small groups and drop nothing for you yet; {npc:9619}'s pelt quest comes later. Stay out of the deepest cave: {npc:9622} is level 55."] = "{area:1943}的猩猩成小群出現，目前還不會為你掉落任何東西；{npc:9619}的毛皮任務稍後才有。不要進入最深的洞穴：{npc:9622}是55級。",
		["The pelts come after loop 2, on the gorilla plateau"] = "毛皮在第二輪之後，到猩猩高地取得",
		["The pylon stands on the eastern cliffs."] = "水晶塔位於東面懸崖上。",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "水晶塔位於避難營東邊的山坡上。{npc:9166}在周圍山坡盤旋：擊殺牠們算入{npc:9997}的任務，並會掉落{npc:9998}要的鱗片。",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "水晶塔位於西面懸崖上。{npc:9167}在整個西側上空飛行。",
		["The relics are in the {zone:1428}: keep it"] = "聖物在{zone:1428}：保留此任務",
		["The wooden sign beside {npc:9997}"] = "{npc:9997}旁邊的木牌",
		["Western Pylon"] = "西部水晶塔",
		["Xiggs waits in the {object:32359}."] = "希格斯在{object:32359}等候。",
		["grind on the Wastewanderers or Dunemaul ogres around {area:976}"] = "在{area:976}周圍擊殺廢土強盜或砂槌巨魔練等",
		["grind on {npc:5458} at {area:982}, {zone:1446}"] = "在{zone:1446}的{area:982}擊殺{npc:5458}練等",
		["grind on {npc:6514} at {area:1943}, {zone:1449}"] = "在{zone:1449}的{area:1943}擊殺{npc:6514}練等",
		["{area:537} and the eastern jungle"] = "{area:537}與東部叢林",
		["{area:978} (optional)"] = "{area:978}（可選）",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}：交給{zone:1447}的奧汀克，保留此任務",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}：上一份指南用爐石把你送到這裡，所以這一步通常會立即完成",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}，在洞穴深處",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}：軟泥怪在{zone:1448}，保留此任務",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618}就站在避難營外。",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "{npc:9684}的巢穴位於{npc:9619}北邊的叢林，在東面懸崖下方：在那裡使用{item:11568}。{npc:9684}是56級：滿血再開打。",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9997}的朋友{npc:9999}失蹤了。",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避難營入口",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}，在避難營入口",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999}坐在環形山中央{area:537}的東南坡上。",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Climb back to {npc:8405} at the {area:1224}, above the ruins."] = "爬回遺跡上方{area:1224}的{npc:8405}處。",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "爬上{area:249}頂端，把頭顱插在鬆軟的土堆上。",
		["Druid training"] = "德魯伊訓練",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "在{zone:1452}的{area:2255}交給{quest:4808}：保留此任務",
		["Fly from {zone:1455} to {area:150} and take the boat to {area:442}."] = "從{zone:1455}飛往{area:150}，搭船前往{area:442}。",
		["Fly from {zone:1455} to {area:69}."] = "從{zone:1455}飛往{area:69}。",
		["Fly to {area:1438}."] = "飛往{area:1438}。",
		["Fly to {area:150} and take the boat to {area:442}, then the boat on to {area:702}."] = "飛往{area:150}，搭船前往{area:442}，再轉船前往{area:702}。",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "沿著道路向西走，然後向北爬上{area:251}的哥布林營地。",
		["From the {area:442} dock, fly to {area:415}."] = "從{area:442}碼頭飛往{area:415}。",
		["Mosshoof Coursers"] = "苔蹄快步者",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "可選：{npc:8395}要兩根完整的角鷹獸羽毛，從他營地周圍的角鷹獸身上取得。資料沒有列出這個任務的經驗值。",
		["Optional: {npc:8888}'s ghost stands on his tomb on the great chain inside {area:254}, and only the dead can see him. If you die near the mountain anyway, run your spirit to him before resurrecting."] = "可選：{npc:8888}的鬼魂站在{area:254}內巨大鎖鏈上的墳墓上，只有死者能看見他。如果你反正在山附近死了，在復活前讓你的靈魂跑去找他。",
		["Read the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript."] = "閱讀{area:251}西南方遺跡中{object:147516}營地裡的石板，抄下文字。",
		["Ride back east along the road to the Vigil."] = "沿著道路向東騎回摩根的崗哨。",
		["Ride back to {area:1438} and fly to {area:348}. The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "騎回{area:1438}，飛往{area:348}。梟獸羽毛散落在{area:348}南邊和東邊、梟獸遊蕩的{zone:1425}各處地上；這裡的怪物現在比你低很多。",
		["Ride east along the road out of {zone:1440} into {zone:1447} to the Sentinels' camp at {area:3137}."] = "沿著道路向東騎出{zone:1440}進入{zone:1447}，前往{area:3137}的哨兵營地。",
		["Ride north out of {area:69} through the pass into the {zone:1428}; {area:2418} sits at the top, in the south-east of the Steppes."] = "向北騎出{area:69}，穿過山口進入{zone:1428}；{area:2418}位於頂端，在燃燒平原東南部。",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "從神殿向東北騎：{npc:8405}在{area:1224}紮營，位於道路上方的山丘上。",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "游到{zone:1447}南端外海的小島：{npc:8392}在紀念碑旁等候。",
		["Thaurissan Relics"] = "索瑞森遺物",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "火腹巨魔佔據摩根的崗哨北邊的巨石，火腹蠻兵在它的東側。",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "精靈貴族的鬼魂在神殿周圍的遺跡中出沒；哈達爾薩特佔據神殿北邊不遠處的營地。",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "{area:1221}的惡鞭納迦身上帶著{item:13815}。{npc:8507}的四塊符文石立在遺跡之間：對每一塊使用他的{item:10445}。",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "最近的苔蹄快步者在{area:1224}東北方、往{area:1219}方向的山丘上覓食；更大的一群在南邊的空地上遊蕩。",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered."] = "遺物是散布在{area:251}周圍{area:250}的雕刻石塊：點擊它們，直到資訊全部取回。",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "神殿位於{zone:1447}西南角，在{area:3137}南邊。",
		["The wildkin are in {zone:1452}: keep it"] = "梟獸在{zone:1452}：保留此任務",
		["The {area:1221}"] = "{area:1221}",
		["The {quest:4296}"] = "{quest:4296}",
		["Use the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "在{area:251}東邊山坡上的{npc:7047}快死時對牠使用{item:12284}，然後拾取牠留下的精華。",
		["Wildkin feathers"] = "梟獸羽毛",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}：{npc:7864}，約10%",
		["{npc:5111}: the last guide binds here, so this usually ticks at once"] = "{npc:5111}：上一份指南在這裡綁定爐石，所以這一步通常會立即完成",
		["{npc:7363} waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have."] = "{npc:7363}在要塞西南方的山丘{area:2517}等候。沿途的{zone:1419}怪物會掉落不完美的德萊尼水晶碎片；把你有的帶給她。",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420}在北邊的{area:1219}紮營；他的裝備散落在他東南方不遠處的{area:1220}各處。",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty."] = "{npc:9176}和黑石獸人佔據{area:251}西邊、{area:254}山腳下的營地和要塞。一次拉一隻；每個獸人和座狼都可能掉落徽章，所以一直殺到你有五十個為止。",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}：黑石獸人會掉落徽章，在整個燃燒平原期間保持此任務進行中",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455}沒有德魯伊訓練師：走傳送門上到{zone:1457}，在{area:1658}學習，然後回到下方的{area:702}。",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Ends in the {zone:1413}: keep it"] = "在{zone:1413}完成：保留此任務",
		["First crater"] = "第一個坑洞",
		["Five feathers buy a little Timbermaw reputation"] = "五根羽毛可換取少量木喉聲望",
		["Fly from {area:1998} to the Sanctuary's end of the road, or ride south along it."] = "從{area:1998}飛往道路上聖地那一端，或沿路向南騎。",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "沿著道路向北前往{area:1769}的洞口；{npc:15395}守在那裡。",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "沿著道路向北前往坑窪山谷，走到每個坑洞，並擊殺途中的熱能野獸和熱能恐獸。",
		["Keep her alive until she is out of the cave"] = "在她離開洞穴之前保住她的性命",
		["Oozes"] = "軟泥怪",
		["Ride east to the night elf camp at {area:1998}."] = "向東騎往{area:1998}的夜精靈營地。",
		["Ride north out of {area:415} into {zone:1448}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "向北騎離{area:415}進入{zone:1448}。熊怪{npc:11554}站在{area:2479}南邊的路旁。",
		["Ride north to {area:1769} (or fly back to {area:1998} first) and through the tunnel into {zone:1452}; follow the road east to the goblin town of {area:2255}."] = "向北騎往{area:1769}（或先飛回{area:1998}），穿過隧道進入{zone:1452}；沿著道路向東前往哥布林城鎮{area:2255}。",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "薩爾法站在隧道的{zone:1452}那一端：保留此任務",
		["Second crater"] = "第二個坑洞",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "走進洞穴：{npc:11558}和{npc:11557}就站在入口內。",
		["Take the boat from {area:702} to {area:442} and fly to {area:415}."] = "從{area:702}搭船前往{area:442}，再飛往{area:415}。",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "被詛咒的軟泥怪和被污染的軟泥怪在{area:1763}和{area:1765}周圍的溪流與魔化水池中滑動：擊殺牠們，並對牠們的殘骸使用拉里斯的軟泥怪採樣瓶。",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "死木熊怪住在{npc:11554}西南方的村莊裡；保留牠們掉落的死木頭飾羽毛。",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}."] = "{area:1762}的死木熊怪佈滿洞穴西邊的山丘。死木復仇者可能掉落{quest:8470}。",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back."] = "碧火薩特佔據道路西邊的山谷，{npc:9454}在山谷深處。",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{area:2618}東邊{area:1767}的曲木樹人帶著{item:11503}。",
		["The vial is filled in {zone:1457}: keep it"] = "瓶子在{zone:1457}裝滿：保留此任務",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "第三個坑洞",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}; Trey Lightforge's remains lie beside her."] = "在{area:1763}中央的腐化月井使用{item:12922}。如果你釋放了{npc:11018}，回到{area:1770}找魅魔{npc:9518}；特雷·萊弗治的殘骸就在她旁邊。",
		["{area:1763} again"] = "再次前往{area:1763}",
		["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763}是山谷北邊的神殿廢墟。部分教徒會掉落{item:13140}，大約每三十次擊殺一次：它能打開後方洞穴{area:1770}裡{npc:11018}的牢房。若有掉落，先清出離開的路再釋放她；若沒有，跳過她的任務。",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618}是西北方的薩特山谷，{npc:10648}在山谷盡頭。他會掉落{quest:939}；每個碧火薩特都可能掉落{item:11674}。",
		["{item:13140}, a rare drop"] = "{item:13140}，稀有掉落",
		["{npc:11016}, in {area:1770}"] = "{npc:11016}，在{area:1770}",
		["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57"] = "{npc:11557}：三十塊{quest:6031}，在57級再次經過時繳交",
		["{npc:11558}: the Timbermaw speak to you only from Neutral"] = "{npc:11558}：木喉熊怪只有在中立以上才會和你說話",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395}在{zone:1448}北端等候",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}，在{npc:11554}東邊的廢墟裡",
		["{quest:8470}, a rare drop"] = "{quest:8470}，稀有掉落",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "回到山丘：只有冰薊雪人女王和冰薊雪人王身上帶著角。繼續擊殺雪人直到54級：在那之前哈魯的梟獸任務是紅色的。",
		["Follow the road east across the zone to the chapel."] = "沿著道路向東穿過本區前往禮拜堂。",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "沿著道路向西前往溫泉旁{npc:9298}的營地。",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "沿著南邊的道路向東進入{zone:1423}；{area:2262}的廢墟在道路南邊。{npc:10926}的鬼魂在南端的廢屋旁玩耍。",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "依照{npc:9298}的指示前往{area:2256}入口，途中經過霜槌巨人：一次通過一個。",
		["For Kernda in {area:1769}: keep it"] = "給{area:1769}的克爾達：保留此任務",
		["Free Darrowshire Spirits: talk to them"] = "解放達隆郡居民的靈魂：與他們交談",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "冰薊雪人住在{area:2244}南邊的山丘上，冰風奇美拉在往{area:2255}方向的山谷裡。",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "保留此任務：{zone:1444}的格雷甘稍後會調製藥劑",
		["On {npc:10978}, by the inn"] = "在旅店旁的{npc:10978}處",
		["Optional: {area:1417}"] = "可選：{area:1417}",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "撿起馬車周圍的補給物資，並從附近的梟獸身上奪回{npc:10301}的護符。",
		["Pristine Yeti Horns"] = "完美的雪人角",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "向北騎往{area:2627}。{npc:12384}住在廢棄的小屋裡，他的收據冊在附近的旅店廢墟中。",
		["Ride north-west back to the village."] = "向西北騎回村莊。",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "沿著山谷向東南騎往{area:2245}雪地中{npc:10301}的受損箱子，他的馬車殘骸就在它東邊。",
		["Ride west along the road to the night elf village."] = "沿著道路向西騎往夜精靈村莊。",
		["Ride west along the road to {npc:10301}."] = "沿著道路向西騎往{npc:10301}處。",
		["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "打完雪人後還不到54級？組隊打{area:1417}（50-54級）代替練等能更快達到目標。之後回到{area:2255}。",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "{zone:1448}的死木大鍋：保留此任務",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "禮拜堂西邊{area:2264}周圍的天譴軍會掉落兩種天譴石；達隆郡居民的靈魂會從牠們身上升起：與每一個交談以解放它。",
		["The Winterfall camp"] = "冬泉營地",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "冬泉熊怪的村莊位於{area:2255}東邊：冬泉薩滿（56-57級）、冬泉巢穴守衛（55-56級）和冬泉巨熊怪（57-58級），都比你高。先殺薩滿，他們會治療，並從邊緣開始拉。後方洞穴裡的{npc:10738}是精英：不要進去。",
		["The next guide starts here and flies to {area:3197}."] = "下一份指南從這裡開始，然後飛往{area:3197}。",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "遺跡位於{area:2253}南邊結冰湖泊的周圍。拾取散落在遺跡中的四塊遺物碎片，以及梟獸遊蕩處地上的月光羽毛。",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "洋娃娃的三個部分在{area:2262}的廢屋裡；撿起其中一個可能會引出鬼魂。把它們組合成洋娃娃。",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "冬泉西部營地位於{npc:11556}和{npc:9298}之間的山丘上。這裡的任何熊怪都可能掉落{item:12771}（約十分之一），極少數會掉落{quest:8471}：掉了哪個就右鍵點擊它。保留熊怪掉落的{quest:6031}給梅羅什。",
		["The western Winterfall furbolgs drop the beads."] = "西部的冬泉熊怪會掉落珠串。",
		["The {area:2247}"] = "{area:2247}",
		["Walk through {area:1769} to {zone:1448} and fly on to the Eastern Kingdoms ({area:442}, the boat to {area:150}). Fly to {area:271} and ride north up the road through Alterac to {area:3197}."] = "穿過{area:1769}前往{zone:1448}，再飛往東部王國（{area:442}，搭船到{area:150}）。飛往{area:271}，沿著道路向北穿過奧特蘭克前往{area:3197}。",
		["grind on {npc:7460} at the {area:2247}, {zone:1452}"] = "在{zone:1452}的{area:2247}擊殺{npc:7460}練等",
		["{item:12771}, a rare drop"] = "{item:12771}，稀有掉落",
		["{npc:10301}'s camp"] = "{npc:10301}的營地",
		["{npc:10301}'s supplies"] = "{npc:10301}的補給物資",
		["{npc:10431}: keep both for the Plaguelands"] = "{npc:10431}：兩個都保留給瘟疫之地",
		["{npc:10926}'s doll"] = "{npc:10926}的洋娃娃",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}：{npc:7583}和{npc:10977}稍後再找",
		["{npc:11038}: {npc:12250} is a level 54 elite"] = "{npc:11038}：{npc:12250}是54級精英",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}：上一份指南在這裡綁定爐石，所以這一步通常會立即完成",
		["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556}守衛著{npc:9298}西北方的{area:1769}入口。",
		["{npc:11629}: keep it for {area:2262}"] = "{npc:11629}：保留給{area:2262}",
		["{npc:12250} is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "{npc:12250}是精英：建議組隊。他在本區西南部的地穴{area:2261}最底層等著。",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{zone:1422}的{quest:5152}：保留此任務",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}，稍後給梅羅什",
		["{quest:8471}, a rare drop"] = "{quest:8471}，稀有掉落",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "安多哈爾",
		["Andorhal Watches"] = "安多哈爾懷錶",
		["Back north to the {area:202}: the cauldron offers its own task now. The ghouls nearby drop Somatic Intensifiers."] = "向北回到{area:202}：瘟疫之鍋現在會提供自己的任務。附近的食屍鬼會掉落細胞增強劑。",
		["Buy one {item:13320} from {npc:11056} for Felstone's cauldron, right before you go: the quickeners vanish after 30 minutes."] = "出發前才向{npc:11056}購買一個{item:13320}，用於費爾斯通的瘟疫之鍋：催化劑30分鐘後就會消失。",
		["Buy two more Arcane Quickeners for the {area:202}'s and Dalson's cauldrons, and ride straight there: they vanish after 30 minutes."] = "為{area:202}和達爾松的瘟疫之鍋再購買兩個{item:13320}，然後直接騎過去：它們30分鐘後就會消失。",
		["Climb the hill west of {area:190} to look down on the town."] = "爬上{area:190}西邊的山丘俯瞰城鎮。",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "向東渡河前往{area:2261}，也就是本區西南部的地穴。{object:177667}就在裡面：它的鑰匙在遠處東北方的{npc:12248}身上，在下一份指南完成。",
		["Cross the river west to {npc:1855}'s hut."] = "向西渡河前往{npc:1855}的小屋。",
		["Diseased Grizzlies"] = "生病的灰熊",
		["Diseased Wolves"] = "生病的狼",
		["Fly to {area:392}."] = "飛往{area:392}。",
		["For the druids of {zone:1457}: keep it"] = "給{zone:1457}的德魯伊：保留此任務",
		["For {zone:1448}: keep it"] = "給{zone:1448}：保留此任務",
		["For {zone:1451}: keep it"] = "給{zone:1451}：保留此任務",
		["For {zone:1453}: keep it"] = "給{zone:1453}：保留此任務",
		["From {area:392}, fly to {area:2255} and ride south to {area:2250}."] = "從{area:392}飛往{area:2255}，再向南騎往{area:2250}。",
		["From {area:702}, fly to {area:1116}."] = "從{area:702}飛往{area:1116}。",
		["Gaeriyan in {area:976}: keep it"] = "{area:976}的加里楊：保留此任務",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "霍古斯的顱骨在{area:2624}，馬杜克的劍在{area:2623}，各自位於鬼魂交戰之處；成年的瘟疫犬在兩地之間的平原上獵食。",
		["Listen to his story"] = "聆聽他的故事",
		["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}標記{npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}標記{npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}標記{npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}標記{npc:10905}",
		["More watches"] = "更多懷錶",
		["Radley and Durgen"] = "萊德雷與杜爾根",
		["Ride back south to the camp."] = "向南騎回營地。",
		["Ride back to {area:3197} and fly to {area:150}, take the boat to {area:442} and fly to {area:702}; the portal leads up to {zone:1457}."] = "騎回{area:3197}並飛往{area:150}，搭船前往{area:442}，再飛往{area:702}；傳送門通往上方的{zone:1457}。",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "向東騎往邊界河：{npc:1855}住在河岸的小屋裡。",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "沿著道路向北騎往北山伐木場；{npc:11610}躲在營地邊緣。",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "向西北騎往達爾松的農場。日記在穀倉裡；一具遊蕩的骷髏帶著廁所的鑰匙，{npc:10836}在廁所裡等著，身上有櫃子的鑰匙。",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "向西北騎往{area:2277}邊緣的{area:2276}。",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "向南騎往{area:201}，{npc:11078}在那裡守護著瘟疫之鍋。",
		["Ride south-west to the camp."] = "向西南騎回營地。",
		["Ride west along the road to the hot springs."] = "沿著道路向西騎往溫泉。",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "向西騎往{area:2627}。瘟疫幼犬、瘟疫蝙蝠和腐肉蟲在樹林中遊蕩；在大白蟻丘裝滿{item:15042}，並擊殺更北邊的狂怒的瘟疫犬。",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones."] = "骷髏剝皮者和被奴役的食屍鬼在營地北邊的田野中遊蕩；這裡所有的天譴軍都會掉落天譴石。",
		["Small lockboxes lie in the rubble all over Andorhal; each holds a watch."] = "安多哈爾各處的瓦礫堆中散落著小型保險箱；每個裡面都有一只懷錶。",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "搭船前往大陸，向東北騎往{area:1119}旁{npc:14637}的營地。",
		["Temple of the Moon"] = "月神殿",
		["Ten {item:11040} from the {item:11020}"] = "從{item:11020}取得十個{item:11040}",
		["The Andorhal watchtowers"] = "安多哈爾哨塔",
		["The Scarlet Crusade"] = "血色十字軍",
