t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Chromie in Andorhal: keep it"] = "安多哈爾的克羅米：保留此任務",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "掘泥摧毀者在更西邊挖掘；石鞭巨鉗蠍、石鞭掠奪者和石行蜘蛛在同一片沙地上狩獵。",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "掘泥打擊者在要塞西北方的沙丘中挖掘；石鞭蠍和掠沙蜘蛛在四周遊蕩。",
		["Dredge and scorpids"] = "掘泥蟲與蠍子",
		["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it."] = "從{area:976}飛往{area:541}。{npc:8737}的小屋在避難營西邊的{area:538}；{npc:9117}在小屋後方的山丘上。",
		["Fly to {area:271} and ride north up the road toward Alterac: Haggerdin camps at {area:1056} beside it."] = "飛往{area:271}，沿著道路向北往奧特蘭克騎：哈格丁在路旁的{area:1056}紮營。",
		["For {area:3197}: keep it"] = "交給{area:3197}：保留此任務",
		["For {npc:10778}: keep it"] = "交給{npc:10778}：保留此任務",
		["For {zone:1448}: keep it"] = "交給{zone:1448}：保留此任務",
		["From {area:392}, fly to {area:976}."] = "從{area:392}飛往{area:976}。",
		["Its jars are filled on the next Un'Goro visit"] = "它的罐子會在下次造訪安戈洛時裝滿",
		["On {npc:7583}"] = "關於{npc:7583}",
		["Ride back to {area:3425} and fly to {area:392}."] = "騎回{area:3425}，飛往{area:392}。",
		["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "向東騎往{area:2738}的{area:2742}高塔；爬上去，擊殺為了異種蠍粘液包裹的物體而出現的亞什伏擊者。",
		["Ride east to {npc:13220}."] = "向東騎往{npc:13220}。",
		["Ride north to the {area:2277}'s north-eastern edge."] = "向北騎往{area:2277}的東北邊緣。",
		["Ride on north to {area:3197} and fly to {area:2268}."] = "繼續向北騎往{area:3197}，飛往{area:2268}。",
		["Ride out of the crater's north-western pass into {zone:1451} and on to {area:3425}."] = "從環形山西北方的山口騎進{zone:1451}，繼續前往{area:3425}。",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised."] = "向西南騎往{area:2261}。土堆在裡面。{npc:11886}是精英：建議組隊。",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "向西南騎往{area:1938}的{npc:7771}營地。",
		["Scourge Champions"] = "天災勇士",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "天災勇士（59級）在{area:2268}北邊的{area:2270}遊蕩。每殺一隻就用{npc:11063}的{item:13156}掃過牠：產生共鳴的頭骨才是他要的。一次只拉一隻。",
		["Sixty {item:2592}, if you carry them"] = "六十塊{item:2592}，如果你帶著的話",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "從{area:392}搭船前往{area:35}，然後飛往{zone:1453}。",
		["Take the {area:2257} to {zone:1455}."] = "搭乘{area:2257}前往{zone:1455}。",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}."] = "焦油獸在{area:538}打滾；中央{area:537}的火元素帶著灰燼；南邊{area:540}的格里什異種蠍帶著腺體。環形山的每隻生物都可能掉落{item:11018}。",
		["The crater"] = "環形山",
		["The next guide starts here in {area:392}."] = "下一份指南從{area:392}這裡開始。",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "被折磨的德魯伊和被折磨的哨兵在{npc:13220}西南方的廢墟村莊出沒。",
		["The western dunes"] = "西部沙丘",
		["The {area:2742} tower"] = "{area:2742}高塔",
		["Umber in {zone:1450}: keep it"] = "{zone:1450}的阿姆伯爾：保留此任務",
		["grind on {npc:8532} at the {area:2258}, {zone:1423}"] = "在{zone:1423}的{area:2258}擊殺{npc:8532}練等",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}，來自天災勇士",
		["{item:14613}, from {npc:11886}"] = "{item:14613}，來自{npc:11886}",
		["{npc:14724}, by the tram"] = "{npc:14724}，在地鐵旁",
		["{npc:332}, in SI:7"] = "{npc:332}，在軍情七處",
		["{npc:3520}, who walks the canals"] = "{npc:3520}，在運河邊走動",
		["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299}在城鎮東邊的墓地等候；墓碑就在附近。",
		["{quest:3444} is in {area:392}"] = "{quest:3444}在{area:392}",
		["{quest:6184} at {area:3197}: keep it"] = "{area:3197}的{quest:6184}：保留此任務",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "安多哈爾",
		["Angerclaw bears and Felpaw wolves"] = "怒爪熊和魔爪狼",
		["Araj is elite: grouping up is advised."] = "阿拉基是精英：建議組隊。",
		["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber."] = "回到{area:1770}：{npc:9861}和{npc:9860}在最深處的洞室守護著{npc:9517}。",
		["Bronzebeard's Encampment"] = "銅鬚營地",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "爬上環形山中央的{area:537}，背包裡帶著兩塊瑟銀錠，在山頂熔岩湖旁使用{item:14644}。在山脊周圍水池中的原生軟泥怪身上裝滿{npc:9616}的純淨樣本瓶。",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "渡過{npc:1855}東邊的河進入{area:2627}。恐懼谷的靈魂在那裡的樹林中出沒。",
		["Dredge Crushers roam the dunes between {area:2743} and {area:3425}, on your way back. {npc:15181} only offers {quest:8304} from level 58."] = "回程路上，掘泥摧毀者在{area:2743}與{area:3425}之間的沙丘上遊蕩。{npc:15181}要到58級才會提供{quest:8304}。",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "飛往{zone:1447}的{area:3137}，沿著道路向西騎往剛越過{zone:1440}邊界的{area:2358}。",
		["Fly to {area:976}."] = "飛往{area:976}。",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "沿著道路向北前往{area:1767}。鐵木踐踏者身上帶著心臟；在北邊的怒爪灰熊和魔爪掠奪者身上收集完爪子。",
		["Follow the road south-west out of the pass to {area:3425}."] = "沿著道路從山口向西南前往{area:3425}。",
		["Go back down to {area:702}, take the boat to {area:442} and the boat on to {area:17203}. Bring sixty Silk, sixty Mageweave and sixty {item:14047} for {npc:14722}: buy what you lack at the Auction House."] = "下到{area:702}，搭船前往{area:442}，再轉船前往{area:17203}。為{npc:14722}準備六十份絲綢、六十份魔紋布和六十份{item:14047}：缺少的到拍賣場購買。",
		["Grind to 58"] = "練到58級",
		["Grind to 59"] = "練到59級",
		["Grind to 60"] = "練到60級",
		["Hand him the ten texts you kept"] = "把你保留的十份文本交給他",
		["Havunth's camp sits just west of {area:3425}."] = "哈弗斯的營地就在{area:3425}西邊。",
		["Hearth to {area:1519} and train your level 60 spells. This is the end of the leveling route: look at the reputation and dungeon guides next."] = "使用爐石回到{area:1519}，學習你的60級法術。升級路線到此結束：接下來請看聲望和地城指南。",
		["Hearth to {area:392} and fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "使用爐石回到{area:392}，飛往{area:976}。在這裡的拍賣場購買兩塊瑟銀錠，用於{quest:5801}。",
		["Into {zone:1451}"] = "進入{zone:1451}",
		["Irontree Stompers"] = "鐵木踐踏者",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "保留他還給你的{item:11169}、爪子和心臟",
		["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "繼續沿路向西，前往溫泉旁{npc:9298}的營地。",
		["Level 60"] = "60級",
		["Ride back north to {area:2255} and west along the road to the night elf village."] = "向北騎回{area:2255}，再沿著道路向西前往墜星村。",
		["Ride back south along the road to the Sanctuary."] = "沿著道路向南騎回聖地。",
		["Ride back south-east to the hermit."] = "向東南騎回隱士處。",
		["Ride back south-west to {area:3197}."] = "向西南騎回{area:3197}。",
		["Ride back to {area:3137} and fly to {area:2255}."] = "騎回{area:3137}，飛往{area:2255}。",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "向東騎進山丘。使用{item:11169}召喚{quest:4005}，然後擊敗他取得圖騰。",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "向東騎往{area:2738}的廢墟。{object:179565}在毀壞的建築之間，由被折磨的哨兵看守。",
		["Ride north along the west side to Mayna's small camp."] = "沿著西側向北騎往瑪恩納的小營地。",
		["Ride north out of {area:415} into {zone:1448} to the druids' camp on the road just past the border."] = "騎出{area:415}向北進入{zone:1448}，前往剛越過邊界後道路旁的德魯伊營地。",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "向北騎往{area:1769}洞口旁的死木熊怪村莊。",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "向北騎往{area:541}。在{npc:10977}旁邊使用{npc:10980}。",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "沿著道路向北騎往伐木場，把白蟻桶放在伐木場中央。",
		["Ride south to {area:2250}. Protect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "向南騎往{area:2250}。保護{npc:10300}，讓她在前往{object:177404}的路上點燃火炬。",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "向西南騎往南部山脈附近的矮人營地，詢問{npc:15171}和{npc:15170}。{npc:15190}的背包就在營地東南方的沙地上。",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "向西南騎往{area:1938}的{npc:7771}營地。",
		["Ride west along the crater's northern wall to the pass in the north-west corner that climbs into {zone:1451}."] = "沿著環形山北面山壁向西騎，前往西北角爬升進入{zone:1451}的山口。",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "組隊打{area:2057}（{zone:1422}東南部的{area:2298}）或{area:2279}代替練等能更快達到目標。若要單人練等，跳過此步驟。",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "組隊打{zone:1444}的{area:2577}代替練等能更快達到目標。若要單人練等，跳過此步驟。",
		["Shaman training"] = "薩滿訓練",
		["Take the boat from {area:442} to {area:702}."] = "從{area:442}搭船前往{area:702}。",
		["Take the flight path in {area:2361} and fly to {area:442}."] = "在{area:2361}搭乘飛行路線飛往{area:442}。",
		["Take the portal up to {zone:1457}."] = "走傳送門上到{zone:1457}。",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "沿著道路向西下到環形山中，騎往南部的異種蟲洞穴{area:540}。{npc:10041}在最深處的洞室等著。",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "從{npc:9298}西邊位於{zone:1452}的入口進入{area:1769}隧道，沿著{area:493}的岔路前往{area:2361}。{npc:11939}在湖岸邊做研究。",
		["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each want sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: 120 of each in all, from your bags or the Auction House."] = "搭乘{area:2257}前往{zone:1455}。{npc:14724}和{npc:14723}各要六十份毛料、六十份絲綢和六十份魔紋布，接著是六十份{item:14047}：每種共120份，從你的背包或拍賣場取得。",
		["Ten more for {quest:8323}"] = "再十份給{quest:8323}",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "暮光之錘的挖掘場佔據西北角：石碑碎片散落在地上，灰塵風暴和沙漠奔行者身上也帶著碎片。每個教徒都可能掉落{item:20404}：保留二十份，十份給{npc:15306}，十份稍後給{npc:15194}。",
		["The hermit hides among the rocks south-east of {area:2738}."] = "隱士躲在{area:2738}東南方的岩石間。",
		["The {area:2479}"] = "{area:2479}",
		["The {area:2739}"] = "{area:2739}",
		["The {area:3098}"] = "{area:3098}",
		["The {npc:7446} bears roam the snowy valley south of {area:2250}."] = "{npc:7446}熊在{area:2250}南邊的雪谷中遊蕩。",
		["Toward the north-west pass"] = "前往西北山口",
		["Twilight Tablet Fragments"] = "暮光石碑碎片",
		["Twilight's Hammer cultists"] = "暮光之錘教徒",
		["Use the jars on slain oozes"] = "對被殺死的軟泥怪使用瓶子",
		["Wait a moment for {npc:9116}"] = "稍等一下{npc:9116}",
		["You start in {area:392}, where the previous guide hearthed you. Fly to {area:415}."] = "你從{area:392}開始，上一份指南讓你用爐石回到這裡。飛往{area:415}。",
		["grind on {npc:11741} at the dunes east of {area:2743}, {zone:1451}"] = "在{zone:1451}{area:2743}東邊的沙丘擊殺{npc:11741}練等",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "在{zone:1423}的{area:2627}擊殺{npc:14564}練等",
		["grind on {npc:7446} at the valley south of {area:2250}, {zone:1452}"] = "在{zone:1452}{area:2250}南邊的山谷擊殺{npc:7446}練等",
		["{area:1770} braziers"] = "{area:1770}的火盆",
		["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}."] = "{area:1770}是{area:1763}後方、道路西邊的洞穴。在洞裡的四個火盆上使用{item:12906}。擊殺沿途的怒爪熊和魔爪狼以取得{item:11172}。",
		["{area:2057} (optional)"] = "{area:2057}（可選）",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057}適合58到60級；{quest:5505}在下方的{area:3197}繳交。",
		["{area:2577} (optional)"] = "{area:2577}（可選）",
		["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577}適合55到60級；下方擊殺{npc:7446}的練等路線可以讓你單人練到59級。",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667}在安多哈爾西側的旅店廢墟裡等候，安多哈爾是營地北邊的廢墟城市。{npc:1852}在城鎮中央守著他的護符匣。",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "{npc:10778}的鬼魂在{area:199}的農舍旁徘徊，位於安多哈爾西邊。田裡喋喋不休的食屍鬼身上帶著護符的另一半：把兩半合起來。",
		["{npc:10924}: ends in {zone:1452}, keep it"] = "{npc:10924}：在{zone:1452}完成，保留此任務",
		["{npc:11557}, if you have thirty {quest:6031}"] = "{npc:11557}，如果你有三十份{quest:6031}",
		["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw"] = "{npc:11558}，就在洞口內：與木喉要塞達到中立後才會提供",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "{npc:11801}的房子在{area:2361}，位於{npc:11939}東邊。",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803}佔據西南角落的教徒營地。",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}，在{object:2096}",
		["{npc:15174}, the innkeeper"] = "{npc:15174}，旅店老闆",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp."] = "{npc:17080}在西邊的蟲巢{area:2743}外紮營。在附近的紅色間歇泉撿起一塊希利塞斯，帶到他營地的聯盟萃取器。",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}，在聯盟帳篷旁",
		["{npc:1852} is a level 61 elite"] = "{npc:1852}是61級精英",
		["{npc:1855} (optional)"] = "{npc:1855}（可選）",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855}住在伐木場東北方、邊界河畔的小屋裡。如果你已完成{quest:5781}，就交給他。",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}，在{area:1658}頂端",
		["{npc:4155}, in the bank"] = "{npc:4155}，在銀行裡",
		["{npc:6791}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6791}：上一份指南用爐石把你送到這裡，所以這一步通常會立即完成",
		["{npc:7740} in {zone:1457}: keep it"] = "{zone:1457}的{npc:7740}：保留此任務",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}，在月神殿裡",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}，在避難營深處",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive."] = "{npc:9598}在{area:1767}等候。護送她走出樹林，並保護她存活。",
		["{object:176091}, if you found the Firewater flask in {zone:1452}"] = "{object:176091}，如果你在{zone:1452}找到了火酒瓶",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}：{zone:1452}的{npc:9298}，保留此任務",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}、{zone:1448}、{zone:1452}與瘟疫之地",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}沒有薩滿訓練師",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train your level 60 spells with {npc:258098}."] = "{zone:1453}沒有薩滿訓練師：從{object:28027}搭乘{area:2257}前往{zone:1455}，向{npc:258098}學習你的60級法術。",
} end)()
t.guides["forever/alliance/dwarf-gnome/01-dun-morogh"] = (function() return {
		["A few Frostmane Troll Whelps if you are short"] = "如果還不夠，再殺幾隻小霜鬃食人妖",
		["A few more troggs outside if you are short"] = "如果還不夠，到外面再殺幾隻穴居人",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "穿過隧道回到農場上方{npc:257597}的洞穴。",
		["Back to {area:77}"] = "返回{area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "回到{area:77}的{npc:257446}處。他會給你{item:6635}：沿著山谷南邊有碎石標記、向西攀升的小路走到山脊上的靈石，在旁邊喝下靈契並與{npc:5891}交談，然後把牠的{item:6656}帶回給他。",
		["Back to {npc:257597}"] = "返回{npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of {area:87}."] = "回到{npc:6122}處。在{object:2164}地下室的召喚法陣使用{item:6928}，擊敗被召喚出來的虛空行者。下一站是{area:87}西邊的{zone:1436}。",
		["Boars and bears"] = "野豬與熊",
		["Cornelius is missing in the {area:136}: find him inside, then go back to Gretchen."] = "巡山人在{area:136}失蹤了：到洞裡找到他，然後回到格雷徹處。",
		["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "峭壁野豬和小黑熊在{area:131}和補給站周圍的原野上遊蕩。",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "格瑞夫的每個任務都會給你一根{item:15908}：對他指定的野獸使用，然後把馴獸棒帶回{area:131}鐵匠舖交給他。大峭壁野豬、雪豹和冰爪熊都在{area:131}南邊和東邊的原野上遊蕩。",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "法森在{area:134}西邊俯瞰採掘場的山脊上紮營。與他交談以獲得他的遠視。",
		["Feather Charms, from the Frostmane Novices"] = "羽毛符咒，來自霜鬃食人妖新兵",
		["Firewood"] = "木柴",
		["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "沿著道路一路向東，前往{zone:1432}隧道處的{area:806}。",
		["Follow the road east past the depot to {area:138}."] = "沿著道路向東經過補給站，前往{area:138}。",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "沿著道路從{area:131}向東北前往{zone:1455}道路下方的補給站。",
		["Follow the road through the tunnel and north-east to {area:131}. Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. {npc:1252}, Eric and his campfire are outside the {area:2102}. {npc:6806}, {npc:1226} and {npc:1267} are inside. {npc:1872} works the forge."] = "沿著道路穿過隧道，向東北前往{area:131}。途中擊殺峭壁野豬：在接到{npc:1267}的任務之前，牠們就會掉落肋排，並算入該任務。{npc:1252}、埃瑞克和他的營火在{area:2102}外面。{npc:6806}、{npc:1226}和{npc:1267}在裡面。{npc:1872}在鍛爐工作。",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "沿著道路上到{zone:1455}，走{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}裡。{npc:6175}是個乞丐，在城裡四處遊蕩。他要十份{item:2589}：{zone:1426}的穴居人和食人妖會掉落，拍賣場也有賣。",
		["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "沿著道路上到{zone:1455}，向你的職業訓練師學習。{area:2257}從城市東邊的{object:171524}出發。搭乘它前往{zone:1453}。",
		["From the {quest:2997} she gives you"] = "來自她給你的{quest:2997}",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "小霜鬃食人妖遍布{npc:786}營地南邊和東邊的山坡。",
		["Gnomes, bears and leopards"] = "地精、熊與雪豹",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿過隧道進入{zone:1432}。過了隧道不遠，道路右側有一條以石頭標記的小路，向北爬上山丘通往{npc:257808}的營地。",
		["Hearth to {area:131}"] = "使用爐石前往{area:131}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "冰爪熊墜飾，來自營地上方山坡上的小霜鬃食人妖",
		["Inside {area:77}"] = "{area:77}裡面",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "從正門離開{zone:1453}，向南前往{area:87}，再沿著道路向東前往{area:62}。{npc:881}（9級）站在農舍旁。",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "從正門離開{zone:1453}。{quest:1861}瀑布在城門西南方，位於向西前往{zone:1436}的路上：在瀑布底下裝滿{item:7207}。",
		["Leopards and boars"] = "雪豹與野豬",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "烈酒村和{area:133}道路周圍的麻瘋地精身上帶著齒輪和零件。冰爪熊、老峭壁野豬和雪豹在湖周圍的山丘上遊蕩。",
		["Level 4 spells, before Gozwin's camp"] = "4級法術，在前往戈茲溫的營地之前學習",
		["Minor Ice Elementals drift around the frozen lake by the refuge. The three rifles are in the snow around it."] = "{npc:276003}在避難所旁的結冰湖泊周圍漂浮。三把步槍就在周圍的雪地上。",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "蓬毛幼狼在{area:77}南邊的雪地上遊蕩。",
		["Ride back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "騎出{zone:1455}，沿著道路向東前往{area:212}。{npc:6177}倒在湖岸邊：對他使用{item:6866}。在湖邊潛行的黑鐵間諜身上帶著文稿。",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}."] = "採掘場北邊{area:212}旁的石齶伏擊者，以及更東邊的石齶碎脊者，會掉落{quest:95214}。",
		["Rockjaw Bonesnappers prowl the quarry and {area:212}; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "石齶斷骨者在採掘場和{area:212}一帶出沒；黑鐵間諜在湖岸周圍潛行。其中一名間諜會掉落{item:274268}。",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "石齶擊顱者遍布採掘場；{area:212}旁的石齶伏擊者會掉落{item:268548}。",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "石齶穴居人和壯實的石齶怪在{area:77}南邊的谷地各處挖掘。",
		["Sit by Eric's campfire (type /sit) and wait for the buff, then {npc:1699} in the distillery teaches you cooking."] = "坐在埃瑞克的營火旁（輸入 /sit）等待增益效果，然後由釀製廠裡的{npc:1699}教你烹飪。",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "小型峭壁野豬在{npc:714}的營地周圍和山谷西側覓食。",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "雪豹和野豬在牧場與採掘場之間的雪地上遊蕩。鐵匠：銅錠可以熔煉{item:2770}取得，或向商業用品商人購買。",
		["Speak with {npc:1699}"] = "與{npc:1699}交談",
		["Spies and Bonesnappers"] = "間諜與斷骨者",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "碎石怪先知（13級）站在{npc:257808}營地南邊、{area:923}南部的穴居人之間；坑道鼠地卜師（12級）在湖北端的{area:149}工作。穴居人成群出現，有些會從遠處投擲：一次拉一隻。",
		["Subdue the voidwalker"] = "制服虛空行者",
		["The Fire Spirit Stone"] = "火焰靈石",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "熱酒只能維持五分鐘：直接向北前往{area:77}裡的{npc:836}。",
		["The boars"] = "野豬",
		["The cold"] = "寒冷",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "木柴散落在避難所旁結冰湖泊周圍的雪地上。",
		["The quarry lies south-east of the ranch."] = "採掘場位於牧場東南方。",
		["The quarry troggs"] = "採掘場的穴居人",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "地鐵抵達{object:28027}。{npc:5480}在{object:2100}訓練戰士；{npc:6089}和{npc:6090}一起站在那裡的{object:2152}旁。{npc:6090}會為了他的杯子和你打一架。",
		["The troggs"] = "穴居人",
		["The troll cave"] = "食人妖洞穴",
		["The tunnel"] = "隧道",
		["The {area:2257}"] = "{area:2257}",
		["The {object:176785} sits next to {npc:271546}, south of the {area:136}; {npc:1243} camps south-west of it, by the road to Coldridge."] = "{object:176785}在{area:136}南邊的{npc:271546}旁邊；{npc:1243}在它西南邊、通往寒脊山谷的路旁紮營。",
		["The {object:269} in the basement"] = "地下室的{object:269}",
		["The {object:270} in the distillery"] = "釀製廠裡的{object:270}",
		["Use the {item:6866} on {npc:6177}"] = "對{npc:6177}使用{item:6866}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "你從{area:77}前方開始，那是山谷北端的石廳。{npc:658}在門外等候。",
		["Young wolves"] = "幼狼",
		["{area:131} and the depot"] = "{area:131}與補給站",
		["{area:135} is the troll cave in the hills west of {area:137}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135}是{area:137}西邊山丘中的食人妖洞穴。在洞口擊殺霜鬃獵頭者，並一路走到洞穴最深處。",
		["{area:137} sits on the lake north-west of {area:135}."] = "{area:137}位於{area:135}西北方的湖邊。",
