		["{npc:1254} and {npc:1256}"] = "{npc:1254}和{npc:1256}",
		["{npc:1266} camps in {area:801}, south of Brewnall. His meats are in the locker in {npc:1271}'s cave to the north-east of his camp: grab them and leave quickly."] = "{npc:1266}在烈酒村南邊的{area:801}紮營。他的肉在營地東北方{npc:1271}洞穴裡的箱子中：拿了就快走。",
		["{npc:1269}, by the depot"] = "{npc:1269}，在補給站旁邊",
		["{npc:12738}, next to him"] = "{npc:12738}，在他旁邊",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}：限時任務，五分鐘內抵達{area:77}的{npc:836}處",
		["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373}看守著釀製廠地下室的{item:2686}酒桶。向{npc:1247}購買一杯{item:2686}，點擊受到看守的酒桶，然後透過他的任務視窗把酒交給{npc:1373}（沒有任務需要接受）；之後，無人看守的酒桶就能拿到{spell:8553}。",
		["{npc:1373}, beside the barrel"] = "{npc:1373}，在酒桶旁邊",
		["{npc:1377}, at the depot"] = "{npc:1377}，在補給站",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}：僅限鐵匠",
		["{npc:1960} waits at the {area:808}; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960}在{area:808}等候；矮人屍體在他西邊的山路上方。",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965}守衛著{area:77}東邊通往山谷外的隧道；{npc:6782}站在隧道口他的身旁。",
		["{npc:1977}, in the quarry"] = "{npc:1977}，在採掘場裡",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}，在{area:77}裡面",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}：{npc:5873}和你的{item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597}在{area:806}西北方農場上方的洞穴裡等候；上山的小路從農場後方開始。",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808}會給你{item:6636}。爬上營地上方的山峰，在靈石旁喝下靈契並擊敗{npc:5893}，然後把牠的{item:6655}放進永恆之火神殿頂端的{object:61934}。",
		["{npc:258098}, the shaman trainer, north of the {object:32372}"] = "{npc:258098}，薩滿訓練師，在{object:32372}北邊",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}：由南門旁的{npc:257597}接收",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756}和{npc:8416}一起站在{area:77}門口。戈茲溫的營地就在西北方的山丘上；{npc:269075}在營地周圍徘徊。",
		["{npc:376} is in the Cathedral of Light."] = "{npc:376}在光明大教堂裡。",
		["{npc:460}, inside {area:77}"] = "{npc:460}，在{area:77}裡面",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497}站在{object:2101}的法師塔裡；她會給你一個裝{quest:1861}瀑布水的瓶子。",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}：由{zone:1453}的{npc:6122}接收",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122}在{object:2101}的{object:2164}地下室等候。",
		["{npc:6179}: Redemption"] = "{npc:6179}：救贖",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}：給{npc:895}的符文",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}：閱讀{quest:98581}",
		["{npc:6806}, in the distillery"] = "{npc:6806}，在釀製廠裡",
		["{npc:713}, next to {npc:658}"] = "{npc:713}，在{npc:658}旁邊",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}的營地在山谷西端。{item:10438}在營地南邊的雪地上，他的箱子在食人妖洞穴旁，他的螺栓桶在洞穴東邊：經過時順手拿取。",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}和{npc:12738}在山谷西南邊緣、食人妖洞穴下方紮營。",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}在{npc:786}營地東邊的食人妖洞穴裡，不在洞穴上方的山丘上：從洞口進去，沿著隧道走到最深處。",
		["{npc:836}, inside {area:77}"] = "{npc:836}，在{area:77}裡面",
		["{npc:837}, the priest trainer"] = "{npc:837}，牧師訓練師",
		["{npc:8416}, by the door of {area:77}"] = "{npc:8416}，在{area:77}門口",
		["{npc:895}, the hunter trainer"] = "{npc:895}，獵人訓練師",
		["{npc:912}, the warrior trainer"] = "{npc:912}，戰士訓練師",
		["{npc:916}, the rogue trainer"] = "{npc:916}，盜賊訓練師",
		["{npc:926}, the paladin trainer"] = "{npc:926}，聖騎士訓練師",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}，法師訓練師，在{area:77}裡面",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}，在{object:171524}的郵箱旁",
		["{quest:313} is the wendigo cave south-west of {area:131}. Flintfire's shipments lie on the cave floor."] = "{quest:313}是{area:131}西南方的雪人洞穴。燧火的貨物就散落在洞穴地上。",
		["{zone:1455} class quests"] = "{zone:1455}職業任務",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "波尼斯·斯通菲爾德姑媽",
		["Back south to the {area:120}, by the road to {zone:1436}. {npc:963} stands outside the barracks, {npc:955} beside him."] = "向南回到{area:120}，在通往{zone:1436}的路旁。{npc:963}站在兵營外，{npc:955}在他旁邊。",
		["Back to the Cathedral of Light."] = "回到光明大教堂。",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "回到{npc:6122}那裡。在{object:2164}地下室的召喚法陣使用{item:6928}，擊敗被召喚出的虛空行者。",
		["Bait ingredients"] = "誘餌材料",
		["Billy plays in the {area:64}, east of the mine."] = "比利在礦坑東邊的{area:64}玩耍。",
		["Boar meat"] = "野豬肉",
		["Chunks of Boar Meat"] = "大塊野豬肉",
		["Crystal Kelp Fronds"] = "水晶藻葉",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "迪菲亞流浪巫師在{area:86}岸邊紮營；他們也會掉落紅色亞麻面罩。{object:56}在東北岸的魚人村裡。",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "迪菲亞暴徒在修道院東邊的空地及山谷東側紮營。",
		["Follow the hills south to the tower, on the road west."] = "沿著山丘向南走到塔，在往西的路上。",
		["Follow the hills south to the tower."] = "沿著山丘向南走到塔。",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "沿著小路向北前往礦坑。狗頭人勞工聚集在礦坑外；山谷中的每個狗頭人都可能掉落{object:83763}。",
		["Follow the road east past the {area:91} to the bridge."] = "沿著道路向東經過{area:91}走到橋邊。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:5497}站在{object:2101}的高塔裡；她會給你一個瓶子，用於{quest:1861}瀑布。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:6122}在{object:2101}的{object:2164}地下室等候。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in {object:2100} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:6171}和{npc:6173}在光明大教堂裡；{npc:6174}站在{object:2100}，向你要十塊{item:2589}（人型生物會掉落；拍賣場也有賣）。",
		["Follow the road south out of the valley to {area:87}. {npc:295} is in the Lion's Pride Inn; {npc:240} stands outside the smithy across the road, {npc:253} at the inn's front and {npc:241} by the road south of it."] = "沿著道路向南離開山谷前往{area:87}。{npc:295}在旅店裡；{npc:240}站在路對面的鐵匠鋪外，{npc:253}在旅店門前，{npc:241}在旅店南邊的路旁。",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "沿著道路向南離開{area:87}，前往{area:64}。{npc:251}在房子旁等候。",
		["Follow the road west back to {area:87}."] = "沿著道路向西回到{area:87}。",
		["Follow the road west back to {area:87}; {npc:6306} and Jason stand on the lake shore before town."] = "沿著道路向西回到{area:87}；{npc:6306}和傑生站在城鎮前的湖岸邊。",
		["Follow the road west past Westbrook into {zone:1436}, then south along it to {area:108}. Thor, the gryphon master, stands on the hill."] = "沿著道路向西經過西泉要塞進入{zone:1436}，再沿路向南前往{area:108}。獅鷲管理員索爾站在山丘上。",
		["From the {quest:2998} he gives you"] = "來自他給你的{quest:2998}",
		["Fun with Elementals: {npc:248464}"] = "快樂玩元素：{npc:248464}",
		["He stands by the river west of the farm."] = "他站在農場西邊的河邊。",
		["Head north-west across the fields to the {quest:91736}, north of the {area:120}. Hand it four Shiny Red Apples for a {item:247824}."] = "向西北穿過田野前往{area:120}北邊的{quest:91736}。交給它四個新鮮的紅蘋果，換取{item:247824}。",
		["Inside {area:34}"] = "{area:34}內部",
		["It lies by the river north-west of the logging camp."] = "它躺在伐木場西北方的河邊。",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "狗頭人苦力在礦坑隧道裡工作。{npc:248362}在右邊第二個轉角深處等著。",
		["Large Candles"] = "大蠟燭",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "從正門離開{zone:1453}。{quest:1861}瀑布在城門西南方，位於往西前往{zone:1436}的路上：在瀑布底部裝滿{item:7207}。",
		["Lost Books: Kobold Miners and Tunnelers"] = "遺失的書：狗頭人礦工和狗頭人隧道工",
		["Murloc Foragers and Lurkers line the river south of the bridge. {npc:473}, a Defias, walks the {area:62} west of it. Finish the Prowlers and Young Forest Bears on the way. {npc:248278} roams the murloc shore too: right-click the head it drops. {npc:248278} is elite: grouping up is advised."] = "魚人強盜和魚人潛伏者分布在橋南邊的河岸。迪菲亞的{npc:473}在橋西邊的{area:62}走動。沿途把覓食的灰狼和小森林熊殺完。{npc:248278}也在魚人河岸遊蕩：右鍵點擊牠掉落的頭顱。{npc:248278}是精英：建議組隊。",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp."] = "魚人和魚人士兵佔據東岸；垃圾堆在牠們的營地裡。",
		["Murlocs and the Collector"] = "魚人與收藏家",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "在伐木場東北方。迪菲亞流浪巫師在湖岸邊紮營。",
		["Painted Gnoll Armbands"] = "彩色豺狼人臂章",
		["Red Burlap Bandanas"] = "紅色粗麻面罩",
		["Red Linen Bandanas"] = "紅色亞麻面罩",
		["Ride back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "騎馬穿過{area:87}，沿著道路向東前往{area:62}。{npc:881}（等級9）站在農舍旁。",
		["Ride back out through {area:87} and east to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "騎馬穿過{area:87}，向東前往{area:86}。{npc:6172}躺在湖的南邊：對他使用{item:6866}。他周圍的迪菲亞流浪巫師身上帶著{item:6846}。",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border. {npc:100}, a level 12 gnoll, walks among them and carries the {item:1307}: right-click it."] = "矮小的河爪豺狼人和河爪豺狼人前鋒佔據要塞南邊、沿著{zone:1436}邊界的山丘。{npc:100}是一個12級的豺狼人，在牠們之中走動，身上帶著{item:1307}：右鍵點擊它。",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "河爪豺狼人在{area:86}西邊的山丘紮營；{quest:91725}就在他們的營地裡。",
		["She sits inside the farmhouse."] = "她坐在農舍裡。",
		["She stands by her cart at the vineyard east of the Abbey."] = "她站在修道院東邊葡萄園的推車旁。",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "她站在礦坑入口外。裡面的{npc:248362}是精英：建議組隊。",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "新鮮的紅蘋果，向{npc:894}取得，用於{quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "在他的營火旁坐下（/sit），直到獲得{spell:1229451}",
		["South down the road to the {area:64}."] = "沿著道路向南前往{area:64}。",
		["Speak with {npc:1430}"] = "與{npc:1430}交談",
		["Stonetusk Boars graze between the vineyards and the farm."] = "石牙野豬在葡萄園和農場之間覓食。",
		["Subdue the voidwalker"] = "制服虛空行者",
		["The Defias camp"] = "迪菲亞營地",
		["The Fishing Traps sit along the west shore of the lake."] = "捕魚陷阱沿著湖的西岸分布。",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house."] = "斯通菲爾德農場在礦坑西邊。斯通菲爾德媽媽和波尼斯·斯通菲爾德姑媽站在房子旁。",
		["The bridge"] = "橋",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "營地在橋的東北方。一捆木柴散落在營地周圍及其北邊的樹林裡。",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "裝葡萄的箱子在迪菲亞後方的葡萄園裡。{npc:103}在山谷東端的小屋旁等候。",
		["The gnoll camps"] = "豺狼人營地",
		["The kobold camp"] = "狗頭人營地",
		["The lake shore"] = "湖岸",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "礦坑在豺狼人營地西南方。{item:247816}在入口附近；狗頭人地卜師佔據隧道。",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "礦坑在葡萄園西邊。狗頭人礦工和狗頭人隧道工遍布上下兩層；有名字的狗頭人{npc:248464}拿著圖畫書，在下層隧道裡。{npc:248464}是精英：建議組隊。",
		["The murloc camp"] = "魚人營地",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "東岸的魚人會掉落海藻。剝皮者：森林灰狼在湖與{area:91}之間的樹林遊蕩；更東邊的覓食的灰狼也能剝下毛皮。",
		["The vineyards and {npc:103}"] = "葡萄園與{npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way."] = "{item:247813}、浸水的斧頭和浸水的工具箱在橋南邊的河裡。{npc:330}是一頭大野豬，和她的{npc:390}在河西邊的{area:62}拱土：先把小豬引開。沿途擊殺覓食的灰狼和小森林熊。",
		["The {quest:91736}"] = "{quest:91736}",
		["Torn Murloc Fins"] = "破損的魚人鱗片",
		["Use the {item:6866} on {npc:6172}"] = "對{npc:6172}使用{item:6866}",
		["Walk into the mine"] = "走進礦坑",
		["Walk through the mine"] = "穿過礦坑",
		["Wolves"] = "狼",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "你從修道院前開始。{npc:823}站在台階下，{npc:197}在大廳裡，{npc:951}和{npc:247229}在右側的圖書室，{npc:196}在修道院西北角外。",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "幼狼和森林狼在修道院周圍的田野遊蕩。",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "他的狗頭人追蹤器會標出通往{area:87}路上可點擊的狗頭人",
		["{area:18} and the wolves"] = "{area:18}與狼群",
		["{item:247824}, from the still"] = "{item:247824}，來自蒸餾器",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}：石牙野豬",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}：迪菲亞營地裡的{object:83763}",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：迪菲亞流浪巫師",
		["{npc:1430} cooks in the inn's kitchen."] = "{npc:1430}在旅店廚房裡做菜。",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}：用{item:15908}馴服牠",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}，法師訓練師，在修道院內",
		["{npc:247229}, in the library"] = "{npc:247229}，在圖書室",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242}和{npc:248248}站在塔底。",
		["{npc:248277} keeps watch at {area:798}, east of the murloc shore. Then head north-west back to the bridge."] = "{npc:248277}在魚人河岸東邊的{area:798}站崗。之後往西北回到橋邊。",
		["{npc:248415} stands behind the Abbey, by the stables."] = "{npc:248415}站在修道院後方的馬廄旁。",
		["{npc:248415}, by the Abbey"] = "{npc:248415}，在修道院旁",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507}和{area:87}的訓練師們站在一起。她的每個任務都會給你一根{item:15908}：對她指定的野獸使用，然後把馴獸棒帶回給她。石皮野豬和小森林熊在{area:64}南邊的山丘遊蕩，森林灰狼在{area:18}東邊的樹林裡。",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她旁邊：{spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261}守衛東邊道路上的橋；{npc:248265}就站在橋的另一頭。",
		["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:263399}在旅店東北方紮營；{npc:6306}、{npc:383}和{npc:1651}站在鎮東{area:18}的岸邊。",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{zone:1453}的{npc:279}接收此任務（02-westfall）",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}：由{zone:1453}的{npc:5497}接收",
		["{npc:375}, the priest trainer"] = "{npc:375}，牧師訓練師",
		["{npc:377}: {npc:376} in {zone:1453} takes both"] = "{npc:377}：兩個都由{zone:1453}的{npc:376}接收",
		["{npc:459}, outside the Abbey"] = "{npc:459}，在修道院外",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}：用{item:15908}馴服牠",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}：由{zone:1453}的{npc:6122}接收",
		["{npc:6171}: Redemption"] = "{npc:6171}：救贖",
		["{npc:6306}: skinners only, the pelts are skinned"] = "{npc:6306}：僅限剝皮者，毛皮需剝皮取得",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}，在修道院南邊的馬廄旁",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6}在修道院東北方的葡萄園挖掘。偶爾會掉落{quest:91741}：右鍵點擊它。",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}：用{item:15908}馴服牠",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}，回到修道院台階",
		["{npc:911}, the warrior trainer"] = "{npc:911}，戰士訓練師",
		["{npc:915}, the rogue trainer"] = "{npc:915}，盜賊訓練師",
		["{npc:925}, the paladin trainer"] = "{npc:925}，聖騎士訓練師",
		["{npc:927}: {npc:6171} in {zone:1453} takes it"] = "{npc:927}：由{zone:1453}的{npc:6171}接收",
		["{npc:952}, upstairs"] = "{npc:952}，在樓上",
		["{npc:955}: he wants your {item:247824}"] = "{npc:955}：他要你的{item:247824}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood."] = "{object:694855}生長在葡萄園和斯通菲爾德農場周圍的田野；附近的石牙野豬提供血液。",
		["{quest:76}'s entrance"] = "{quest:76}入口",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87}在{area:57}裡面，不在上方的山丘上：從入口進去，靠左走到礦坑底層的最深處；不要走樓梯上去。葡萄園周圍的迪菲亞強盜偶爾會掉落{item:1972}：右鍵點擊它。",
		["{quest:91733} and {npc:330}"] = "{quest:91733}與{npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "在{npc:265811}的營火旁/sit，直到獲得{spell:1229451}",
		["Back at {area:256}"] = "回到{area:256}",
		["Back to the moonwell."] = "回到月井。",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "回到{area:256}頂端。{object:654846}就在他旁邊。",
		["Bloodfeather harpies"] = "血羽鷹身人",
		["Boat to {zone:1453}"] = "搭船前往{zone:1453}",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "達札拉的每個任務都會給你一根{item:15908}：對他指定的野獸使用，然後把馴獸棒帶回{area:186}給他。樹林潛伏者在村莊周圍潛行，夜刃捕食者和巨翼惡梟在村莊南邊的樹林遊蕩。",
		["East to {area:260}"] = "向東前往{area:260}",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "護送{npc:275744}離開古墓；由{area:186}的{npc:2081}接收報告。",
		["Fandral in {zone:1457} takes it"] = "由{zone:1457}的范達爾接收",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}. Nightsabers and Webwood Lurkers keep roaming the road east. {object:126158} is in the house on the hill at the east end of the village."] = "魔錐果散落在{area:186}和{npc:2150}周圍的樹下。夜刃豹和樹林潛伏者仍在往東的道路上遊蕩。{object:126158}在村莊東端山丘上的房子裡。",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "再飛往{area:702}一次，搭傳送門上去找{npc:4217}，然後飛回{area:442}搭船。",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "沿著道路向西南離開{area:188}。{npc:2150}就坐在路旁，在{area:186}東邊不遠處。",
		["Follow the road west into {zone:1457}. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092} and {npc:7999} are in the Temple of the Moon at the south end. {npc:7316} is in the west of the city, on the way to the pink portal down to Rut'theran."] = "沿著道路向西進入{zone:1457}。{npc:4241}站在一進城的{area:1659}上。{npc:3516}在城市北端的{area:1658}，{quest:922}就在其南邊；{npc:4092}和{npc:7999}在城市南端的月神殿裡。{npc:7316}在城市西部，在前往通往魯瑟蘭的粉紅色傳送門的路上。",
		["From the harbour walk into {object:2100}. {npc:5480} trains warriors there; {npc:6089} and {npc:6090} stand together by the {object:2152}. {npc:6090} fights you for his mug."] = "從港口走進{object:2100}。{npc:5480}在那裡訓練戰士；{npc:6089}和{npc:6090}一起站在{object:2152}旁。{npc:6090}會為了他的杯子和你決鬥。",
		["From {area:17203}, ride through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "從{area:17203}騎馬穿過城門進入{zone:1429}，沿著道路向西前往{zone:1436}。",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "瘤背伏擊者埋伏在{area:258}西邊的道路沿線。",
		["Gnarlpine Mystics and Ferocitas camp north-east of {area:260}. Ferocitas drops the {item:8049}: open it for the jewel."] = "瘤背秘法師和噬夢者菲羅斯塔在{area:260}東北方紮營。噬夢者菲羅斯塔會掉落{item:8049}：打開它取得寶石。",
		["Gnarlpine Shamans"] = "瘤背薩滿",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "回到{area:702}，飛往{area:442}。{object:177525}在村莊東邊的山丘上：在那裡使用{item:15208}，擊敗月爪梟獸，然後與{npc:12144}交談。",
		["Hearth to {area:186}"] = "用爐石回{area:186}",
		["Learn the {area:442} flight path on the hill south of the inn, then cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path in {area:2361} and fly to {area:702} (by way of {area:442})."] = "在旅店南邊的山丘上學習{area:442}的飛行路線，然後施放{spell:18960}。{npc:11802}在{area:2361}；{quest:5929}在西北方的樹林裡。在{area:2361}學習{area:493}的飛行路線，然後飛往{area:702}（途經{area:442}）。",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "從{area:256}東南方的小路離開{area:188}：{npc:6780}站在路旁，就在小路往下通往{area:186}道路的地方。",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:8584} waits in the trees west of the cave mouth; {npc:1994} sits deep inside."] = "癩皮夜刃豹和草刺野豬在{area:256}北邊、前往洞穴的路上遊蕩。{npc:8584}在洞口西邊的樹林裡等候；{npc:1994}在洞穴深處。",
		["Nightsabers"] = "夜刃豹",
		["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east. The moonwell is at the west edge of {area:260}."] = "夜刃豹、巨翼梟和樹林潛伏者在{area:186}四周和往東的道路沿線遊蕩。月井在{area:260}的西緣。",
		["North to {area:257}"] = "向北前往{area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "從大槌烏薩爾的巢穴向東北走，回到{area:186}。",
		["Sentinel Arynia again"] = "再次找哨兵阿瑞尼亞",
		["South of Zenn. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "在賽恩南邊。{npc:2080}在岸邊照料他的樹苗；{npc:275703}和林精在他周圍遊蕩，{quest:919}就生長在牠們之間。",
		["South of the pools. The {object:6751} grows by the Hold."] = "在池塘南邊。{object:6751}生長在脊骨堡旁。",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "從多蘭納爾向東南前往{npc:2080}那裡。鞭笞者幼苗在岸邊他的周圍遊蕩。",
		["South-west of the barrow. The moonwell sits by the pools."] = "在古墓西南方。月井就在池塘旁。",
		["Speak with the {quest:5929}"] = "與{quest:5929}交談",
		["Speak with {npc:6286}, south of the inn"] = "與旅店南邊的{npc:6286}交談",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs."] = "搭傳送門下到{area:702}。{npc:10118}站在碼頭上，{npc:3838}在角鷹獸旁。",
		["Take the portal up from {area:702} to {npc:4217} in the {area:1658}."] = "從{area:702}搭傳送門上去，到{area:1658}找{npc:4217}。",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "再次沿著道路從{area:186}向西北走；她仍躺在路旁，在前往{zone:1457}的路上。",
		["Take the road north-west from {area:186} towards the {area:264}; she lies hurt beside it."] = "沿著道路從{area:186}向西北前往{area:264}；她受傷躺在路旁。",
		["The Bloodfeather harpies nest on the slopes west and north of the glade."] = "血羽鷹身人在林地西邊和北邊的山坡上築巢。",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms."] = "古墓在道路南邊。{npc:275744}被關在裡面，{npc:7317}在深處沉睡，四個聖物箱在下層的房間裡。",
		["The moonwell and {npc:8584}"] = "月井與{npc:8584}",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "月井在林地中央。{object:6752}生長在林地北端。",
		["The moonwell sits north of {area:256}; {npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "月井在{area:256}北邊；{npc:8584}在更西北一點。{quest:3522}只有五分鐘：裝滿藥瓶後直接去找他。",
		["The named harpies"] = "有名字的鷹身人",
		["The road to {zone:1457}"] = "前往{zone:1457}的道路",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406}在{area:257}深處：走中間的路，分岔處往左，一路上到高處的岩架。紫藍色蘑菇由小劣魔掉落，月牙百合花生長在{area:256}北邊的池塘旁。",
		["Use the {item:5185} at the moonwell"] = "在月井使用{item:5185}",
		["Use the {item:5619} at the moonwell"] = "在月井使用{item:5619}",
		["Use the {item:5621} at the moonwell"] = "在月井使用{item:5621}",
		["Use the {item:5623} at the moonwell"] = "在月井使用{item:5623}",
		["Walk Lynessa out and keep her alive"] = "護送哨兵離開，並保住她的性命",
		["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}."] = "沿著島的西側向南走。大槌烏薩爾在最南邊、{area:478}下方徘徊。",
		["Webwood Lurkers"] = "樹林潛伏者",
		["Webwood Spiders"] = "樹林蜘蛛",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "你從{area:188}的巨樹{area:256}底下開始。",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "小夜刃豹和小草刺野豬在{area:256}周圍遊蕩。小劣魔帶著{item:3297}，在樹西邊瘤背圖騰矗立的樹林裡。",
		["{area:186} again"] = "再次回到{area:186}",
		["{area:186} quests"] = "{area:186}任務",
		["{area:258}'s mouth"] = "{area:258}入口",
		["{area:736}, outside the barrow"] = "{area:736}，在古墓外",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "向{npc:6736}購買{item:159}，給{npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "向{npc:6094}旁邊的{npc:3614}購買{item:3371}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}，在月神殿裡：星辰碎片",
		["{npc:1992}, south of the tree"] = "{npc:1992}，在樹的南邊",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}：用{item:15908}馴服牠",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}：用{item:15908}馴服牠",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038}在洞穴裡等候，在底部或上方的岩架上；靠右走。",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}：用{item:15908}馴服牠",
		["{npc:2077}, by the path"] = "{npc:2077}，在小路旁",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}：給{npc:3596}的印記",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}：由{zone:1457}的{quest:922}接收",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}，在樹的坡道上",
		["{npc:2150}, on the way back"] = "{npc:2150}，在回程路上",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151}在村莊西邊的道路上巡邏：如果她不在箭頭處，沿著道路走直到遇見她。",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}，在村莊西邊的路上",
		["{npc:265811}, by the campfire"] = "{npc:265811}，在營火旁",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034}和{npc:272044}在月井西邊飛行，{npc:272046}在更北邊。",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}，在樹頂",
		["{npc:3515}, south of the inn"] = "{npc:3515}，在旅店南邊",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}，在{area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519}，在月井旁",
		["{npc:3567}, back in {area:186}"] = "{npc:3567}，回到{area:186}",
		["{npc:3593}, the warrior trainer"] = "{npc:3593}，戰士訓練師",
		["{npc:3594}, the rogue trainer"] = "{npc:3594}，盜賊訓練師",
		["{npc:3595}, inside the tree"] = "{npc:3595}，在樹裡",
		["{npc:3595}, the priest trainer, inside the tree"] = "{npc:3595}，牧師訓練師，在樹裡",
		["{npc:3596}, the hunter trainer"] = "{npc:3596}，獵人訓練師",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}，{area:256}的德魯伊訓練師",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}：由{zone:1457}的{npc:11401}接收",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}：由{zone:1457}的{npc:4217}接收",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}，在月神殿裡",
		["{npc:4146} in {zone:1457} takes it"] = "由{zone:1457}的{npc:4146}接收",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}，在{area:1658}：{spell:5149}",
		["{npc:4200}'s fish stall is by the docks. Then take the boat to {zone:1453}."] = "{npc:4200}的魚攤在碼頭旁。然後搭船前往{zone:1453}。",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217}，在{area:1658}",
		["{npc:7318}, in the den"] = "{npc:7318}，在巢穴裡",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999}，在{npc:4092}上方",
		["{npc:8583}, east of the tree"] = "{npc:8583}，在樹的東邊",
		["{object:673378}, just west of the moonwell"] = "{object:673378}，就在月井西邊",
		["{object:7510}, beside him"] = "{object:7510}，在他旁邊",
		["{quest:488} and the Starbreeze moonwell"] = "{quest:488}與星風村月井",
		["{quest:917} and the antidote"] = "{quest:917}與解毒劑",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}：施放{spell:1259799}和影遁，然後交回給{npc:3595}",
