		["Use the {item:15826} on Sickly Gazelles: they graze north of the road that runs east and west through the {area:380}."] = "對生病的瞪羚使用{item:15826}：牠們在穿過{area:380}的東西向道路北邊覓食。",
		["Use the {item:15826} on {npc:12298}. They roam {zone:1439} from the {area:456} in the north to the {zone:1440} border in the south."] = "對{npc:12298}使用{item:15826}。牠們在{zone:1439}從北邊的{area:456}到南邊的{zone:1440}邊界一帶遊蕩。",
		["{item:15851} and {item:2449}"] = "{item:15851}與{item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449}與科多獸角",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}；草藥師可以在平原上採集",
		["{npc:12296}: use the salve on them"] = "{npc:12296}：對牠們使用藥膏",
		["{npc:12298}: use the salve on them"] = "{npc:12298}：對牠們使用藥膏",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033}站在{area:1639}。",
		["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away, sells {item:2449}, three at a time until he restocks."] = "{npc:3448}站在{area:380}。沒有{skill:182}？幾步外的{npc:3490}販售{item:2449}，每次補貨前只有三個。",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217}站在{area:1658}。",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "Forever 不再由訓練師教授{spell:8946}：這個任務鏈會教你，途中還有一個藥袋。",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "返回古樹",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "古樹哈斯塔特的箭袋需要{item:18704}。{npc:6109}是需要團隊的世界首領，在{zone:1447}南部遊蕩，大多會掉落；{zone:1452}的深藍龍族極少掉落。如果你不想要箭袋，跳過本指南其餘部分。",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "Forever中尚未確認。在經典版中，背包裡有{item:18724}時使用{item:18707}即可製成洛克德拉爾，然後古樹瓦特魯斯會給你{item:18715}（{spell:425121}）。",
		["Onyxia"] = "奧妮克希亞",
		["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "奧妮克希亞會掉落{item:18705}；她是{area:2159}的40人團隊首領，巢穴位於{zone:1445}南部{area:511}的洞穴中。",
		["Rhok'delar and Lok'delar"] = "洛克德拉爾與羅可德拉爾",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "獵人的史詩弓任務鏈：在經典版中，法杖和弓弦會變成洛克德拉爾和羅可德拉爾（Forever中尚未確認）。",
		["The {item:18703}"] = "{item:18703}",
		["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "{npc:12018}投降時，{object:179703}會出現在{area:2717}；約有一半機率內含{item:18703}。{area:2717}是{area:254}內的40人團隊副本。右鍵點擊葉子開始任務。",
		["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "古樹瓦特魯斯、古樹斯托瑪和{npc:14526}一起站在{zone:1448}北部。聯盟：最近的飛行點是{area:1998}；部落：{area:1997}。",
		["from the {item:18703}"] = "從{item:18703}取得",
		["{item:18704}, from {npc:6109}"] = "{item:18704}，來自{npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}，來自奧妮克希亞",
		["{item:18707}, by Vartrus"] = "{item:18707}，由古樹瓦特魯斯給予",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}：經典版中的羅可德拉爾",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}：箭袋，本指南最後一步",
		["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "食人妖{npc:14527}站在{zone:1449}西部。和她交談，她會變成{npc:14533}，還帶著自己的寵物。單獨對付，不帶寵物。",
		["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "人類{npc:14529}站在{zone:1428}西部。和他交談，他會變成{npc:14534}。單獨對付，不帶寵物。",
		["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "牛頭人{npc:14531}在{zone:1452}東北部等著。和他交談，他會變成{npc:14535}。每個惡魔都要單獨且不帶寵物對付：任何形式的幫助都會讓它消失。拾取頭顱。",
		["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "地精{npc:14536}站在{zone:1451}西南部。和他交談，他會變成{npc:14530}。單獨對付，不帶寵物；遠離他召喚的甲蟲。",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "50級時任何聯盟獵人訓練師都提供此任務：{zone:1453}{object:28027}的{npc:5516}、{zone:1455}{object:32390}的{npc:5116}，或{zone:1457}塞納里奧區的多利安。",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "50級時任何部落獵人訓練師都提供此任務：{zone:1454}{object:172958}的{npc:3352}，或{zone:1456}{area:1641}的{npc:3039}。",
		["Experience"] = "經驗值",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "50級時透過{zone:1447}和{area:1417}取得經驗值；Forever移除了經典版的物品選擇。",
		["Morphaz in the {area:1417}"] = "{area:1417}的摩弗拉斯",
		["Morphaz is an elite dragon boss inside the {area:1417}, a five-player dungeon: bring a group. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "摩弗拉斯是{area:1417}（五人地城）內的精英龍類首領：找小隊一起去。神廟位於{area:74}中央；游下去即可到達入口。部落：飛往{area:75}；聯盟：飛往{area:42}或{area:1438}再騎過去。",
		["Mosshoof Coursers graze all over {zone:1447}; one in a dozen or so drops a pair of Perfect Courser Antlers."] = "苔蹄快步者遍布{zone:1447}吃草；大約每十幾隻會掉落一對完美的鹿角。",
		["Wavethrashers crawl along {zone:1447}'s coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore."] = "碎浪多頭怪沿著{zone:1447}的海岸爬行：東北岸的幼年碎浪多頭怪和東岸的碎浪多頭怪掉落鱗片的機率，約為南岸大型碎浪多頭怪的兩倍。",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}，在{area:1417}內",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405}住在{area:1221}東北方的懸崖頂上。聯盟：飛往{area:3137}；部落：飛往{area:1237}。",
		["{quest:8151} (Alliance)"] = "{quest:8151}（聯盟）",
		["{quest:8151} (Horde)"] = "{quest:8151}（部落）",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "返回博學者萊德羅斯",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing (or the North wing with a {item:18249})."] = "飛往羽月要塞（聯盟）或{area:1099}（部落），然後騎往{zone:1444}中部的{area:2577}。{npc:14368}在圖書館等著，經由西區抵達（持有{item:18249}也可走北區）。",
		["Hydrospawn"] = "海多斯博恩",
		["Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool."] = "水元素海多斯博恩住在Warpwood Quarter（厄運之槌東區）：追趕小鬼普希林直到他轉身應戰，清掉薩特房間，然後沿螺旋坡道下到水池。",
		["Shen'dralar reputation"] = "辛德拉聲望",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "60級的{spell:10140}，來自{area:2577}的圖書館：為你和小隊提供飲料。",
		["{item:18299}: Hydrospawn"] = "{item:18299}：海多斯博恩",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
