} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "返回要塞",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "回到{area:16602}。{npc:246378}會給你{item:6866}；{npc:257655}在要塞樓下等候。",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "回到{area:16602}：比爾穆收下計畫，{npc:246378}教你{spell:7328}。",
		["Tarnished Drudges"] = "晦暗苦工",
		["Tarnished Zealots"] = "晦暗狂熱者",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "在{area:812}周圍紮營的{npc:239036}身上帶著攻擊計畫。",
		["The Scarlet attack plans"] = "血色十字軍的攻擊計畫",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "邪鰭魚人潛伏在要塞東邊道路沿線的崖頂上，以及西邊湖泊周圍的營地中。",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328}"] = "Tyr's Watch與{spell:7328}",
		["Vile Fin Attackers"] = "邪鰭攻擊者",
		["Vile Fin Seers"] = "邪鰭先知",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "從{area:159}向南走到{area:153}，再往下進入{zone:1458}。{npc:10181}在{object:36126}接見；{npc:257648}在{object:36078}乞討。",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602}位於{area:156}西北方的崖頂上。{npc:246349}在大門等候。",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "{area:812}位於林地的最東端。對{npc:257663}使用{item:6866}，然後與他交談。如果你弄丟了符記，{npc:246378}會再給你一個。",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "在{area:159}訓練聖騎士的{npc:246152}會派你前往西海岸的騎士團要塞。",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378}在要塞內領導騎士團；{npc:246393}站在要塞旁。",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378}在12級時提供第一個神性的教誨。",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648}需要10份{item:2589}。血色狂熱者和血色苦行修士大約每十次掉落三次；如果你身上已有，就一起帶來。",
		["{object:554626}, in the root cellar"] = "{object:554626}，在地窖裡",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317}佔據要塞西南方{area:16616}中的廢棄村莊{area:16881}。{item:246213}堆放在其中一間房子的地窖裡；{npc:259431}在他的晦暗者之間走動。",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "用{spell:7328}復活倒下的盟友，另外還有給新的被遺忘者聖騎士的一把武器和一面盾牌。",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "20 級時，{object:32362}的{npc:6179}會給你{item:6776}；它會引導你去找{zone:1453}光明大教堂的{npc:6171}。從{zone:1455}搭地鐵前往{zone:1453}。",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "回到{area:442}找{npc:3649}：他會淨化寶石。",
		["Back to {npc:6241}"] = "回到{npc:6241}那裡",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "把四個部件交給{zone:1455}外的{npc:6181}。",
		["Goblin Woodcarvers, inside"] = "哥布林木匠，副本內",
		["Protect {npc:6182}"] = "保護{npc:6182}",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "聯盟聖騎士 20 多級的稀有雙手錘，途中還能拿到一面盾牌。",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "{zone:1440}西北海岸{area:2797}入口附近的黑暗深淵納迦會掉落{item:6995}。牠們是精英：建議組隊。",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "礦石箱在{zone:1432}東北部莫格羅什巨魔營地中央的樹旁。莫格羅什巨魔是精英：建議組隊。",
		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["from the {item:6776}"] = "來自{item:6776}",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581}是位於{area:20}地底的五人副本；副本傳送門在{area:20}礦坑內。桅杆室裡與斯尼德在一起的哥布林木匠會掉落木材。",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}礦坑內",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236}是位於{zone:1421}南部的 20-30 級地城。錘子放在馬廄內的箱子上，就在庭院盡頭、上坡道之前。",
		["{npc:3649} is in {area:442}."] = "{npc:3649}在{area:442}。",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171}在光明大教堂裡。右鍵點擊{item:6776}開始任務。",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181}站在{zone:1455}大門外。他會給你{item:6996}，上面列出四個部件。",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "{npc:6182}的農舍位於{zone:1436}西南海岸。她的任務期間，迪菲亞會一波波來襲：保住她的性命，必要時治療她。",
		["{npc:6241} is in {area:144}."] = "{npc:6241}在{area:144}。",
		["{npc:6241} turns the ore into {item:6993}."] = "{npc:6241}會把礦石做成{item:6993}。",
		["{object:91138}, inside"] = "{object:91138}，副本內",
		["{object:92420} crate"] = "{object:92420}箱子",
} end)()
t.guides["forever/class/priest/benediction"] = (function() return {
		["Equip {item:18646} to see {npc:14494}, a ghost on the mountainside in the north-west of the {zone:1423}. Come with full mana, Major Mana Potions and {item:8956}: if you fail, the event takes about two hours to return."] = "裝備{item:18646}才能看見{npc:14494}，她是{zone:1423}西北部山坡上的一個鬼魂。帶著滿法力、極效法力藥水和{item:8956}前往：如果失敗，事件大約要兩小時才會重新出現。",
		["Save 50 peasants before 15 die. Kill the skeletons that attack them, cure their diseases (the purple ones first) and heal the wounded with {spell:139}. Friends may buff you beforehand but must stay out of the fight, or a demon appears and kills everyone."] = "在15個農民死亡之前救出50個。擊殺攻擊他們的骷髏，治癒他們的疾病（先治紫色的），並用{spell:139}治療傷者。朋友可以事先為你施加增益，但必須遠離戰鬥，否則會出現一個惡魔殺死所有人。",
		["With both Eyes in your bags: {item:18608}"] = "兩顆眼睛都在背包裡時：{item:18608}",
		["You need {item:18646} first: it comes from the {object:179703} after {npc:12018} in {area:2717}. {item:18665} drops from elite demons ({npc:12397}, a world boss, always; Doomguard Commanders and Manahounds rarely); it binds when equipped, so buying one works too."] = "你需要先取得{item:18646}：它來自{area:2717}擊敗{npc:12018}後的{object:179703}。{item:18665}由精英惡魔掉落（世界首領{npc:12397}必定掉落；{npc:12396}和法力犬極少掉落）；它是裝備後綁定，所以也可以用買的。",
		["{item:18608} and Anathema"] = "{item:18608}與咒逐",
		["{npc:14494}'s splinter and the two Eyes make {item:18608}, the epic priest staff that turns into Anathema."] = "{npc:14494}的碎片和兩顆眼睛可以製成{item:18608}，這把史詩牧師法杖可以轉變成咒逐。",
} end)()
t.guides["forever/class/priest/blood-of-morphaz"] = (function() return {
		["Any undead can drop it. The {npc:7864} in the {area:1221}, below {npc:8405}'s cliffs, are the nearest; Highborne Apparitions and Lichlings haunt the ruins near {area:3137}."] = "任何不死生物都可能掉落。{npc:8405}所在懸崖下方{area:1221}的{npc:7864}是最近的；高等精靈的幻影和高等精靈鬼巫在{area:3137}附近的廢墟出沒。",
		["At 50 {npc:5489} in {zone:1453}'s Cathedral of Light or {npc:11406} in {zone:1455}'s {object:32386} offers it."] = "50級時，{zone:1453}光明大教堂的{npc:5489}或{zone:1455}{object:32386}的{npc:11406}會提供此任務。",
		["At 50 {npc:6018} in {zone:1454}'s {object:172961} offers it."] = "50級時，{zone:1454}{object:172961}的{npc:6018}會提供此任務。",
		["Experience and gold"] = "經驗值和金幣",
		["Experience and gold at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "50級時經由{zone:1447}和{area:1417}獲得經驗值和金幣；Forever移除了經典版的物品選擇。",
		["Morphaz in the {area:1417}"] = "{area:1417}的摩弗拉斯",
		["Morphaz is an elite dragon boss inside the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "摩弗拉斯是{area:1417}裡的精英龍類首領，這是50級地城：請帶五人小隊。神廟位於{area:74}中央；潛入水中往下游就能到入口。部落：飛往{area:75}；聯盟：飛往{area:42}或{area:1438}，再騎過去。",
		["Mosshoof Coursers graze all over {zone:1447}; about one in three drops a {item:20027}."] = "苔蹄快步者在{zone:1447}各處吃草；大約三隻中有一隻會掉落{item:20027}。",
		["{npc:10922} is at the {area:2479} in southern {zone:1448}."] = "{npc:10922}在{zone:1448}南部的{area:2479}。",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405}住在{area:1221}東北方的懸崖頂上。聯盟：飛往{area:3137}；部落：飛往{area:1237}。",
		["{quest:8254} (Alliance)"] = "{quest:8254}（聯盟）",
		["{quest:8254} (Horde)"] = "{quest:8254}（部落）",
		["{quest:8257}: the {area:1417} entrance"] = "{quest:8257}：{area:1417}入口",
} end)()
t.guides["forever/class/priest/confounding-flash-and-contingency-plan"] = (function() return {
		["At 10, go to {npc:258785} in the {object:32386}, in {zone:1455}'s {object:32362}. {npc:1226} in {area:131}, {npc:377} in {area:87} and {npc:376} in {zone:1453} send you to her with a quest of the same name (its text may say {zone:1453}: Mims is in {zone:1455})."] = "10級時，到{zone:1455}{object:32362}的{object:32386}找{npc:258785}。{area:131}的{npc:1226}、{area:87}的{npc:377}和{zone:1453}的{npc:376}會用同名任務派你去找她（任務文字可能寫{zone:1453}：敏絲在{zone:1455}）。",
		["At 20, {npc:258785} teaches {quest:94818}. {npc:376} in {zone:1453} sends you to her with a quest of the same name."] = "20級時，{npc:258785}會教你{quest:94818}。{zone:1453}的{npc:376}會用同名任務派你去找她。",
		["The Gnome priest spells, new in Forever: one at 10, one at 20."] = "地精的牧師法術，Forever 新增：10級一個，20級一個。",
		["{quest:94817} and {quest:94818}"] = "{quest:94817}與{quest:94818}",
} end)()
t.guides["forever/class/priest/desperate-prayer-and-chastise"] = (function() return {
		["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362}. Forever's quest text names Rohan, but the quest data has {npc:376} in {zone:1453}'s Cathedral of Light take it: try Rohan first, then Laurena (the {area:2257} links the cities)."] = "10級時，到{zone:1455}{object:32362}的{object:32386}找{npc:11406}。Forever 的任務文字寫的是洛漢，但任務資料顯示由{zone:1453}光明大教堂的{npc:376}接收：先試洛漢，再試勞瑞娜（{area:2257}連接兩座城市）。",
		["At 20, {npc:11406} teaches {quest:5641}. {npc:376} in {zone:1453} and {npc:11401} in {zone:1457} send you to him with a quest of the same name."] = "20級時，{npc:11406}會教你{quest:5641}。{zone:1453}的{npc:376}和{zone:1457}的{npc:11401}會用同名任務派你去找他。",
		["If Rohan did not take it: {npc:376} is in the Cathedral of Light. Take the {area:2257} from {object:171524}."] = "如果洛漢沒有接收：{npc:376}在光明大教堂。從{object:171524}搭乘{area:2257}。",
		["The Human and Dwarf priest spells: {quest:5634} at 10, {quest:5641} for Dwarves at 20."] = "人類和矮人的牧師法術：10級的{quest:5634}，以及矮人20級的{quest:5641}。",
		["{quest:5634} and {quest:5641}"] = "{quest:5634}與{quest:5641}",
