		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}."] = "30級時，{zone:1455}的薩滿訓練師{npc:258098}會派你去找{zone:1417}的{npc:259023}。",
