		["200 Horde reputation"] = "200點部落聲望",
		["A {area:2057} fight at 60 for Horde reputation; Forever removed the {item:20134}."] = "60級時在{area:2057}的一場戰鬥，換取部落聲望；Forever移除了{item:20134}。",
		["An {item:12800} comes from Thorium veins, a {item:18335} from the elites of the {zone:1422}, both rarely: buy them at the auction house if you can."] = "{item:12800}來自瑟銀礦脈，{item:18335}來自{zone:1422}的精英怪，兩者都很稀有：能的話就在拍賣場購買。",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds."] = "58級時，{object:172957}的薩滿訓練師{npc:13417}會要你帶兩顆稀有鑽石。",
		["Two diamonds"] = "兩顆鑽石",
		["he hands you the {item:18746}"] = "他會交給你{item:18746}",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. Use the {item:18746} in the heart of the {object:179746}'s basement, beat the spirits it calls, then {npc:14516}. All are elite: bring a group."] = "{area:2057}位於{zone:1422}東南方的島嶼城鎮{area:2298}之下。在大藏骨堂地下室的中心使用{item:18746}，擊敗它召喚出的靈魂，然後擊敗{npc:14516}。全都是精英：找小隊一起去。",
		["{quest:7668} needs level 60."] = "{quest:7668}需要60級。",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, sends you to {npc:6176}."] = "50級時，{object:172957}的薩滿訓練師{npc:13417}會派你去找{npc:6176}。",
		["At 50 {npc:3032}, a shaman trainer in {zone:1456}, sends you to {npc:6176}."] = "50級時，{zone:1456}的薩滿訓練師{npc:3032}會派你去找{npc:6176}。",
		["Experience and gold"] = "經驗值和金幣",
		["Experience and gold at 50, ending in the {area:1417}; Forever removed the Classic item choice."] = "50級時取得經驗值和金幣，最後在{area:1417}結束；Forever移除了經典版的物品選擇。",
		["In the {zone:1422}, the Venom Mist Lurkers drop the {item:20610} and the Diseased Black Bears the {item:20611} (about one kill in five each)."] = "在{zone:1422}，毒霧潛伏者會掉落{item:20610}，生病的黑熊會掉落{item:20611}（各約五次擊殺一次）。",
		["One each of {item:7069}, Fire, Earth and Water. The Exiles of Arathi Highlands drop them, one element each, about one kill in ten: Thundering (air), Burning (fire), Rumbling (earth) and Cresting (water). Or buy them at the auction house."] = "{item:7069}、元素火焰、元素大地和元素之水各一個。阿拉希高地的流亡者會掉落，每種流亡者掉落一種元素，大約每十次擊殺掉一個：雷霆流亡者（空氣）、燃燒流亡者（火焰）、隆隆流亡者（大地）和浪潮流亡者（水）。或者在拍賣場購買。",
		["Spider eye and bear claw"] = "蜘蛛眼和熊爪",
		["The four elements"] = "四種元素",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}) lies under the {area:74}; the arrow points at its entrance. Gasher or {npc:5716} drop the {item:20606}, Hukku or Mijan the Blue, Zolo or Loro the Green: all six are elite trolls inside. Bring a group."] = "{area:1417}（{area:1477}）位於{area:74}之下；箭頭指向其入口。加什爾或{npc:5716}會掉落{item:20606}，胡庫或米杉，祖羅或洛若爾也是：六個都是裡面的精英食人妖。找小隊一起去。",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}：頑石流放者",
		["{item:7068}: Burning Exiles"] = "{item:7068}：烈焰流放者",
		["{item:7069}: Thundering Exiles"] = "{item:7069}：雷霆流放者",
		["{item:7070}: Cresting Exiles"] = "{item:7070}：水浪流放者",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176}在{zone:1416}東部、{area:272}東北方紮營。",
		["{quest:8412} and {quest:8413}"] = "{quest:8412}與{quest:8413}",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "30多級用的稀有布甲長袍，由{npc:6266}用你帶來的材料製作。",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "31級時，{object:172960}的{npc:3326}會派你去找{area:392}的{npc:6266}。",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "31級時，{object:36082}的{npc:4563}會派你去找{area:392}的{npc:6266}。從{zone:1420}出發的飛艇飛往{zone:1411}。",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "31級時，{object:2101}{object:2164}的{npc:461}會派你去找{area:392}的{npc:6266}。",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "31級時，{zone:1455}的{npc:5172}會派你去找{area:392}的{npc:6266}。",
		["Back to {npc:6266}"] = "返回{npc:6266}",
		["Back to {npc:6266} with the thread, the coal and a {item:6265}. Wait while she completes the robe, then speak to her again."] = "帶著線、煤和一個{item:6265}返回{npc:6266}。等她完成長袍，然後再和她交談。",
		["Bring {npc:6266} a {item:5770}: tailors sew it from a pattern that drops; otherwise buy one at the Auction House. Her next errand needs a {item:3577}: smelted from {item:2776}, or from the Auction House."] = "帶一件{item:5770}給{npc:6266}：裁縫可用掉落的圖樣縫製；否則在拍賣場購買。她的下一個差事需要一個{item:3577}：由{item:2776}熔煉，或在拍賣場購買。",
		["The Burning Exiles, fire elementals in western {zone:1417}, drop the coal."] = "{zone:1417}西部的火元素烈焰流放者會掉落悶燒煤。",
		["The Hatefury satyrs of {area:603}, in north-eastern {zone:1443}, carry the blood; the Lesser Infernals of Mannoroc Coven, in the south, the stone."] = "{zone:1443}東北部{area:603}的怨怒薩特身上帶著血；南部瑪諾洛克集會所的次級地獄火身上帶著石頭。",
		["Vials of Hatefury Blood"] = "怨怒薩特之血",
		["Wait for the robe"] = "等待長袍完成",
		["{npc:2670} in {area:35} has the thread for you."] = "{area:35}的{npc:2670}有你要的線。",
		["{npc:2670} sells tailoring supplies in {area:35}. Bring him the {item:3577}."] = "{npc:2670}在{area:35}出售裁縫用品。把{item:3577}交給他。",
		["{npc:6266} again"] = "再次找{npc:6266}",
		["{npc:6266} stands in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266}站在{area:392}上方山丘的塔裡，{npc:6251}旁邊。",
		["{zone:1443} demons"] = "{zone:1443}的惡魔",
} end)()
