t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "50多級用的法杖、副手或長袍；{npc:14470}自己的差事，不屬於恐懼戰馬任務鏈。",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448}."] = "50級時，{object:172960}的{npc:3326}會派你去找{zone:1448}的{npc:14470}。",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448}."] = "50級時，{object:36082}的{npc:4563}會派你去找{zone:1448}的{npc:14470}。",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448}."] = "50級時，{object:2101}{object:2164}的{npc:461}會派你去找{zone:1448}的{npc:14470}。",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448}."] = "50級時，{zone:1455}的{npc:5172}會派你去找{zone:1448}的{npc:14470}。",
		["The Irontree treants in northern {zone:1448} drop the {item:20613}; the Tainted Oozes around {area:1763} the {item:20614}."] = "{zone:1448}北部的鐵木樹人會掉落{item:20613}；{area:1763}周圍的被污染的軟泥怪會掉落{item:20614}。",
		["The six troll guardians of the {area:1417}, a level 50 dungeon, each drop a Voodoo Feather: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance."] = "{area:1417}（50級地城）的六名食人妖守護者各掉落一根巫毒羽毛：找五人小隊一起去。神廟位於{area:74}中央；游下去即可到達入口。",
		["The {area:1417}"] = "{area:1417}",
		["{item:20613} and Bloodvenom"] = "{item:20613}與血毒",
		["{npc:14470} again"] = "再次找{npc:14470}",
		["{npc:14470} waits beside {npc:14469} in central {zone:1448}, just east of {area:1763}. This chain is {npc:14470}'s own and is not part of the Dreadsteed chain; Niby and {npc:14470} also give the {item:18762} chain here."] = "{npc:14470}在{zone:1448}中部、{area:1763}東邊不遠處，待在{npc:14469}旁邊。此任務鏈是{npc:14470}自己的，不屬於恐懼戰馬任務鏈；尼比和{npc:14470}也在這裡提供{item:18762}任務鏈。",
		["{npc:14470} wants one {item:14256}: the Jadefire satyrs and the demons of {area:1763} drop it."] = "{npc:14470}要一塊{item:14256}：碧火薩特和{area:1763}的惡魔會掉落。",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "第二種誘惑型惡魔，也就是男性的魅魔，還有一個用來裝靈魂碎片的靈魂碎片包。",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}."] = "20級時，{object:2101}{object:2164}地下室的{npc:6122}會派你去{zone:1413}找{npc:6244}。",
		["Back to {npc:6122} in the {object:2164}. Place the figurine at the summoning circle in the crypt below him and defeat the incubus it calls."] = "回到{object:2164}的{npc:6122}處。把小雕像放在他下方地穴的召喚法陣上，擊敗它召喚出的夢魔。",
		["From {area:415} take the road west to {area:413}: the figurine lies in a house among the trees north of the post."] = "從{area:415}沿著道路向西前往{area:413}：小雕像在前哨站北邊樹林中的一間房子裡。",
		["Incubus (Alliance)"] = "夢魔（聯盟）",
		["{npc:6122}: he binds the incubus to you"] = "{npc:6122}：他會把夢魔束縛給你",
		["{npc:6244} camps in the southern {zone:1413}, east of the road north-east of {area:378}: come in from the east and keep clear of the Horde guards."] = "{npc:6244}在{zone:1413}南部、{area:378}東北方道路的東邊紮營：從東邊過去，避開部落守衛。",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "第二種誘惑型惡魔，也就是男性的魅魔，還有一個用來裝靈魂碎片的靈魂碎片包。",
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers offer the incubus, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one: this guide follows whichever {quest:1472} you took."] = "20級時，{object:172982}下方{object:172960}的{npc:5875}會派你去找幾步之遙的{npc:5909}。有兩位訓練師提供夢魔任務，這裡的{npc:5875}和{zone:1458}的{npc:5675}，你只能接其中一個：本指南依照你接的{quest:1472}。",
		["Back to {npc:5675} in the {object:36082}. Place the hearts at the summoning circle below him and defeat the incubus they call."] = "回到{object:36082}找{npc:5675}。把心臟放在他下方的召喚法陣，擊敗它們召喚出的夢魔。",
		["Back to {npc:5875} in the {object:172960}. Take the scarf to the summoning circle in {npc:3216}'s tent nearby and defeat the incubus it calls."] = "回到{object:172960}找{npc:5875}。把圍巾帶到附近{npc:3216}帳篷裡的召喚法陣，擊敗它召喚出的夢魔。",
		["Incubus (Horde)"] = "夢魔（部落）",
		["{area:422} lies in southern {zone:1440}, south of {area:431}. The Shadethicket bog beasts around the lake drop the {item:190232}, about one in twenty."] = "{area:422}位於{zone:1440}南部、{area:431}南邊。湖周圍的沼澤獸會掉落{item:190232}，大約二十隻一次。",
		["{npc:185333} works as a tailor for the {area:279} wizards at {area:233}, in eastern {zone:1421}. Take her heart."] = "{npc:185333}在{zone:1421}東部的{area:233}為{area:279}的巫師們當裁縫。取走她的心臟。",
		["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and ride or fly on to {area:392}."] = "{npc:185334}在{zone:1413}海岸的{area:392}工作。搭飛艇前往{zone:1411}，再騎或飛往{area:392}。",
		["{npc:3363} keeps {object:173018}, east of the {object:172960} along the main street. He asks you to look for his mate, Krilge."] = "{npc:3363}經營{object:173018}，位於{object:172960}東邊的主街上。他請你去找他的伴侶。",
		["{npc:5675}: he binds the incubus to you"] = "{npc:5675}：他會把夢魔束縛給你",
		["{npc:5875}: he binds the incubus to you"] = "{npc:5875}：他會把夢魔束縛給你",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} in the Temple of the Damned, just north of him."] = "{object:1661}的版本，給接了{npc:5675}而非{npc:5875}的{quest:1472}的術士。20級時，{object:36082}的{npc:5675}會派你去找就在他北邊詛咒者神殿裡的{npc:5693}。",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "30多級後期的副手寶珠或法杖，走地獄犬或地獄火的路線，任你選擇。",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "35級時，{object:172960}的{npc:3326}會派你去找{area:392}的{npc:6266}。",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "35級時，{object:36082}的{npc:4563}會派你去找{area:392}的{npc:6266}。從{zone:1420}出發的飛艇飛往{zone:1411}。",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "35級時，{object:2101}{object:2164}的{npc:461}會派你去找{area:392}的{npc:6266}。",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "35級時，{zone:1455}的{npc:5172}會派你去找{area:392}的{npc:6266}。",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, wait while she completes the {item:15108}, then speak to her again."] = "帶著淨化過的寶珠回到{area:392}上方塔裡的{npc:6266}那裡。走地獄犬路線時，等她完成{item:15108}，然後再和她說話。",
		["Back to {npc:6266} in the tower above {area:392} with the spirit first: {npc:6546}'s cleansing follows it."] = "先帶著靈魂回到{area:392}上方塔裡的{npc:6266}：之後才是{npc:6546}的淨化。",
		["Choose an acolyte"] = "選擇一名侍僧",
		["On the infernal path, wait while {npc:6266} completes the {item:15107}, then speak to her again."] = "走地獄火路線時，等{npc:6266}完成{item:15107}，然後再和她說話。",
		["Orb of Orahil"] = "奧拉赫寶珠",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, {npc:6252}'s infernal path with the Orb or {item:15105}. The guide follows the one you take."] = "選擇一名侍僧：他們的任務你只能接其中一個。{npc:6254}的地獄犬路線最後獲得寶珠或{item:15106}，{npc:6252}的地獄火路線最後獲得寶珠或{item:15105}。本指南會依照你接的那條路線。",
		["The demon's spirit"] = "惡魔的靈魂",
		["The demons of {area:602}, in southern {zone:1443}, have all you need. Burning Blade Summoners carry the {item:7291}. On the felhound path, use the {item:12647} on a {npc:4678}, a felhound, and kill it for its spirit; on the infernal path, use the {item:12646} on a {npc:4676} and kill it."] = "{zone:1443}南部{area:602}的惡魔有你需要的一切。火刃召喚師帶著{item:7291}。走地獄犬路線時，對地獄犬{npc:4678}使用{item:12647}，然後擊殺牠取得靈魂；走地獄火路線時，對{npc:4676}使用{item:12646}並擊殺牠。",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["Wait for the orb"] = "等待寶珠完成",
		["{item:12648}, from a {npc:4678}"] = "{item:12648}，來自{npc:4678}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}，來自{npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}，來自火刃召喚師",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}：他會給你{item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}：她會給你{item:12647}",
		["{npc:6266} and her two acolytes stand in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266}和她的兩名侍僧站在{area:392}上方山丘的塔裡，就在{npc:6251}旁邊。",
		["{npc:6546} lives at her farm in western {zone:1445}. She calls the {npc:6549} out of the {item:7291}; it is elite: grouping up is advised."] = "{npc:6546}住在{zone:1445}西部她的農場。她會從{item:7291}中召喚出{npc:6549}；它是精英：建議組隊。",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your late 20s, for fragments from two dungeons."] = "適合20多級後段的稀有副手寶珠或法杖，用兩個地城的碎片換取。",
		["Back to {npc:6247}"] = "返回{npc:6247}",
		["The Shadowfang Darksouls inside {area:236}, a level 20-30 dungeon, drop the Large Fragment about one time in five: bring a group. The keep stands south of the {area:228}."] = "{area:236}（20-30級地城）裡的影牙魔魂狼人約每五次掉落一次大型碎片：找小隊一起去。城堡位於{area:228}南邊。",
		["The Twilight Acolytes inside {area:2797}, a level 24-32 dungeon, each drop a {item:6914}: bring a group. The entrance is in the ruins on the north-west coast of {zone:1440}."] = "{area:2797}（24-32級地城）裡的每個暮光侍僧都會掉落{item:6914}：找小隊一起去。入口在{zone:1440}西北海岸的廢墟中。",
		["{item:6914}, from the Twilight Acolytes"] = "{item:6914}，來自暮光侍僧",
		["{item:6915}, from the Shadowfang Darksouls"] = "{item:6915}，來自影牙魔魂狼人",
		["{npc:6247} camps in the southern {zone:1413}, east of the road north-east of {area:378}."] = "{npc:6247}在{zone:1413}南部紮營，位於{area:378}東北方道路的東側。",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "50多級時從{zone:1448}{npc:14469}和{npc:14470}取得的稀有副手，這個營地也提供「小鬼的要求」。",
		["At 50 {npc:14469} and his imp {npc:14470} wait in central {zone:1448}, just east of {area:1763}."] = "50級時，{npc:14469}和他的小鬼{npc:14470}在{zone:1448}中部、{area:1763}東邊等候。",
		["Back to {npc:14469}"] = "回到{npc:14469}那裡",
		["The Felguard Sentries around the {area:72}, in southern {zone:1419}, carry its essence."] = "{zone:1419}南部{area:72}周圍的地獄衛士斥候帶著它的精華。",
		["The Jaedenar Legionnaires, a short way west of {npc:14469}, carry {area:1763}'s essence."] = "在{npc:14469}西邊不遠處的加德納爾軍團士兵帶著{area:1763}的精華。",
		["The Legashi satyrs of northern {zone:1447} carry {zone:1447}'s essence."] = "{zone:1447}北部的雷加斯薩特帶著{zone:1447}的精華。",
		["{item:18626}, at {object:179677}"] = "{item:18626}，在{object:179677}",
		["{npc:14467}' remains lie in {area:1766}, north of {npc:14469}. Use the {item:18626} beside them and kill the infernal when he wakes. {npc:14467} is elite: grouping up is advised."] = "{npc:14467}的遺骸在{npc:14469}北邊的{area:1766}。在遺骸旁使用{item:18626}，等地獄火醒來後擊殺他。{npc:14467}是精英：建議組隊。",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "60級的稀有副手，是{npc:14463}為了你在{zone:1419}捕捉{npc:12396}而給的報酬。",
		["At 60 {npc:14463} waits in the {area:73}, in western {zone:1419}."] = "60級時{npc:14463}在{zone:1419}西部的{area:73}等候。",
		["Back to {npc:14463}"] = "返回{npc:14463}處",
		["Hand both in to {npc:14463}, then find the {npc:12396} in the {area:73} and use the {item:18601} on him. He is elite and fights to escape: grouping up is advised."] = "把兩樣都交給{npc:14463}，然後在{area:73}找到{npc:12396}，對他使用{item:18601}。他是精英，會掙扎逃脫：建議組隊。",
		["The Hederine demons hold {area:2256}, in southern {zone:1452}. They are elite: grouping up is advised."] = "赫達琳惡魔佔據{zone:1452}南部的{area:2256}。牠們是精英：建議組隊。",
		["The Wildspawn satyrs of the Warpwood Quarter, {area:2577}'s eastern wing, carry the blood. The back door at {area:2518}, north of {area:1099}, needs the {item:18249}; otherwise go in by {area:2577}'s main entrance. Bring a group."] = "{area:2577}東翼的荒野薩特身上帶著血。位於{area:1099}北邊{area:2518}的後門需要{item:18249}；否則從{area:2577}的正門進入。要帶小隊。",
		["{item:18601}, on the {npc:12396}"] = "{item:18601}，對{npc:12396}使用",
		["{item:18603}, inside the Warpwood Quarter"] = "{item:18603}，在東翼裡",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "20級時，{zone:1456}的戰士訓練師{npc:3041}會派你去找{area:378}的{npc:6394}。",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "20級時，{object:172958}的{npc:3354}會派你去找{area:378}的{npc:6394}。",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "20級時，{zone:1458}的戰士訓練師{npc:4595}會派你去找{area:378}的{npc:6394}。",
		["Back to {npc:5878} beside the road east of the {area:380}. {quest:1848} is the first piece; he then sends you to three crafters for the rest."] = "回到{area:380}東邊路旁的{npc:5878}那裡。{quest:1848}是第一件；接著他會派你去找三位工匠製作其餘部件。",
		["Fly to {area:378}. South of the camp the Silithid Mounds dot the {area:390}: the silithid there carry the Twitching Antennae."] = "飛往{area:378}。營地南邊的{area:390}散布著異種蠍土丘：那裡的異種蠍帶著顫抖的觸角。",
		["Four armor pieces at 30 (hauberk, helm, gauntlets, legguards) and a shield on the way."] = "30級時的四件護甲（鎖甲、頭盔、護手、護腿），途中還有一面盾牌。",
		["Hillsbrad Miners"] = "希爾斯布萊德礦工",
		["Iron Bars"] = "鐵錠",
		["Iron Bars: {npc:8673}"] = "鐵錠：{npc:8673}",
		["Miners smelt Iron Bars from {item:2772} ({skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "礦工可用{item:2772}熔煉鐵錠（{skill:186}125）；其他人在{zone:1454}的拍賣場購買。",
		["Roogug in {area:1717}"] = "{area:1717}的魯古格",
		["Roogug is an elite quilboar inside {area:1717}, the dungeon at the south end of the {zone:1413}; he drops the {item:6841}. {area:1717} is a dungeon: grouping up is advised."] = "魯古格是{area:1717}裡的精英野豬人，那是{zone:1413}南端的地城；他會掉落{item:6841}。{area:1717}是地城：建議組隊。",
		["Smoky Iron Ingots from the Windshear kobolds"] = "從風剪狗頭人身上取得煙霧鐵錠",
		["Sturdy Dragonmaw Shinbones"] = "結實的龍喉脛骨",
		["Take the zeppelin from {zone:1454} to {zone:1420}; the {zone:1458} lies below the {area:153}."] = "從{zone:1454}搭飛艇前往{zone:1420}；{zone:1458}位於{area:153}下方。",
		["The Dragonmaw orcs camp in the middle of the {zone:1437}, south of the road; Raiders, Swamprunners, Centurions, Shadowwarders and Bonewarders all drop the Sturdy Dragonmaw Shinbones."] = "龍喉獸人在{zone:1437}中部、道路南邊紮營；龍喉襲擊者、龍喉沼澤行者、龍喉百夫長、龍喉暗影守衛和龍喉白骨守衛都會掉落結實的龍喉脛骨。",
		["The Hillsbrad Miners work the mine in the west of {zone:1424}; they drop the {item:7127}. Take the zeppelin from {zone:1454} to {zone:1420} and ride south through {zone:1421}."] = "希爾斯布萊德礦工在{zone:1424}西部的礦坑工作；他們會掉落{item:7127}。從{zone:1454}搭飛艇前往{zone:1420}，再向南騎過{zone:1421}。",
		["The {area:2160} lies at the east end of {area:461} in Stonetalon. Its kobolds drop the Smoky Iron Ingots."] = "{area:2160}位於石爪山脈{area:461}的東端。那裡的狗頭人會掉落煙霧鐵錠。",
		["The {area:429} satyrs camp in eastern {zone:1440}, with the Felmusk satyrs further west; both drop Uncloven Satyr Hooves."] = "{area:429}的薩特在{zone:1440}東部紮營，魔草薩特在更西邊；兩者都會掉落完整的薩特之蹄。",
		["The {npc:6167} roams the south-west of Stonetalon near the Fledgling and Young Chimaeras; she drops the {item:6840}."] = "{npc:6167}在石爪山脈西南部、奇美拉雛獸和小奇美拉附近遊蕩；她會掉落{item:6840}。",
		["Twitching Antennae from the silithid"] = "從異種蠍身上取得顫抖的觸角",
		["Uncloven {quest:1842}"] = "完整的{quest:1842}",
		["{item:6840} from the {npc:6167}"] = "從{npc:6167}身上取得{item:6840}",
		["{item:6841}, from Roogug"] = "{item:6841}，來自魯古格",
		["{item:7127} from the Hillsbrad Miners"] = "從希爾斯布萊德礦工身上取得{item:7127}",
		["{npc:5878} camps beside the road east of the {area:380}. {quest:1838} is a level 30 quest; you can take it now and gather for it on the way."] = "{npc:5878}在{area:380}東邊的路旁紮營。{quest:1838}是30級任務；你可以現在接下，順路收集材料。",
		["{npc:6408} is in {area:367} on the {zone:1411} coast."] = "{npc:6408}在{zone:1411}海岸的{area:367}。",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["A hauberk at 28, a coif, leggings or gauntlets by race, and a shield on the way."] = "28級的鎖甲衫、依種族而定的頭巾、護腿或護手，以及途中的一面盾牌。",
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "20級時，{zone:1455}的戰士訓練師{npc:5113}會派你去赤脊山找{quest:1698}。",
		["At 20, {npc:5479} in {object:2100}, beside the Pig and Whistle, sends you to {quest:1698} in Redridge."] = "20級時，{object:2100}酒館旁的{npc:5479}會派你去赤脊山找{quest:1698}。",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "20級時，{zone:1457}的戰士訓練師{npc:7315}會派你去赤脊山找{quest:1698}。",
		["Back to {npc:5413} in the {object:28027}. He sends you on to a smith of your own race."] = "回到{object:28027}的{npc:5413}處。他會派你去找你自己種族的鐵匠。",
		["Charred and Galvanized Horns"] = "燒焦的奇美拉角與光滑的奇美拉角",
		["Enter the {area:98} and come back"] = "進入{area:98}再回來",
		["Fire Hardened Armor"] = "火焰淬煉護甲",
		["Ride the {area:2257} from {zone:1453} to {zone:1455}."] = "從{zone:1453}搭乘{area:2257}前往{zone:1455}。",
		["Roogug in {area:1717}"] = "{area:1717}的魯古格",
		["Roogug is an elite quilboar inside {area:1717}, the dungeon at the south end of the {zone:1413}; he drops the {item:6841}. {area:1717} is a dungeon: grouping up is advised."] = "魯古格是{area:1717}裡的精英野豬人，那是位於{zone:1413}南端的地城；他會掉落{item:6841}。{area:1717}是地城：建議組隊。",
		["Scorched Spider Fangs"] = "燒焦的蜘蛛牙",
		["The Fledgling and Young Chimaeras roam the south-west of Stonetalon, with the {npc:6167} among them: the young ones drop the {item:6839}, the Matriarch the {item:6840}."] = "奇美拉雛獸和小奇美拉在石爪山脈西南部遊蕩，{npc:6167}也在牠們之中：小奇美拉會掉落{item:6839}，族母會掉落{item:6840}。",
		["The Leech Stalkers and Cave Stalkers crawl around 46,61 in the middle of the {zone:1437}; they drop the {item:6838}."] = "吸血捕獵者和洞穴捕獵者在{zone:1437}中部46,61附近爬行；牠們會掉落{item:6838}。",
		["The Nightbane worgen of {zone:1431} drop the {quest:1705}. {npc:6170} walks in the far south-east of {zone:1431} and carries the {item:6845}."] = "{zone:1431}的夜行狼人會掉落{quest:1705}。{npc:6170}在{zone:1431}最東南方走動，身上帶著{item:6845}。",
		["The {quest:1708} grows along the {zone:1437}' west coast, south of {area:150}."] = "{quest:1708}生長在{zone:1437}西海岸、{area:150}南邊。",
		["The {quest:1710} lie along the western edge of {zone:1441}."] = "{quest:1710}散落在{zone:1441}西緣。",
		["{item:6839} from the young chimaeras"] = "{item:6839}，來自小奇美拉",
		["{item:6840} from the {npc:6167}"] = "{item:6840}，來自{npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}，來自魯古格",
		["{item:6845} from {npc:6170}"] = "{item:6845}，來自{npc:6170}",
		["{npc:1416} is in {zone:1453}, a short walk from {npc:5413}."] = "{npc:1416}在{zone:1453}，離{npc:5413}不遠。",
		["{npc:5413} works in the Dwarven District of Stormwind. He keeps the {item:6843} and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest."] = "{npc:5413}在暴風城的矮人區工作。他會留下{item:6843}並給你{item:6970}，一面盾牌；{quest:1701}是28級任務。",
		["{quest:1698} is in {area:69}, at the inn. His test is timed: run north-west into the {area:98}, reach the first fork and come back to him before the timer runs out. Do not die and release your spirit."] = "{quest:1698}在{area:69}的旅店裡。他的測試有時間限制：向西北跑進{area:98}，到達第一個岔路口後在時間結束前回到他身邊。不要死亡並釋放靈魂。",
		["{quest:1703} is a smith in {zone:1457}."] = "{quest:1703}是{zone:1457}的鐵匠。",
		["{quest:1705} from the Nightbane worgen"] = "{quest:1705}，來自夜行狼人",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
		["Back to {npc:294}"] = "返回{npc:294}",
		["Haggard's Weapons"] = "哈加德的武器",
		["{npc:294}'s house is in eastern {zone:1429}, south of the road from {zone:1453} to Redridge."] = "{npc:294}的房子在{zone:1429}東部，從{zone:1453}通往赤脊山的道路南邊。",
