		["In the {object:172958}."] = "在{object:172958}。",
		["In the {object:172961}. Have the Wool, Silk and Mageweave in your bags."] = "在{object:172961}。背包裡要有毛料、絲綢和魔紋布。",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "莉芙的工作室在{area:392}碼頭北端；{object:149036}就在裡面。",
		["Ride back west to {area:1237}."] = "向西騎回{area:1237}。",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "向東騎往海岸上的遺跡。在沿岸的潮池裝滿科雷的四個瓶子；惡鞭納迦在潮池之間巡邏。",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there, then kill the Magus."] = "雷姆托里的營地在基地營的東端。閱讀那裡的{object:151286}，然後殺死法師。",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "血精靈在東北方{area:1227}旁的懸崖上紮營。",
		["The zeppelin tower stands just north-east of {zone:1454}'s main gate; take the {zone:1458} zeppelin."] = "飛艇塔就在{zone:1454}正門東北方不遠處；搭乘前往{zone:1458}的飛艇。",
		["Zeppelin to the {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["Zeppelin tower"] = "飛艇塔",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}，在 Apothecarium",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}，{object:172957}：保留給{zone:1451}",
		["{npc:256386} stands in the {area:380}. Open each crate she hands you and bring back what is inside."] = "{npc:256386}站在{area:380}。打開她交給你的每個箱子，把裡面的東西帶回來。",
		["{npc:256386}'s crates"] = "{npc:256386}的箱子",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901}在{area:392}北邊不遠處的岸邊紮營。",
		["{npc:8393}, beside him"] = "{npc:8393}，在他旁邊",
		["{npc:8403}, nearby"] = "{npc:8403}，在附近",
		["{npc:8578}'s camp"] = "{npc:8578}的營地",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，{object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050}要交回給{zone:1422}的{npc:10778}：保留此任務。",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "一張撕破的卷軸在{area:2260}南邊的地穴{area:2261}入口。",
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "回到隧道，走{zone:1452}出口，然後向南騎到{area:2246}。",
		["Back to {area:1638}"] = "返回{area:1638}",
		["Both quests lead to {zone:1451}: keep them."] = "兩個任務都通往{zone:1451}：先留著。",
		["Fly to the {zone:1458}, take the zeppelin to {zone:1454} and fly on to {area:1638}."] = "飛往{zone:1458}，搭飛艇到{zone:1454}，再飛往{area:1638}。",
		["Fly to {area:1099}. The hippogryph nests are in the south of {zone:1444}; each holds an egg for the {object:142071}."] = "飛往{area:1099}。角鷹獸巢在{zone:1444}南部；每個巢都有一顆蛋可放進{object:142071}。",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:2268}"] = "飛往{area:2268}",
		["Fly to {area:541}, then ride south-west through Un'Goro to the pass into {zone:1451}. The next guide opens at {area:3077}, where the pass comes out."] = "飛往{area:541}，然後向西南騎過安戈洛環形山，穿過山口進入{zone:1451}。下一份指南從山口出口的{area:3077}開始。",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "狂怒的瘟疫犬和巨型瘟疫蝙蝠共同分布在{area:2273}南邊、{area:2272}和{area:2271}周圍的田野。",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "穿過{area:1769}，走隧道通往{zone:1450}的支線。{npc:11801}在{area:2361}。",
		["Hameya hides among the Mossflayer trolls of {area:2273}, in the north-east corner."] = "滲透者哈米亞躲在東北角{area:2273}的爛苔食人妖之間。",
		["Hameya's mound"] = "哈米亞的土堆",
		["Hameya's scroll"] = "哈米亞的卷軸",
		["Hippogryph eggs"] = "角鷹獸蛋",
		["Moontouched Owlbeasts"] = "月光梟獸",
		["On to {zone:1451}"] = "前往{zone:1451}",
		["On {area:1641}. Have the Wool, Silk and Mageweave in your bags."] = "在{area:1641}。背包裡要帶著毛料、絲綢和魔紋布。",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "只有在掉落了{quest:8471}時：{npc:11558}在{area:1769}的{zone:1448}入口等著，而且只有在你對木喉熊怪為中立時才會和你交談。",
		["Only if you found a {item:12820} flask in {zone:1452}: ride north up the road. The cauldron stands in {area:1762}, just south-west of {area:1769}; the Deadwood furbolgs there are hostile."] = "只有在{zone:1452}找到{item:12820}酒瓶時：沿道路向北騎。大鍋在{area:1769}西南方不遠的{area:1762}；那裡的死木熊怪是敵對的。",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "瘟疫幼犬和瘟疫蝙蝠在{area:2260}北邊的丘陵遊蕩，腐肉蟲在牠們之間爬行；一路向北往{area:2627}推進。",
		["Plaguehounds and their runts roam the shores of the lake south-west of the chapel."] = "瘟疫犬和瘟疫幼犬在禮拜堂西南方的湖岸邊遊蕩。",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "向東騎到{area:2255}再向北出城；月光梟獸在{area:2241}南坡的丘陵遊蕩。一次只拉一隻。",
		["Ride west to the {area:2260}."] = "向西騎到{area:2260}。",
		["Sword of Marduk"] = "馬杜克的破碎之劍",
		["The high elf Rangers, Pathstriders and Woodsmen guard the lodge by {area:2275}; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way."] = "高等精靈遊俠、巡路者和護林者守衛著{area:2275}旁的小屋；名冊在屋內。遊俠最高60級：一次只拉一隻。途中田野上空有毒性瘟疫蝙蝠飛行。",
		["The shattered sword lies on the ground north-west of the lake."] = "破碎的劍躺在湖的西北方地上。",
		["The skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "頭骨在{area:2622}，周圍有荒蕪水元素和瘟疫水元素。",
		["The western hills"] = "西部丘陵",
		["The {area:2622}"] = "{area:2622}",
		["The {object:142071} machine"] = "{object:142071}機器",
		["The {object:177675} is just behind the {area:2261}."] = "{object:177675}就在{area:2261}後面。",
		["Use {npc:10980} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "對{area:976}的哥布林女孩{npc:7583}使用{npc:10980}。{npc:10977}和{npc:10978}會在路線後段被嚇到。",
		["{item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once."] = "{item:15447}十分鐘內就會腐壞：快速擊殺鎮上的天譴軍團，並立刻用{item:15454}磨碎七份。",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "鬼魂{npc:11140}站在西北角{area:2627}的一間小屋旁。",
		["{npc:15193}'s champion holds the {area:2260} farmhouse."] = "{npc:15193}的勇士佔據{area:2260}的農舍。",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771}在{area:976}南邊、通往{area:1336}的路旁紮營。",
		["{npc:9299} is a ghost at the graveyard just north of {area:976}; the Conspicuous Gravestone is south of it, outside the town wall."] = "{npc:9299}是{area:976}北邊墓地的鬼魂；明顯的墓碑在它南邊、城牆外。",
		["{object:1661}'s flight master is in the {object:36078}'s west tower, outside the walls."] = "{object:1661}的飛行管理員在{object:36078}城牆外的西塔。",
		["{quest:3914} goes back to Linken in Un'Goro: keep it."] = "{quest:3914}要交回安戈洛環形山的林克：先留著。",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it if you have it."] = "{quest:5086}在{zone:1448}，之後的行程再去：如果有就先留著。",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "{quest:5168}的物品在之後的瘟疫之地區域：先留著。",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Andorhal watchtowers and silos"] = "安多哈爾的哨塔與穀倉",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "回到南風村並爬上塔。攪動塔頂的蟲巢會引出亞什伏擊者；其中一隻帶著{item:17346}。",
		["Back to {area:3425}"] = "回到{area:3425}",
		["Dithers offers {item:14619} ({quest:838}). Skip it."] = "迪瑟斯提供{item:14619}（{quest:838}）。跳過。",
		["Dredge Crushers and Pincers"] = "掘泥摧毀者與巨鉗蠍",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "掘泥打擊者、石鞭蠍和掠沙蜘蛛都在城堡北邊不遠的沙地上。",
		["Dredge and scorpids"] = "掘泥者與蠍子",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "沿著道路往東，{npc:11077}守著{area:200}的大鍋。",
		["Flayers and Rock Stalkers"] = "掠奪者與石行蜘蛛",
		["Fly to {area:1637} and train."] = "飛往{area:1637}並訓練。",
		["Fly to {area:976}. The {object:142071} stands in the middle of town."] = "飛往{area:976}。{object:142071}就在鎮中央。",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "沿著西側沙丘往北走；從這裡到城堡一帶都有掘泥摧毀者和石鞭巨鉗蠍。",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "保留{quest:3942}：{npc:9116}在{area:2479}，下一份指南經過{zone:1448}時會路過。",
		["Mar'alith's Dearest Natalia needs level 58 and leads into {area:2744} among elites. Skip it."] = "瑪爾利斯的「親愛的娜塔莉雅」需要等級 58，而且要深入精英環伺的{area:2744}。跳過。",
		["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}標記{npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}標記{npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}標記{npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}標記{npc:10905}",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "往北到伐木場；把白蟻桶放在鋸木廠中央。",
		["Ride east across the plaguelands to the chapel."] = "往東穿過瘟疫之地到禮拜堂。",
		["Ride east along the road to the {area:152} on the border."] = "沿著道路往東騎到邊界上的{area:152}。",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "往東騎到{area:2619}旁{npc:1855}的小屋，聽他把話說完。",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "往東北騎到{area:3077}；從旁邊的山道離開{zone:1451}。",
		["Ride north-east to {area:3447}."] = "往東北騎到{area:3447}。",
		["Ride north-west to {npc:1855}'s hut."] = "往西北騎到{npc:1855}的小屋。",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "往南騎進安多哈爾。{npc:10667}在鎮西側的旅店廢墟裡等著。帶著{item:12815}站在四座哨塔各自的門口來標記；沿著鎮的外緣走。在鎮中央的穀倉旁使用{item:12627}，引出時光寄生蟲。",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "往東南騎到安戈洛懸崖下的{area:3447}。",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "往西南騎到{area:2738}的廢墟。要交給{npc:11801}的{object:179565}就在其中一間破屋裡。",
		["Ride south-west to {npc:10667} in Andorhal."] = "往西南騎到安多哈爾找{npc:10667}。",
		["Ride to {area:2262} in the south-west; {npc:10926} plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town."] = "騎到西南方的{area:2262}；{npc:10926}在房屋之間玩耍。{npc:11886}潛伏在{area:2261}，就是鎮西邊不遠的墓穴。",
		["Ride west to the Horde camp north of {area:2744}."] = "往西騎到{area:2744}北邊的部落營地。",
		["Ride west to the walled hold in the middle of the desert."] = "往西騎到沙漠中央有城牆的城堡。",
		["Scourge Champions"] = "天災勇士",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "天災勇士在禮拜堂北邊的{area:2270}遊蕩。每殺一隻就用{npc:11063}的{item:13156}掃過屍體：產生共鳴的頭骨就是他要的。",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "南部沙漠各處會有希利蘇斯之塵間歇泉噴發。走進噴發後留下的希利蘇斯之塵，把它帶到奇立卡營地的部落希利蘇斯之塵提取器；戰鬥或騎乘坐騎會讓它掉落。",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "石鞭掠奪者和石行蜘蛛在奇立卡營地西南的沙丘上遊蕩。",
		["Take the zeppelin from the tower outside {area:1637} to {zone:1420} and ride into the {zone:1458}. Lady Sylvanas holds the {object:36126}."] = "在{area:1637}外的塔上搭飛艇到{zone:1420}，再騎進{zone:1458}。希瓦娜斯女士在{object:36126}。",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "發光的石碑碎片散落在極西北的暮光營地周圍；那裡的灰塵風暴和沙漠奔行者也會掉落。",
		["The libram lies further north, on the way to {area:190}."] = "聖契在更北邊，前往{area:190}的路上。",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "從安戈洛來的山道出口在{area:3077}，也就是{zone:1451}東北部的墓地。{npc:13220}站在墳墓之間。",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "背包在極南方的山裡，過了銅鬚營地就是。精英蠍子死亡彎鉤在附近巡邏：趁牠離開時拿走。",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "盾牌在{npc:1855}小屋南邊的{area:201}。",
		["The spare texts from the cultists"] = "從信徒身上多拿的文件",
		["Through the pass and east along the northern cliffs to {area:541}. {npc:8737} stands by the cave; {npc:9117} is inside it."] = "穿過山道，沿北側懸崖往東到{area:541}。{npc:8737}站在洞口旁；{npc:9117}在洞裡。",
		["Twilight Vanguard"] = "暮光先鋒",
		["Use {npc:10980} on {npc:10977}"] = "對{npc:10977}使用{npc:10980}",
		["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "往西到{area:152}。下一份指南從往西騎不遠的{zone:1458}開始。",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "{npc:10667}的達隆郡之戰最後要對付精英。跳過。",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field."] = "{npc:10778}的農場是{area:152}以東的第一座。農場上的喋喋不休的食屍鬼身上有她護符的另一半；{npc:11075}守著田裡的大鍋。",
		["{npc:10926} and the {area:2261}"] = "{npc:10926}與{area:2261}",
		["{npc:10926}'s own errand is not on this route. Skip it."] = "{npc:10926}自己的差事不在這條路線上。跳過。",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803}在極西南的先鋒營地巡邏。不論有沒有任務，這裡每個信徒都會掉落暮光加密文件：收集二十份，十份給{npc:15306}，十份給奧泰爾。",
		["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804}站在{area:3425}西邊的前哨站。在這裡的信徒身上把暮光加密文件補到二十份。",
		["{npc:11878}' errands are not on this route. Skip them."] = "{npc:11878}的差事不在這條路線上。跳過。",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "{npc:15193}的勇士守在{area:2261}北邊的{area:2260}農舍。",
		["{npc:15200} holds the camp in the west."] = "{npc:15200}守在西邊的營地。",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}，在城堡西側",
		["{npc:1855}'s next task, Of Lost Honor, is not on this route. Skip it."] = "{npc:1855}的下一個任務「失落的榮耀」不在這條路線上。跳過。",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "回到木喉隧道，從{zone:1452}出口出去；{npc:9298}就在出口外的溫泉旁紮營。",
		["Back south to the Sanctuary, a short ride."] = "向南回到聖地，路程很短。",
		["Dungeon instead of grinding"] = "以地城代替練等",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "飛往{area:431}，沿著道路向西北離開{zone:1440}進入{zone:1448}。{area:2479}就是過了邊界不遠的德魯伊營地。",
		["From the {zone:1458}, take the zeppelin from the tower outside the city to {zone:1454}."] = "從{zone:1458}出發，在城外的塔搭飛艇前往{zone:1454}。",
		["Grind to 60"] = "練到60級",
		["In {zone:1454}: fly from {area:2255}"] = "在{zone:1454}：從{area:2255}飛過去",
		["In {zone:1456}: fly from {area:2255}"] = "在{zone:1456}：從{area:2255}飛過去",
		["Only if you carry {quest:5087}: the runners walk the road from {area:1769} toward {area:2244} in small groups; wait by the road near {npc:9298} and kill them as they pass. Each one carries a crate."] = "僅限你帶著{quest:5087}時：信使們成小群從{area:1769}沿著道路走向{area:2244}；在{npc:9298}附近的路旁等候，趁他們經過時擊殺。每個信使都帶著一個箱子。",
		["Only if {npc:9298} gave you {quest:5086}: ride north up the {zone:1448} road to {area:1767}; the {quest:5086} ooze between the trees."] = "僅限{npc:9298}給了你{quest:5086}時：沿著{zone:1448}的道路向北騎往{area:1767}；{quest:5086}在樹林間蠕動。",
		["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "僅限持有30塊{quest:6031}，且木喉聲望為中立時：沿著道路向北前往{area:1769}；{npc:11557}就在入口內交易。",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "可選。和小隊打{area:2279}、{area:2057}、黑石塔下層或{area:1584}代替練等，能更快達到目標。",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "可選：有小隊的話，一個55-60級地城可以取代下面的練等。",
		["Ride east along the road to {area:2255}."] = "沿著道路向東騎往{area:2255}。",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "沿著道路向北騎，經過{area:1763}，前往{area:1997}。",
		["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one."] = "向西北騎往{area:1763}。四個火盆位於教徒的建築之間；對每個火盆使用淨化過的水。",
		["South to the Sanctuary once more."] = "再次向南前往聖地。",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "任務到這裡就沒了。瘋狂的碎齒熊在{zone:1452}南部、{area:2255}出來的道路南邊的{area:2249}徘徊。",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "穿過木喉隧道前往{zone:1450}。{npc:11939}在{area:2361}的一間房子裡看書。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "在{zone:1452}的{area:2249}擊殺{npc:7446}練等",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "{npc:10306}接下來的{quest:4741}會讓你從{zone:1452}跑回這裡。跳過。",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}的「魔藤碎片」需要{area:2577}。跳過。",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "{npc:9116}的「銀爪鐵心」需要{zone:1448}北部的{item:11173}，還要騎回這裡。跳過。",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298}接著會派你去對付洞穴裡的精英{npc:10738}。跳過。",
		["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go."] = "{npc:9861}、{npc:9860}和{npc:9517}在{area:1763}北部洞穴{area:1770}的深處等候。沿途清理隧道。",
} end)()
t.guides["forever/horde/orc-troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "硬甲蠍在{area:362}西邊的平原上爬行。馴服一隻，然後回到{npc:3171}那裡。",
		["Back at the Den"] = "回到大獸穴",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "向東回到{npc:275657}北邊的海岸。{npc:275662}和其他惡鞭納迦佔據{area:370}下方的海灘。獵人：在海灘上馴服一隻{npc:3107}。",
		["Back south to {area:362}."] = "向南回到{area:362}。",
		["Back to the Den"] = "回到大獸穴",
		["Back to {area:362}."] = "回到{area:362}。",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "回到{object:172960}找{npc:5875}。在那裡的召喚法陣使用{item:7464}，擊敗虛空行者以束縛它。",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "燃刃氏族的教徒佔據{quest:827}的洞穴；他們都會掉落{item:4871}。{npc:3204}是14級的術士，站在深處，會掉落{item:4903}。",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "地獄捕獵者在洞穴下方的山坡上遊蕩，位於山谷北側。",
		["Fizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way."] = "費索佔據{area:362}西北方{area:369}上的燃刃氏族營地。獵人：沿途用{item:15908}馴服一隻{npc:3099}。",
		["Follow the road east out of the valley to {area:367} on the coast."] = "沿著道路向東離開山谷，前往海岸邊的{area:367}。",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "沿著道路從{area:362}向北前往{zone:1454}的正門，就在{area:817}西邊。{npc:3352}和獵人訓練師們站在{object:172958}。",
		["Follow the road north to {area:362}."] = "沿著道路向北前往{area:362}。",
		["Follow the road north toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "沿著道路向北往{zone:1454}走。{npc:3293}在路旁紮營；被偷的袋子散落在他南邊的道路沿線。",
		["Follow the road south-west from {area:379} to the {area:380}. {zone:1413} guide starts here."] = "沿著道路從{area:379}向西南前往{area:380}。{zone:1413}指南從這裡開始。",
		["Follow the road west from {area:362} over the {area:814} bridge; {area:379} sits just above it on the {zone:1413} side."] = "沿著道路從{area:362}向西過{area:814}的橋；{area:379}就在橋上方的{zone:1413}那一側。",
		["Free {npc:275811} and see her safely out of the crag"] = "釋放{npc:275811}，並護送她安全離開峭壁",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "向南穿過群島。洛阿神像遍布南部島嶼；巫毒食人妖和被施妖術的食人妖守著它們，並掉落妖術墜飾。{quest:826}和明希納的囚籠在最南端的島上。",
		["Hit the sleeping peons north of the Den with the {item:16114}."] = "用{item:16114}敲打大獸穴北邊睡著的苦工。",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "進入洞穴後，在第一個岔路直走，然後往右，沿著左手邊的溪流走到瀑布：鎬在水邊發光，在一根石柱後面。",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "進入洞穴後，一路沿著右側牆壁繞行，越過溪流：{npc:3183}在盡頭等著。",
		["Makrura and crawlers"] = "龍蝦人與海浪蟹",
		["Makrura and surf crawlers line the beaches north-east of Sen'jin."] = "龍蝦人和海浪蟹分布在森金村東北方的海灘。",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "米莎的小屋在蜥蜴的南邊。西邊{area:814}沿岸的鱷魚身上帶著{item:4891}。",
		["North end of the valley"] = "山谷北端",
		["Prickly pears"] = "仙人掌果",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "鋼鬃野豬人和鋼鬃斥候佔據城鎮西邊的小屋；鋼鬃傳令兵和鋼鬃衛兵佔據更西邊的營地。",
		["Ridgeshade spiders"] = "脊影蜘蛛",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}."] = "塵風暴徒和塵風雷巫在{npc:3293}東邊的{area:370}築巢。塵風雷巫會掉落{item:277661}。",
		["South-east shore"] = "東南海岸",
		["Spitelash naga"] = "惡鞭納迦",
		["Talk to {npc:3191}"] = "與{npc:3191}交談",
		["Tame it with the {item:15908}"] = "用{item:15908}馴服牠",
		["The foreman stands at the lumber pile east of the Den."] = "工頭站在大獸穴東邊的木材堆旁。",
		["The gnomish toolboxes lie in the wreckage along the shore east and south-east of {area:362}. Follow the shore south to Sen'jin."] = "地精工具箱散落在{area:362}東邊和東南方海岸的殘骸中。沿著海岸向南走到森金村。",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "城堡位於{area:362}東南方的海岸上。襲擊者的斧頭、弓和盾牌在城堡外圍。庫爾提拉斯水手和水兵會掉落{item:4870}。{npc:3192}在城堡頂端等候；他的鑰匙可以打開他旁邊的箱子，裡面有{item:4881}。",
		["The prickly pears grow among the quilboar huts just west of town."] = "仙人掌果生長在城鎮西邊的野豬人小屋之間。",
		["The spiders lurk in the hills along the road north toward {area:362}."] = "蜘蛛潛伏在往北通往{area:362}的道路沿線山丘中。",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "武器散落在大獸穴和訓練場周圍；雜斑野豬在整個谷底遊蕩。",
		["The wreckage"] = "殘骸",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}在{area:817}裡，就在你剛才打過的教徒之間。",
		["The {quest:792} swarm the slope below the {area:365}, the cave on the valley's north side."] = "{quest:792}聚集在{area:365}下方的山坡上，那是山谷北側的洞穴。",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "雷霆蜥蜴和閃電蜥蜴在橋對面的{area:369}吃草；牠們都可能掉落{item:6486}。",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}."] = "雷霆蜥蜴和閃電蜥蜴在{npc:3293}西邊和西南方的{area:369}吃草。",
		["Thunder lizards"] = "雷霆蜥蜴",
		["Thunder lizards across the river"] = "河對岸的雷霆蜥蜴",
		["Training weapons and boars"] = "訓練武器與野豬",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "涉水到北邊的回音群島。族母在那裡的迅猛龍之間徘徊。",
		["Wade back west to the shore south of Sen'jin. Durotar Tigers roam it and the Taillasher eggs sit in nests along the beach."] = "涉水向西回到森金村南邊的海岸。杜洛塔猛虎在那裡遊蕩，鞭尾龍的蛋在海灘沿線的巢裡。",
		["Wake {quest:5441} with the {item:16114}"] = "用{item:16114}叫醒{quest:5441}",
		["the {object:654925} on the ground beside her"] = "她旁邊地上的{object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}在森金村西邊。三份進攻計畫放在半人馬帳篷之間的地上。{npc:275811}也被關在峭壁那裡。",
		["{area:817}'s mouth"] = "{area:817}入口",
		["{npc:10176}, where you start"] = "{npc:10176}，在你的出生點",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears."] = "{npc:265809}在{area:362}南邊紮營。在他的營火旁坐下（/sit），直到出現{spell:1229451}增益效果。",
		["{npc:265809}'s campfire"] = "{npc:265809}的營火",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}：僅限附魔師，殘渣要從妖術墜飾分解取得",
		["{npc:266940}, on the east side of town"] = "{npc:266940}，在城鎮東側",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}站在{area:362}東邊的岸上。三叉戟、旗幟和匕首散落在他周圍的海灘上。",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}是一個年輕的海巨人，在{zone:1411}北岸、納迦海灘的北邊走動。{npc:275666}是精英：建議組隊。",
		["{npc:3102} hooves"] = "{npc:3102}的蹄子",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}，回到{area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}：{npc:275666}，一個精英海巨人",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}就站在洞口內；{npc:3159}在他身後的洞穴深處。",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}在大獸穴裡等候，就是{npc:10176}西邊的那棟建築。",
		["{npc:3147}, in the watchtower"] = "{npc:3147}，在瞭望塔裡",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}，大獸穴旁的戰士訓練師",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}，大獸穴旁的獵人訓練師",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}，大獸穴裡的盜賊訓練師",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}，洞穴深處的術士訓練師",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}，大獸穴旁的薩滿訓練師",
		["{npc:3159}, at the back of the cave"] = "{npc:3159}，在洞穴深處",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171}：{zone:1454}的{npc:3352}教授{spell:5149}",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}受傷躺在大獸穴西北方的山腳下。",
		["{npc:3294}, by the inn"] = "{npc:3294}，在旅店旁",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}，交給{zone:1454}的{npc:6018}：保留此任務",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}，大獸穴的牧師訓練師",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}，法師訓練師，在大獸穴入口",
		["{npc:5887} stands just outside the Den."] = "{npc:5887}就站在大獸穴外。",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}站在大獸穴外。{area:639}就是它南邊的山丘：在那裡喝下{item:6635}以看見{npc:5891}，然後把{item:6656}帶回給{npc:5887}。",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}：{npc:5873}和你的{item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}，在{area:639}上",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}站在山谷東側出口的道路上。",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}，在烹飪火堆旁",
		["{quest:790}, a large scorpid, prowls the slope south of {npc:3287} among the Scorpid Workers; pick the Cactus Apples by the cactuses on the way."] = "{quest:790}是一隻大蠍子，在{npc:3287}南邊的山坡上與工蠍一起徘徊；沿途在仙人掌旁採集仙人掌果。",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}在納迦海灘西邊的山丘上紮營，位於{quest:827}南邊。",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454}的正門就在{area:817}西邊。{npc:5875}站在{object:172960}，就是{object:172982}下方的峽谷。",
} end)()
t.guides["forever/horde/orc-troll/02-the-barrens"] = (function() return {
		["Back to the pirate camp: the boots are in the crate marked {object:3767} at the camp's south end, the lens in the Fragile crate just east of it."] = "回到海盜營地：靴子在營地南端標有{object:3767}的箱子裡，鏡片在它東邊不遠的易碎箱子裡。",
		["Back to the {area:380}"] = "返回{area:380}",
		["Back to the {area:380}; the next guide starts here."] = "返回{area:380}；下一份指南從這裡開始。",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}, by {area:370}; they drop the {item:6652}."] = "火刃祭司佔據{zone:1411}北部、{area:370}旁的{area:1898}；他們會掉落{item:6652}。",
		["Follow the road north to the {area:1703}; {npc:9316} stands just south of it."] = "沿道路向北前往{area:1703}；{npc:9316}就站在它南邊。",
		["Follow the road south-east to {area:392} on the coast."] = "沿道路向東南前往海岸的{area:392}。",
		["Head east to the Venture Co. research site west of the {area:382}. Use the {object:4141}, close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471}."] = "向東前往{area:382}西邊的風險投資公司研究站。使用{object:4141}，關閉鑽機周圍的三個閥門，再次使用控制台，然後從{npc:3471}身上取得{item:5089}。",
		["Kolkar camps and the {area:386}"] = "科卡爾半人馬營地與{area:386}",
		["Oasis Snapjaws crowd the water of {area:387}, south-west of the {area:380}."] = "綠洲鉗嘴龜擠滿了{area:380}西南方{area:387}的水域。",
		["On the way back to the {area:380}, the Razormane camp again: Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "在返回{area:380}的路上，再去一次鋼鬃營地：鋼鬃地卜師和鋼鬃防禦者佔據營地東半部；{npc:3438}在他們之間走動。",
		["Plainstriders and Sunscale raptors roam the plains all around the {area:380}."] = "平原陸行鳥和赤鱗迅猛龍在{area:380}周圍的平原上遊蕩。",
		["Plainstriders and raptors"] = "平原陸行鳥與迅猛龍",
		["Razormane camp"] = "鋼鬃營地",
		["Southsea beach"] = "南海海灘",
		["The Kolkar camps spread north-west of {npc:3389}; every Kolkar can drop {quest:855}. {area:386} lie in their middle, with Laden Mushrooms around the water. Savannah Prowlers roam the same plains."] = "科卡爾半人馬營地分布在{npc:3389}西北方；每個科卡爾半人馬都可能掉落{quest:855}。{area:386}在營地中央，水邊有豐滿的蘑菇。草原徘徊者在同一片平原遊蕩。",
		["The Slayers hold the western end of the {area:383}, past the harpies you fought before; they drop the rings."] = "巫翼殺戮者佔據{area:383}的西端，在你之前打過的鷹身人後方；她們會掉落戒指。",
		["The Tool Buckets sit around the Venture Co. camp in the {area:382}, east of {npc:9316}."] = "工具籃放在{npc:9316}東邊、{area:382}的風險投資公司營地周圍。",
		["The harpies nest in the {area:383} north-west of the {area:386}; any of them can drop a talon."] = "鷹身人在{area:386}西北方的{area:383}築巢；任何一隻都可能掉落爪子。",
		["The oasis lies south-east of the {area:380}. Test the seeds at the bubbling fissure in the middle of the water."] = "綠洲在{area:380}東南方。在水中央冒泡的裂縫測試種子。",
		["The pirates camp along the beach south of {area:392}. The piles of complicated parts lie in and around their camp."] = "海盜在{area:392}南邊的海灘上紮營。複雜零件堆就在他們的營地裡和周圍。",
		["The {area:1697} lie south-west of the oasis. Sunscale Scytheclaws drop the feathers you use on the three nests."] = "{area:1697}在綠洲西南方。赤鱗鐮爪龍會掉落羽毛，用在三個巢上。",
		["Wade into the pools to explore them"] = "涉水進入水池探索",
		["Walk back up the road to the {area:380}. Savannah Prowlers hunt along it and on the plains west of town: finish the claws before you hand them in."] = "沿道路走回{area:380}。草原徘徊者在路邊和城鎮西邊的平原上狩獵：繳交前先收集完爪子。",
		["Water Seekers, Thornweavers and Hunters hold the camp east of the {area:380}. The supply crates sit at its eastern end. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}. Kill Savannah Prowlers you pass for their claws."] = "鋼鬃尋水者、鋼鬃織棘者和鋼鬃獵手佔據{area:380}東邊的營地。補給箱放在營地東端。戰士：{object:58369}在營地裡。薩滿：野豬人會掉落{item:5026}。順路擊殺草原徘徊者取得爪子。",
		["Witchwing Slayers"] = "巫翼殺戮者",
		["Witchwing harpies"] = "巫翼鷹身人",
		["You arrive from {area:379}. {npc:3338} stands by the inn; {npc:3429} and {npc:3449} on the tower platform; Helbrim and {npc:3464} by the north gate; {npc:3448} at the south gate."] = "你從{area:379}抵達。{npc:3338}站在旅店旁；{npc:3429}和{npc:3449}在塔台上；藥劑師赫布瑞姆和{npc:3464}在北門旁；{npc:3448}在南門。",
		["Zhevra Runners graze on the same plains; finish the raptor heads as you go."] = "快步斑馬在同一片平原上吃草；順便收集完迅猛龍頭。",
		["Zhevra and raptors"] = "斑馬與迅猛龍",
		["grind on Witchwing Slayers at the {area:383}, {zone:1413}"] = "在{zone:1413}的{area:383}刷巫翼殺戮者",
		["{area:1898} cultists"] = "{area:1898}的祭司",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389}站在{area:380}西邊不遠的科卡爾半人馬哨站。",
		["{npc:3449}, on the tower platform: needs level 12"] = "{npc:3449}，在塔台上：需要12級",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}在往東通往{area:392}的道路旁紮營。",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}用焦油和袋子製作{item:6636}。在他旁邊的火盆使用它以顯現{npc:5893}，擊殺它取得{item:6655}，然後把餘燼放進火盆。",
		["{npc:5900} waits on the {zone:1411} bank of the {area:814}, east of the Razormane camp."] = "{npc:5900}在{area:814}的{zone:1411}岸邊等著，位於鋼鬃營地東邊。",
		["{npc:5907} stands on the ridge north of the Razormane camp, east of the {area:380}."] = "{npc:5907}站在鋼鬃營地北邊的山脊上，位於{area:380}東邊。",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}，在碼頭上",
		["{quest:881}'s lair lies south of the {area:382}, north-east of the {area:380}. Use the horn {npc:3338} gave you there to call the white lion out. Then hearth to {area:392}."] = "{quest:881}的巢穴在{area:382}南邊、{area:380}東北方。在那裡使用{npc:3338}給你的號角把白獅引出來。然後用爐石回到{area:392}。",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "在{npc:263664}的營火旁 /sit，直到獲得{spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "天空祭司安德斯和陣亡的守衛就在塔的西南方不遠處。從屍體上取得菈妮的幸運羽毛和影歌家族徽記。",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "回到{quest:92529}：奧拉凱斯風暴召喚者和{npc:251662}遍布村莊，補給貯藏箱放在房屋之間，{npc:251966}在村莊東南端等著。",
		["Back to {area:16624} with what you found."] = "帶著你找到的東西返回{area:16624}。",
		["Back to {area:16635}"] = "返回{area:16635}",
		["Back to {area:16638}"] = "返回{area:16638}",
		["Back to {npc:268592}, then west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "回去找{npc:268592}，然後向西進入{area:16623}：{npc:268605}的家在風歌蟹所在湖泊南邊的丘陵中。",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "回去找{npc:268592}。等他點燃{npc:268762}，然後在計時結束前把火焰直接帶到{area:16638}中{npc:252382}身旁的{npc:268679}。",
		["Bandit Highwaymen"] = "強盜路霸",
		["Cast {spell:1259686} near the {object:460001}"] = "在{object:460001}附近施放{spell:1259686}",
		["Climb the watchtower in the village, jump off the top and use {spell:1259416} to float down."] = "爬上村裡的瞭望塔，從塔頂跳下，使用{spell:1259416}飄落地面。",
		["Faladiel stands on the hill west of the falls, north of {area:16638}."] = "天空祭司法拉迪爾站在{area:16638}北邊、瀑布西側的山丘上。",
		["Find {npc:258130}"] = "找到{npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "沿道路向南前往島嶼中部的{area:16624}。",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "向北進入{area:16631}；{npc:257944}在森林南緣紮營。",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "向西南前往{area:17674}。{npc:252155}在塔頂；{item:254871}就在他身旁。",
		["Heal the injured druids in the Nightfang Den"] = "在Nightfang Den治療受傷的德魯伊",
		["High Order Apprentices"] = "高天盟學徒",
		["Hippogryph nests"] = "角鷹獸巢穴",
		["Horde airship"] = "部落飛艇",
		["Leave {zone:1456} by a lift and follow the road south past {area:222} and through the eastern pass into the {zone:1413}; from the pass, take the {area:458} north to the {area:380}, the Horde town in the middle of the {zone:1413}."] = "搭升降梯離開{zone:1456}，沿道路向南經過{area:222}，穿過東邊的山口進入{zone:1413}；從山口沿{area:458}向北前往{area:380}，即{zone:1413}中央的部落城鎮。",
		["Leaving {area:16635}"] = "離開{area:16635}",
		["Listen to {npc:252448}'s story"] = "聆聽{npc:252448}的故事",
		["Listen to {npc:256083}"] = "聆聽{npc:256083}",
		["Northern {zone:1412}"] = "{zone:1412}北部",
		["On the way north, back to {npc:255853} by the falls."] = "向北的路上，回到瀑布旁找{npc:255853}。",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "討厭的捲雲蜂和{npc:250873}在村莊東南方的樹林中遊蕩。",
		["Prideclaws and Galestriders"] = "群爪與逐風者",
		["Prideclaws and Galestriders share the meadows south of the village. Keep the {item:5469} for {npc:251905}; the eggs come later from the hippogryphs."] = "群爪和逐風者共同分布在村莊南邊的草地上。把{item:5469}留給{npc:251905}；蛋稍後從角鷹獸身上取得。",
		["Raw Windstones"] = "原始風石",
		["Ride north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "向東北騎往{area:17675}。奧拉凱斯營地就在它西邊，{npc:252666}在營地北端。每個教徒都可能掉落風石符咒。",
		["Sit by {npc:263664}'s campfire (type /sit) until you get the {spell:1229451} buff, then find {npc:251905} at the cook fire."] = "坐在{npc:263664}的營火旁（輸入 /sit），直到獲得{spell:1229451}增益效果，然後到烹飪火堆旁找{npc:251905}。",
		["Skyhoppers"] = "空躍者",
		["Skyhoppers hop about the fields just west of Valennia."] = "空躍者在維菈妮雅西邊不遠的田野中跳來跳去。",
		["Spread the {item:278078} off {area:1641}"] = "在{area:1641}撒下{item:278078}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "熟透的風暴蘋果和振翼蝶粉末散落在果園各處；飢餓的強盜正在洗劫果園。逐風者在果園東邊的田野吃草。損壞的構造體漂浮在果園北緣。",
		["Take the Torch of Dormant Flame to {npc:268592} at the Shrine of Flames, south-west of {area:16638} in the {area:16626}."] = "把眠炎火炬帶給{area:16638}西南方{area:16626}中、Shrine of Flames的{npc:268592}。",
		["Take the portal up to the {area:16630} and join {npc:252475} and {npc:251968} against the High Priestess."] = "搭乘傳送門上到{area:16630}，與{npc:252475}和{npc:251968}一起對抗高階女祭司洛舒娜。",
		["Take the road south-east to {area:16638}, the Skyborne town on the south coast. {npc:257006} and {npc:252448} stand at its western edge."] = "沿道路向東南前往南岸的天裔精靈城鎮{area:16638}。{npc:257006}和{npc:252448}站在城鎮西緣。",
		["Talk to {npc:251902}"] = "與{npc:251902}交談",
		["Talk to {npc:251968}"] = "與{npc:251968}交談",
		["Talk to {npc:252383}"] = "與{npc:252383}交談",
		["Talk to {npc:252800}"] = "與{npc:252800}交談",
		["Talk to {npc:253576}"] = "與{npc:253576}交談",
		["Talk to {npc:254089}"] = "與{npc:254089}交談",
		["Tell {npc:252800} you're ready"] = "告訴{npc:252800}你準備好了",
		["The Al'Aketh camp"] = "奧拉凱斯營地",
		["The Al'Aketh cultists in the camp beyond {npc:252095} carry the signet."] = "{npc:252095}後方營地裡的奧拉凱斯教徒身上帶著徽記。",
		["The Horde airship docks at the south-west edge of {area:16638}. Ride it to Kalimdor; it lands in northern {zone:1412}."] = "部落飛艇停靠在{area:16638}西南緣。搭乘它前往卡林多；它會降落在{zone:1412}北部。",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "原始風石是村莊周圍山坡上的藍色水晶。",
		["The Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "熊獸巢穴在村莊西邊。牠們的族母{npc:251115}坐在巢穴最深處。",
		["The airship"] = "飛艇",
		["The apprentices practise north-east of the village."] = "學徒們在村莊東北方練習。",
		["The bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "強盜營地在村莊東北方；『惡風』班尼克佔據最高處的營地。強盜身上帶著被偷的風石。",
		["The crawlers scuttle along the shore south-west of town."] = "風歌蟹在城鎮西南方的海岸邊爬行。",
		["The hermit lives at {area:16625}'s west shore. {item:257128} cones grow south of him; the Wind Hollows drift east of the lake."] = "隱士住在{area:16625}西岸。{item:257128}毬果生長在他南邊；風之空靈在湖的東邊飄蕩。",
		["The highland bandits"] = "高地強盜",
		["The highwaymen hold the hills north-east of the orchard. More {object:616468} lie near the road to {area:16638}."] = "強盜路霸佔據果園東北方的丘陵。更多{object:616468}在通往{area:16638}的道路附近。",
		["The hippogryph nests are north-west of the tower, west of {quest:92529}; the Matriarch sits at the western end. {item:263493} lies on the ground around them, and the hippogryphs drop the Small Eggs."] = "角鷹獸巢穴在塔的西北方、{quest:92529}西邊；角鷹獸族母在最西端。{item:263493}散落在巢穴周圍的地上，角鷹獸會掉落小蛋。",
		["The orchard"] = "果園",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "蜂后在樹林的東南端盤旋，就在你從立石回來的路上。",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "難民的財物散落在{area:16625}北岸；{npc:259013}在湖的西北端。",
		["The standing stones"] = "立石",
		["The turncoat"] = "叛徒",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "叛徒的房子在{area:16638}西北方的{area:16626}。{npc:273017}在附近等著；他的刺客潛伏在房子周圍。",
		["The watchtower"] = "瞭望塔",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629}在{area:16638}北邊。一路殺穿守衛，前往東側的{npc:253576}。",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "在{area:1641}朝南的懸崖上，對儀式墊和香爐使用{item:278078}。",
		["Walk north to {area:16624}; finish the {item:5469} on the Galestriders along the way if you are short."] = "向北走到{area:16624}；如果{item:5469}不夠，沿途擊殺逐風者補齊。",
		["Wind Hollows and {object:616467}"] = "風之空靈與{object:616467}",
		["Wind Hollows drift over the lowlands around {area:16638}. The first {object:616467} lie west of the orchard road."] = "風之空靈在{area:16638}周圍的低地上飄蕩。第一批{object:616467}在果園道路的西邊。",
		["Windsong Crawlers"] = "風歌蟹",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "你將永遠離開這座島。{npc:259119}在飛艇降落處等著。",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "你在島嶼北部的{area:16635}醒來。{npc:251362}站在小徑旁，{npc:251361}在村莊中央。",
		["search the dead cultist in the house"] = "搜查房子裡死去的教徒",
		["search the wardrobe"] = "搜查衣櫃",
		["talk to {npc:251684}"] = "與{npc:251684}交談",
