		["{item:278083}, from {npc:3027}"] = "{item:278083}，向{npc:3027}購買",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363}站在村莊東邊的{area:17678}。{npc:251143}和奧拉凱斯皈依者聚集在她北邊不遠處。{object:460001}就在她的東北方：在它旁邊施放你的種族技能{spell:1259686}。",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}."] = "{npc:250926}在村莊西南方的山坡上徘徊，就在前往{npc:252095}的路上。",
		["{npc:251361}'s errands"] = "{npc:251361}的差事",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}：訓練師留給你的字條",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}：檢查{item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}：閱讀{item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}：{item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "德魯伊訓練師{npc:251373}，在{npc:251361}身後那棵樹的底層",
		["{npc:251374} sends you to the {area:16988}, just east of the village: drink the {item:6635} there to see the {npc:251166}, then take the {item:6656} back to him."] = "{npc:251374}派你前往村莊東邊不遠的{area:16988}：在那裡喝下{item:6635}以看見{npc:251166}，然後把{item:6656}帶回給他。",
		["{npc:251374} stands in the village."] = "{npc:251374}站在村莊裡。",
		["{npc:251374}, at the village centre"] = "{npc:251374}，在村莊中央",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}：{npc:5873}和你的{item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}，在瞭望塔內",
		["{npc:251964}, in the watchtower"] = "{npc:251964}，在瞭望塔內",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it."] = "{npc:252095}在村莊西南方的{area:16622}等你。奧拉凱斯營地就在她後方；由{npc:256935}率領。",
		["{npc:252359} stands on {area:16638}'s east side."] = "{npc:252359}站在{area:16638}的東側。",
		["{npc:252377} stands in the middle of {area:16638}."] = "{npc:252377}站在{area:16638}中央。",
		["{npc:252382} stands on {area:16638}'s west side."] = "{npc:252382}站在{area:16638}的西側。",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:252389} in {area:16638} hands you a {item:15908} three times: tame a {npc:254588} by the lakes north-west of town, an {npc:251707} in the fields west of town and a {npc:250874} at {area:16663}, returning to her after each. {npc:254411} stands beside her."] = "{area:16638}的{npc:252389}會三次交給你{item:15908}：馴服城鎮西北方湖邊的一隻{npc:254588}、城鎮西邊田野中的一隻{npc:251707}，以及{area:16663}的一隻{npc:250874}，每次完成後回去找她。{npc:254411}站在她身旁。",
		["{npc:252448} and {npc:256083}"] = "{npc:252448}與{npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}、{npc:258130}和{npc:258134}在{npc:257944}東邊的教派營地。{npc:254151}站在營地邊緣。哈利安也會掉落{quest:94490}：閱讀它以開始下一個任務。{quest:94489}：進入Nightfang Den，治療7名受傷的德魯伊並找到{npc:258130}。",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}潛伏在村莊南邊的群爪之間。{npc:254589}是精英：建議組隊。",
		["{npc:255853} waits by the falls just north of the watchtower."] = "{npc:255853}在瞭望塔北邊不遠的瀑布旁等著。",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083}站在城鎮西北方不遠的{area:16626}。",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247}在{area:16638}北邊、通往{area:16629}的路上等著。",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196}在神殿西側持有{item:263993}。",
		["{npc:257944} again"] = "再次找{npc:257944}",
		["{npc:257944}, last time"] = "最後一次找{npc:257944}",
		["{npc:258443} roams the slopes just south of the turncoat's house."] = "{npc:258443}在叛徒房子南邊不遠的山坡上遊蕩。",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "降落處旁的{npc:259118}：給{zone:1456}的{npc:3033}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}：先留著，{zone:1454}的索爾要再過兩份指南才會用到",
		["{npc:263664}'s campfire"] = "{npc:263664}的營火",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛頭人的薰香：向草藥商{npc:3014}、附魔供應商{npc:3012}、製皮供應商{npc:3005}和烹飪供應商{npc:3027}購買四種材料，然後合成{item:278078}。",
		["{npc:3033} trains druids on {area:1639}. He teaches you {spell:18960}; {npc:11802}'s welcome waits for your {spell:499} trip at about 23 (forever/horde/04-the-barrens)."] = "{npc:3033}在{area:1639}訓練德魯伊。他會教你{spell:18960}；約23級進行{spell:499}之旅時，{npc:11802}的歡迎在等著你（forever/horde/04-the-barrens）。",
		["{npc:3615}, the wind rider master"] = "雙足飛龍管理員{npc:3615}",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529}在申德村南邊。{npc:257065}在村子邊緣與你會面；搜查他身後房子裡的衣櫃。",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "在Kaga的營火旁 /sit，直到獲得{spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "向東回到{area:358}：刺背薩滿站在那裡的野豬人之間。",
		["Back south-east to the {area:396}."] = "向東南回到{area:396}。",
		["Back to Bloodhoof"] = "返回血蹄村",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "回到營地找{npc:5888}。{npc:5891}在營地東邊的平頂山上等著：在那裡喝下{item:6635}才能看見它，然後把{item:6656}帶回給先知。",
		["Back west to the camp."] = "向西回到營地。",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "鬥豬在神殿北邊吃草；刺背野豬人佔據東北方的峽谷。{npc:8554}站在峽谷東端，{object:3076}就在營地的地上。",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods."] = "施放{spell:18960}。{npc:11802}在{area:2361}；{quest:5930}在西北方的樹林中。",
		["Class turn-ins in {area:1638}"] = "{area:1638}的職業任務繳交",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "向西北經過{zone:1456}，前往{zone:1412}最北邊的{area:398}。",
		["Finish the wolf heart, cougar femur, plainstrider scale and swoop gizzard on the plains around the village."] = "在村子周圍的平原收集完狼心、山獅股骨、平原陸行鳥鱗片和猛鷲砂囊。",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "沿小徑向南出營地，前往山腳下灰舌先知的帳篷。",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}."] = "沿道路從{area:220}向北走。{npc:265810}在{area:222}南邊不遠的路上等著；在她的營火旁 /sit，直到獲得{spell:1229451}。",
		["Galak centaurs"] = "加拉克半人馬",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "向北前往{zone:1456}東邊的{area:225}。{npc:3233}站在岩石底部；刺背干涉者在墓地挖掘，{npc:2994}在頂上等著。",
		["Hearth to {area:222} and ride north to {area:1639}."] = "用爐石回到{area:222}，向北騎到{area:1639}。",
		["Leave {zone:1412} by the south-eastern pass and follow the road to the {area:380}. {quest:860} stands by the inn, {npc:3448} at the south gate. {zone:1413} guide starts here."] = "從東南方的山口離開{zone:1412}，沿道路前往{area:380}。{quest:860}站在旅店旁，{npc:3448}在南門。{zone:1413}指南從這裡開始。",
		["Plainstriders roam the grass all around the camp."] = "平原陸行鳥在營地周圍的草地上遊蕩。",
		["Prairie Wolf Alphas"] = "草原狼前鋒",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "草原狼前鋒在{npc:275789}和東邊加拉克營地周圍的平原上，混在狼群之中遊蕩。",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "草原狼和成年平原陸行鳥在村子周圍的平原遊蕩。",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "搭升降梯上到平頂山。{npc:2995}在中央高台照料雙足飛龍；{npc:3057}站在那裡的大帳篷裡。",
		["Ride down to {area:222} and tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a Swoop to the north-west."] = "騎下山到{area:222}，用{item:15908}馴服：平原上的一隻{npc:2956}、村子北邊的一隻{npc:2959}，以及西北方的一隻猛鷲。",
		["Speak with {npc:3067}"] = "與{npc:3067}交談",
		["Spread the {item:278078} off {area:1641}"] = "在{area:1641}撒下{item:278078}",
		["Swoops glide over the plains all around Bloodhoof."] = "猛鷲在血蹄村周圍的平原上空滑翔。",
		["Tame it with the {item:15908}"] = "用{item:15908}馴服牠",
		["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "加拉克半人馬在水井東邊的平原紮營；由{npc:275767}率領。",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "白鬃豺狼人佔據{area:818}，位於挖掘場南邊、血蹄村西邊。{npc:272203}被關在他們的營地裡：帶他出來。",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "風怒鷹身人佔據水井北邊和西邊的{area:819}。",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "{area:404}的矮人身上帶著勘察員的鋤頭。在挖掘場裡矮人的熔爐砸毀它們。",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "哥布林在水井東北方丘陵的礦坑工作。{quest:765}站在礦坑深處；他的{item:281031}會開啟{quest:98424}，其他書頁在礦坑裡。",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "薰香十分鐘就會燒完：沿南邊的丘陵直接向東跑到{object:660739}。",
		["The shrine of An'she and Mu'sha"] = "安希與Mu'sha的神殿",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "石頭位於離開{zone:1412}的山口，就在你往東的路上。在那裡使用{item:15710}並擊敗月爪梟獸。",
		["The well lies north of the village. Well Stones sit around the well, {object:2912} lies under the trees nearby. Kill wolves, cougars, plainstriders and swoops on the way for {quest:766} and {quest:761}."] = "水井在村子北邊。水井石放在井的周圍，{object:2912}在附近的樹下。途中擊殺狼、山獅、平原陸行鳥和猛鷲，完成{quest:766}和{quest:761}。",
		["The well lies south-east of the village."] = "水井在村子東南方。",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "失事的商隊在半人馬西北方、通往{zone:1456}的道路東邊。",
		["The {object:177525}"] = "{object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "在{area:1641}朝南的懸崖上，對儀式墊和香爐使用{item:278078}。",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "你從{area:221}的平頂山開始。{npc:2980}和鷹風酋長站在中央的大帳篷旁。",
		["{item:278079}, from {npc:3014}"] = "{item:278079}，向{npc:3014}購買",
		["{item:278080}, from {npc:3012}"] = "{item:278080}，向{npc:3012}購買",
		["{item:278081}, from {npc:3005}"] = "{item:278081}，向{npc:3005}購買",
		["{item:278083}, from {npc:3027}"] = "{item:278083}，向{npc:3027}購買",
		["{item:4703}, at the digsite forge"] = "{item:4703}，在挖掘場的熔爐旁",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}：平原徘徊者在{area:225}周圍的平原遊蕩",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛頭人的薰香：向草藥商{npc:3014}、附魔供應商{npc:3012}、製皮供應商{npc:3005}和烹飪供應商{npc:3027}購買四種材料，然後合成{item:278078}。",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "{npc:275789}站在水井東邊不遠的{area:821}。",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182}站在村子北緣。Kyle想要從平原陸行鳥取得的{item:287505}。",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}，在村子北端",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}，給{zone:1456}的大德魯伊哈繆爾·符文圖騰",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984}站在{area:404}邊緣，水井南邊。",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988}在血蹄村東南方的{area:396}旁紮營。",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991}坐在營地東緣的帳篷旁；{object:2907}就在她旁邊。",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}，給{zone:1456}的{npc:3057}",
		["{npc:3059}, the warrior trainer"] = "戰士訓練師{npc:3059}",
		["{npc:3060}, the druid trainer beside him"] = "他旁邊的德魯伊訓練師{npc:3060}",
		["{npc:3061}, the hunter trainer"] = "獵人訓練師{npc:3061}",
		["{npc:3062}, the shaman trainer in camp"] = "營地裡的薩滿訓練師{npc:3062}",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}的任務：在他旁邊擊敗三名新戰士（或在決鬥中擊敗玩家）。",
		["{npc:3209}, next to {npc:2980}"] = "{npc:3209}，在{npc:2980}旁邊",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}：給{area:380}的{quest:860}",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}：給{area:380}的{npc:3448}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888}站在{area:221}。{quest:1516}需要4級，在這裡繳交任務就能達到。",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}：{npc:5873}和你的{item:5175}",
		["{npc:6746} on the central rise sends you to {npc:3033} on {area:1639}."] = "中央高台的{npc:6746}會派你去{area:1639}找{npc:3033}。",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775}站在營地西端，山獅出沒的丘陵西北角：接他的任務，從那裡往南和往東獵殺山獅，然後回到{npc:2980}那裡。",
		["{quest:96130} and {quest:756}"] = "{quest:96130}與{quest:756}",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "孤狼{quest:96130}在村子西邊的平原徘徊。草原捕食者和平原獅在村子北邊和西邊的平原遊蕩。",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "在她的營火旁/sit，直到獲得{spell:1229451}",
		["Ask {npc:10666} for his report"] = "向{npc:10666}索取報告",
		["Ask {npc:1496} for his report"] = "向{npc:1496}索取報告",
		["Ask {npc:251001} for his report"] = "向{npc:251001}索取報告",
		["Back to the church"] = "回到教堂",
		["Back to {area:154}"] = "返回{area:154}",
		["Back to {area:159}."] = "回到{area:159}。",
		["Back up the road to {area:159}."] = "沿路回到{area:159}。",
		["Balnir graves"] = "巴尼爾墓地",
		["Beat {npc:6784} in the duel"] = "在決鬥中擊敗{npc:6784}",
		["Crusader's Outpost"] = "十字軍前哨",
		["Dry Branches"] = "乾樹枝",
		["Duskbats and Darkhounds roam all along the road back west; finish the wings and hides on the way."] = "夜行蝙蝠和黑暗犬在往西的回程道路沿線遊蕩；順路把翅膀和外皮收集完。",
		["Eleanor camps just south-west of town."] = "她在城鎮西南方紮營。",
		["Escort {npc:275954} out of the outpost"] = "護送{npc:275954}離開前哨",
		["Fields west of {area:159}"] = "{area:159}西邊的田野",
		["Follow the path north into {area:154}; Sarvis stands in front of the church."] = "沿著小路向北進入{area:154}；薩維斯站在教堂前。",
		["Follow the road east to {area:159}. {npc:10665} stands at the north-west edge of town; the {area:2119} is the big inn in the middle, with {npc:1515} in front of it."] = "沿著道路向東前往{area:159}。{npc:10665}站在城鎮西北邊緣；{area:2119}是鎮中央的大旅店，{npc:1515}就在門前。",
		["Follow the road east. Bleeding Horrors and Wandering Spirits haunt the graves on the east side of the farmstead, where the {quest:99142} grows."] = "沿著道路向東。可怕的血殭屍和遊蕩的幽靈在農場東側的墓地出沒，{quest:99142}就生長在那裡。",
		["Follow the road north-east from {area:159} past {area:162}. {npc:1665} and his two Scarlet Bodyguards hold the Scarlet watchtower on the north-east coast, north of the {area:459}: pull the bodyguards first."] = "沿著道路從{area:159}向東北經過{area:162}。{npc:1665}和他的兩名血色保鏢佔據東北海岸的血色十字軍瞭望塔，位於{area:459}北邊：先把保鏢拉開。",
		["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}. From here on, kill the Duskbats and Darkhounds you pass: {npc:3549} wants their wings and hides."] = "沿著道路向西北前往{area:157}。{npc:1657}在磨坊南邊的墓地走動；妮薩、格里高和{npc:1656}則在磨坊內徘徊。斷骨骷髏和碎顱士兵會掉落肋骨，暗眼骷髏法師掉落頭骨，牠們都可能掉落{item:2839}。從現在起，擊殺沿途遇到的夜行蝙蝠和黑暗犬：{npc:3549}要牠們的翅膀和外皮。",
		["Follow the road south back to {area:159}."] = "沿著道路向南回到{area:159}。",
		["Follow the road south-east from {area:159} past the zeppelin towers. Linnea, Kristof and {npc:3549} camp by the road."] = "沿著道路從{area:159}向東南經過飛艇塔。林奈、克里斯多夫和{npc:3549}在路旁紮營。",
		["Follow the road south-west from {area:159} to the Scarlet Crusade camp. {npc:1662} stands at its south end; every Scarlet there can drop a ring."] = "沿著道路從{area:159}向西南前往血色十字軍營地。{npc:1662}站在營地南端；那裡的每個血色十字軍都可能掉落戒指。",
		["Follow the road west past {area:157} to the {area:16616}. Leonid stands just north of {npc:246389}'s camp."] = "沿著道路向西經過{area:157}前往{area:16616}。萊尼德站在{npc:246389}營地北邊。",
		["Free six Webbed Victims inside the cave for {npc:244808}"] = "為{npc:244808}解救洞內六名被蛛網纏住的受害者",
		["Greater Duskbats"] = "巨型夜行蝙蝠",
		["Greater Duskbats fly over the fields around {area:159} and along the road north."] = "巨型夜行蝙蝠在{area:159}周圍的田野上空以及北邊的道路沿線飛行。",
		["Head west into the {area:16616}; {npc:246389} and {npc:259190} camp at its edge."] = "向西進入{area:16616}；{npc:246389}和{npc:259190}在森林邊緣紮營。",
		["Head west to the cave. The Young Night Web Spiders sit outside; the Night Web Spiders and the Webbed Victims are inside."] = "向西前往洞穴。小夜行蜘蛛在洞外；夜行蜘蛛和被蛛網纏住的受害者在洞內。",
		["Hearth to {area:159}"] = "用爐石回{area:159}",
		["Leave {area:154} by the road north-east. {npc:6784} stands by the farmhouse at the {area:156}."] = "沿著東北方的道路離開{area:154}。{npc:6784}站在{area:156}的農舍旁。",
		["Listen to Leonid and {npc:246378}, then talk to him again"] = "聽萊尼德和{npc:246378}交談，然後再和他說話",
		["Mindless Zombies"] = "無腦的殭屍",
		["More Vile Fin murlocs walk the shore just north of the outpost."] = "更多的邪鰭魚人在前哨北邊的海岸走動。",
		["Offer aid to the {npc:246143}"] = "向{npc:246143}伸出援手",
		["Only if the letter dropped"] = "僅限信件有掉落時",
		["Paladin: {area:16616}"] = "聖騎士：{area:16616}",
		["Paladins: {quest:90902} is done once you have healed five {npc:259377} around the church with {spell:635}."] = "聖騎士：用{spell:635}治療教堂周圍五名{npc:259377}後，{quest:90902}即完成。",
		["Rattlecage Skeletons wander the ruined houses in the north half of {area:154}. Young Scavengers and Duskbats roam all around the village; the Ragged Scavengers and Mangy Duskbats are on its east side."] = "斷骨骷髏在{area:154}北半部的廢墟房屋間遊蕩。小食腐狼和夜行蝙蝠在村莊各處遊蕩；蓬毛食腐狼和癩皮夜行蝙蝠在村莊東側。",
		["Rattlecage skulls"] = "斷骨骷髏的頭骨",
		["Rattlecages, scavengers and duskbats"] = "斷骨骷髏、食腐狼和夜行蝙蝠",
		["Rot Hide graveyards"] = "腐皮豺狼人的墓地",
		["Scarlet Warriors guard the outpost just west of the pumpkin fields. {npc:275954} is held inside: talk to him and stay with him until he is out."] = "血色戰士守衛著南瓜田西邊的前哨。{npc:275954}被關在裡面：和他交談，一直陪著他直到他脫困。",
		["Take the road south-east out of {area:159}; Terrence stands on it short of the zeppelin towers."] = "沿著東南方的道路離開{area:159}；特倫斯站在路上，在飛艇塔之前。",
		["Talk to {npc:265944}"] = "與{npc:265944}交談",
		["The Dry Branches lie on the ground around the south-west edge of {area:159}."] = "乾樹枝散落在{area:159}西南邊緣周圍的地上。",
		["The Rattlecage Skeletons in the ruined houses drop the skulls."] = "廢墟房屋中的斷骨骷髏會掉落頭骨。",
		["The Rot Hide Graverobbers dig through the graveyards north of {area:159}; all the Rot Hides drop the ichor."] = "腐皮盜墓賊在{area:159}北邊的墓地挖掘；所有腐皮豺狼人都會掉落膿液。",
		["The Rot Hide Mongrels hold the hills further north. {npc:1753} (level 11) stands in their camp on the hill south of the shore: clear the gnolls around him first."] = "混血腐皮豺狼人佔據更北邊的山丘。{npc:1753}（等級11）站在海岸南邊山丘上的營地裡：先清掉他周圍的豺狼人。",
		["The Scarlet Converts and Initiates hold the farm east of {area:154}. {npc:1919} wanders between the farmhouses: his remains are for {quest:6395}."] = "血色信徒和血色新兵佔據{area:154}東邊的農場。{npc:1919}在農舍之間遊蕩：他的遺骸用於{quest:6395}。",
		["The Scarlet Friars camp just north-east of the graves; {npc:1664} stands among them."] = "血色苦行修士在墓地東北方紮營；{npc:1664}站在他們之中。",
		["The Scarlet camp"] = "血色十字軍營地",
		["The Scarlet farm"] = "血色十字軍農場",
		["The Vile Fin murlocs line the north shore."] = "邪鰭魚人分布在北岸。",
		["The Wanted poster by the inn"] = "旅店旁的通緝告示",
		["The spiders lurk in the woods at the far east end of the glades."] = "蜘蛛潛伏在林地最東端的樹林裡。",
