t.guides["forever/reputation/argent-dawn"] = (function() return {
		["Argent Dawn Reputation"] = "銀色黎明聲望",
		["Corruptor's Scourgestones and dungeons to Revered"] = "墮落者的天譴石與地城到崇敬",
		["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "黑暗教徒和暗影法師（58-60級）在這裡會掉落侵略者的天譴石，還有爪牙的天譴石和{item:14047}。侵略者的每次10個、爪牙的每次20個交給{area:2268}的{npc:11039}。在經典版中，兩者到尊敬後就不再提供聲望。",
		["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "從尊敬開始，墮落者的天譴石（每次繳交一個）和在{area:2279}及{area:2057}擊殺天譴軍團可提升聲望。墮落者的天譴石由那裡的天譴首領（{npc:1853}、{npc:10433}、維克圖斯）以及{zone:1422}的{npc:1852}和普特迪烏斯掉落。多跑地城比任何野外刷怪都快。",
		["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:152}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "{zone:1422}各處的食屍鬼和骷髏約有一半機率掉落爪牙的天譴石；這一帶很密集。每次20個交給任一銀色黎明軍官（{area:3197}的普爾哈特、{area:152}的加魯什、{area:2268}的{npc:11039}）。每次繳交也會得到一個{item:12844}，可在銀色黎明軍需官處使用。",
		["Invader's Scourgestones to Honored"] = "侵略者的天譴石到尊敬",
		["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "持續跑{area:2279}和{area:2057}，並在{area:2268}繳交每一個{item:12843}，直到崇拜。",
		["Minion's Scourgestones to Friendly"] = "爪牙的天譴石到友好",
		["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "跑{area:2279}（兩個區域）和{area:2057}，擊殺沿途每一隻天譴軍團。",
		["{faction:529} to Exalted"] = "{faction:529}到崇拜",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:152} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}初始為中立。向{area:152}的{npc:10839}領取委任狀並裝備：在經典版中，只有裝備{quest:5401}飾品時才會掉落天譴石。Forever的傳承外交官天賦可提高聲望獲取。",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160}初始為中立。向{area:3197}的{npc:10840}領取委任狀並裝備：在經典版中，只有裝備{quest:5401}飾品時才會掉落天譴石。Forever的傳承外交官天賦可提高聲望獲取。",
		["{quest:5401} (Alliance)"] = "{quest:5401}（聯盟）",
		["{quest:5401} (Horde)"] = "{quest:5401}（部落）",
} end)()
t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "深淵紋章、深淵徽記和深淵節杖在完成各自的開頭任務後，就能在{npc:15306}處重複繳交。",
		["Back to {area:3425}"] = "返回{area:3425}",
		["Cenarion Circle Reputation"] = "塞納里奧議會聲望",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "暮光加密文件可重複：{npc:15306}會一再收取更多文件。教徒營地是收集它們的地方。",
		["Encrypted Twilight Texts to Friendly"] = "暮光加密文件到友好",
		["From here on, the {area:3454} raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation."] = "從這裡開始，{area:3454}團隊副本和深淵議會的繳交物（紋章、徽記、節杖）提供大部分聲望。",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "繼續在暮光營地刷。穿上暮光服飾（暮光教徒套裝加上身份勳章，來自{npc:15282}的身份勳章任務）就能在風之石召喚深淵聖殿騎士；牠們的深淵紋章交給{npc:15306}。",
		["Keep running the {area:3454} and turning in Abyssal Council insignia until Exalted."] = "繼續打{area:3454}並繳交深淵議會的徽章，直到崇拜。",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "暮光之錘教徒佔據{zone:1451}西部的營地。{quest:8320}和暮光喚石者混雜在這裡；任何教徒都可能掉落{item:20404}。每擊殺一個教徒也會計入{faction:609}聲望。只有在你60級並接了{quest:8320}時，擊殺地王才會計入該任務。",
		["{area:3425} is the walled town in north-central {zone:1451}. Bor and {npc:15270} stand together inside. The {faction:609} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:3425}是{zone:1451}中北部有圍牆的城鎮。鮑爾和{npc:15270}一起站在裡面。{faction:609}一開始是中立。Forever的傳承外交官天賦可提高聲望獲取。",
		["{faction:609} to Exalted"] = "{faction:609}到崇拜",
		["{faction:609} to Honored"] = "{faction:609}到尊敬",
		["{faction:609} to Revered"] = "{faction:609}到崇敬",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306}：暮光加密文件",
		["{quest:8320} needs level 60"] = "{quest:8320}需要60級",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "黑暗教徒和暗影法師（58-60級）在這裡會掉落；在這裡每擊殺一隻天譴軍團也會計入{object:92525}（見該指南）。拍賣場也買得到。",
		["Darkspear Trolls Reputation"] = "暗矛食人妖聲望",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "砂槌巨魔（45-48級）在這裡會掉落。拍賣場也買得到。",
		["Keep handing in {quest:7837} until {faction:530} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "持續繳交{quest:7837}，直到{faction:530}崇拜。{item:14047}：{zone:1423}的黑暗教徒和暗影法師（58-60級），或拍賣場。",
		["Keep handing in {quest:7837}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "持續繳交{quest:7837}，每次20個{item:14047}。{item:14047}：{zone:1423}的黑暗教徒和暗影法師（58-60級），或拍賣場。",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "科卡爾半人馬（30-33級）在這裡會掉落。拍賣場也買得到。",
		["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "{area:381}的風險投資公司執行者（16-17級）在這裡會掉落。拍賣場也買得到。",
		["{npc:14727} takes cloth for {faction:530} in the {object:172961}, {zone:1454}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7837} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14727}在{zone:1454}的{object:172961}收取布料以提升{faction:530}聲望。毛料、絲綢、魔紋布和{item:14047}的首次捐獻（各60塊布）只能做一次，每塊布給的聲望最多；之後{quest:7837}可重複到崇拜。與其他種族主城崇拜後，可購買該種族的坐騎。Forever的傳承外交官天賦可提高聲望獲取。",
		["{npc:14727}: {item:14047} delivered"] = "{npc:14727}：{item:14047}已交付",
		["{quest:7837} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837}每次繳交需要20個{item:14047}，可無限次重複。以20的倍數攜帶{item:14047}，一次全部連續繳交。{item:14047}：{zone:1423}的黑暗教徒和暗影法師（58-60級），或拍賣場。",
		["{quest:7837} to Exalted"] = "{quest:7837}到崇拜",
		["{quest:7837} to Honored"] = "{quest:7837}到尊敬",
		["{quest:7837} to Revered"] = "{quest:7837}到崇敬",
} end)()
